window.WIKI.push(
/* ---------- 总览 ---------- */
{id:'v_void', n:'虚空', c:'地理', m:'void', r:'void', e:[6,7,8,9,10,11,12,13], p:[0,0,0], k:'core', kp:{r:160,c:'#8fb8ff'},
 s:'星星之间的一切。在琳看来，虚空其实就是一片大得没边的海。',
 d:'卷六以后，故事离开了绒球。琳靠传送、星游者、各种兵种在虚空中旅行，见到无数的“翻滚者”（星球）和活着的世界。这张地图把每个时代去过的地方放在一片星区里，按故事先后排开——它们之间真正的距离，往往远到无法想象。\n卷八揭开了虚空更早的样子：正常虚空和凝固虚空原是一体的“虚空本源”，分裂时留下的大量碎块成了虚空隧道的空间；星理者还相信所有虚空都是一个不断膨胀的大气泡，终会裂成许多小泡。碰撞之后，琳把虚空分成四种状态：偏正常、偏凝固、一体的本源，以及打碎又拼起、混着“杂质”的融合状态——它觉得最后这种最容得下现在的生物。\n卷八末尾补上了虚空的“底”：虚空之间会分裂也会融合，分裂时掉下的空间碎末一直沉向最深处，在那里聚成了虚空之眼的虚空。它一度被认为是最远的虚空，直到琳在它的尽头连上一个和以往任何虚空都没有关系的新虚空。',
 ch:'卷六《虚空惊遇》《恒星环绕者》《出发@495》《路途》《连接的世界》《捕获者》卷八《感觉》《另一部分》《内部的意识》《汇聚》《正常化》卷八《虚空的粉末》《最深处》《最后的瞬间》', rel:['v_rongqiu','v_ximin','v_starbus','v_erxi','v_midgard','j1_benyuan','j1_maodian','j1_jilu','j3_eyevoid','j3_end']},
/* ---------- 星区 6 ---------- */
{id:'v_rongqiu', n:'绒球（从虚空看）', c:'地理', m:'void', sec:6, e:[6,7,8,9,10,11,12], p:[-560,0,300], k:'planet', kp:{r:60,tex:'earth',c1:'#2f7a43',c2:'#1b5f7c',atm:'#5fa8ff',moon:1}, go:'rongqiu',
 s:'琳的母星：从虚空望去是一颗蓝色翻滚者，与尔什和另一颗世界同属一体。',
 d:'从虚空里看，绒球是悬在星空中的一颗蓝色翻滚者，旅途从这里出发，琳也始终在它各处留着兵种，看着整个世界的演变。月本是一头恒星巴士，它突然出现在绒球旁边时本该悄无声息地融入引力平衡，可体内器官受过伤，这份能力残缺不全，结果让绒球上的鸣石纷纷飞上天空；天色随之变得异样，骸龙首领和苏苏米站在最高的树顶上望着天，向绒球雕像祈求庇护。月恢复以后，就该告别绒球，动身前往远方的恶魔翻滚者了。卷六以后，绒球上依旧故事不断：南之大陆的脑灵、浓雾与结晶、血雾大师……\n来自虚空的威胁也曾逼到它门前。教团代表蒸腾者让始境去攻打绒球，要把镜世界里的改造装置整套搬到绒球上；蒸腾者又把镜世界推进一条岩石般的隧道，送到绒球近旁；那颗结晶世界在绒球的夜空里亮得像一块巨大的宝石，山顶喷出的光柱直射过来，弹幕如流星般落下，北之大陆和周围海里的庞然大物破土出海去拦截，最后是琳的恒星巴士挡在前面，把镜世界一路拖离了绒球。蒸腾者还打过把整颗绒球蒸发掉的主意，想借此逼琳接手它们的伟大工程。\n在远离它的地方，也留着绒球的痕迹：凝固虚空里有一群琳叫作“迷球”的飘浮生物，曾“看见”过绒球的丛林和生物，照样搭出一模一样的房屋，连火把也摆上；绒球泉眼旁的气蚁肚子里装着恐龙大陆丛林的空气。琳在绒球所在的位置挖出了许多能容下整颗世界的空间，尔什也启程前往绒球的星系；离那个星系约一个尔什昼夜光程的一处虚空，却让预知巴士器官里的意识感到莫名的恐惧。\n绒球的来历也在这几卷里慢慢揭开。碎影和领队那一辈的旅者记得，遥远之影的意识曾聚在一颗几乎没有生命的世界上，那就是绒球；它和另外两颗翻滚者处在一种“同步状态”，三处的生物一起演化，其中一颗却在慢慢毁灭，领队回来时那股意识也已消失不见。莎琳后来告诉琳：这三颗世界其实就是尔什本身——三个世界共用一个意识，一颗是尔什，一颗是绒球，第三颗被尔什把意识压缩藏了起来；琳诞生于遥远之影和莎琳意识的碰撞，又掺进了尔什的影响，因此琳自己也算是那第三颗世界。莎琳还猜测，脆弱却能“记录”的细胞生物，正是尔什创造的。点“进入地图”回到这颗星球。',
 ch:'卷六《降临》《异色的天际》《集合》《管道》《接近@1281》《晃动@1282》《拖动》《结束……了？》《新的适应目标》《观察世界》《泉眼@2491》《建造@2666》卷七《规则》《成员》《联系》《回归》', rel:['rongqiu','moon_bus','rq_south','lin','v_erxi','shalin','bk_shadow','v_jing','v_starbus','v_zhengteng','ng_quanyan','qiyi']},
{id:'v_ximin', n:'虚民母球（从虚空看）', c:'地理', m:'void', sec:6, e:[5,6,7], p:[0,0,0], k:'planet', kp:{r:55,tex:'metal',c1:'#7c858c',c2:'#3a4a55',lights:'#ffd27a',atm:'#9fb6c8'}, go:'ximin',
 s:'一颗被金属覆盖的世界。夜面亮满了城市的灯。',
 d:'漂泊号载着琳的间谍回到这里，卷六由此开始。',
 ch:'卷五《随机之星》卷六《第一步》', rel:['xm_planet','v_nuowa']},
{id:'v_nuowa', n:'诺瓦矿场 · 瓦砾之海', c:'地理', m:'void', sec:6, e:[6], p:[300,-20,-300], k:'rocks', kp:{r:170,n:220,s:5,c:'#8a7a68',star:'#ffd890',ring:1},
 s:'虚民太阳周围的陨石圈，一处“无法地带”。',
 d:'开往诺瓦矿场的列车上，悦耳的女声广播提醒乘客：准备好随身武器，做好上战场的准备，遇到歹徒、土匪、海盗、盗贼请全力反击，不要留情。车厢里多数虚民倒还平静，只有一位被一圈黑衣部下围着、称作“老大”的虚民看着不好惹。诺瓦矿场是最远的空间站：虚民的太阳周围漂浮着一圈被称为“瓦砾之海”的陨石带，矿场最初就是为了在这里寻找矿物而建的。后来这里掀起太空淘金热，海盗横行，一大堆不遵守法律的虚民聚集于此，有的甚至从没回过母球。',
 ch:'卷六《虚空中的矿场》《太空淘金热》', rel:['v_ximin','xumin']},
{id:'v_starbus', n:'恒星巴士 · 星球要塞', c:'地理', m:'void', sec:6, e:[6,7,8,9,10,11,12,13], p:[-380,60,-330], k:'planet', kp:{r:72,tex:'flesh',c1:'#6a8a52',c2:'#8a4a3a',atm:'#bfe6a0',veins:1},
 s:'绕着恒星生长的巨大古老生物——本身就是一个活着的世界。琳把它变成了自己的基地。',
 d:'母体把幼仔丢到恒星附近数十公里大的飘浮石头上，幼仔最初是史莱姆一样的变形虫，吸收石头的资源，在自己身上慢慢长出一个微型环境，最后合并成一体、渗进石头把它整个转化——上千年后长成直径数十公里的世界。它身上的生物怕冷，所以它总是绕着恒星生活，琳就叫它“恒星巴士”；它也能传送，但每传送一次要冷却几百年。琳最早遇到它时还以为是一颗普通的“冰雪翻滚者”：阿特兰曾在这颗世界上定居，脑灵来袭时躲进地下避难所；巴士被打伤后逃离原处，流浪到没有恒星的地方，地表冻结，地下生物也在慢慢消亡。琳在地下看到它用植物当眼睛记录下的历史，又找来“愈石”喂给它的进食器官，治好了受损的神经。它苏醒后满心复仇，冲向黑金属的岛屿要同归于尽，最终击毁了那些岛屿，自己也被炸得满是螺旋形的深坑；之后成了琳的“星球要塞”，在攻打脑灵核心时替舰队硬扛了漫天的光团，表层被削薄了一圈。成熟的恒星巴士会去和同类接触，老了则聚到一起，用门彼此相连。\n卷八古战场的传说里，也有一头恒星巴士为了对抗从虚空裂口涌出的疯狂生物，造出一种能吞物质、长武器、在战争中不断进化的生物。',
 ch:'卷六《冰雪世界的深处》《世界的最后》《恒星环绕者》《治愈的方法》《复仇》《巨星之战》《星球要塞》《战争统计》卷八《感觉》', rel:['v_yushi','v_spike','moon_bus','v_xukongbus','v_icerolly','v_atlan','v_lianjie','j1_guzhan']},
{id:'v_spike', n:'尖刺林地 · 鼹 · 蒙奇', c:'地理', m:'void', sec:6, e:[6], p:[-300,0,-250], k:'none',
 s:'恒星巴士地底的荆棘丛林。',
 d:'鼹是这里的掠食者。鼹原本有四足着地和站立的两种，其中一种被夜里出没的生物——恒星巴士的免疫系统——灭绝了，留下的鼹至今每天用嘴拱土堵住洞穴；像莫斯一样、手特别像、因为冷而多了些毛的“蒙奇”是它们的猎物。勇者也在这里冒过险。巴士苏醒之后，丛林被岩石掩埋又清理出来，只剩满地植物残骸和一扇三米多高的大门。',
 ch:'卷六《地下的奥秘》《地下的夜晚》《我感觉得到》《监狱@86》《星球要塞》', rel:['v_starbus','c_hero']},
{id:'v_yushi', n:'愈石 · 巴士墓地', c:'地理', m:'void', sec:6, e:[6,7], p:[-640,-40,-120], k:'rocks', kp:{r:110,n:60,s:12,c:'#d8f4e8',glow:'#8affc0',shards:1},
 s:'能治好恒星巴士神经的石头，出自一颗没有恒星的“愈石之星”；而年老的恒星巴士会聚在“巴士墓地”。',
 d:'恒星巴士受损的是混合结构的神经，里面有稀有材料，需要“愈石”才能修复。琳循着线索传送到一颗没有恒星、没有空气的流浪世界，称它“愈石之星”：绒球先被困在一个直径几十公里、能屏蔽传送感知的洞穴里，炸开岩壁才到地表；地表上一座雪白的小山其实是一头直径约一公里、半埋在地下的虚空巴士，体内一个生物也没有，附近还有不少虚空巴士的残骸可当材料。愈石带回后交给恒星巴士深处的进食器官——一条几十米长的蠕虫，用钝齿把石头一点点磨碎吞下——神经就慢慢长好了。很久以后琳又读到：意识消退的老年恒星巴士会慢慢移往同一处，琳把那里译作“巴士墓地”；就位后它们身上会长出类似“星界之门”的长期传送结构，与附近几头连在一起。琳立刻想到了连接世界。',
 ch:'卷六《治愈的方法》《巴士墓地》《分解过程》《我感觉得到》《漫长的周期》', rel:['v_starbus','v_lianjie']},
{id:'v_xukongbus', n:'虚空巴士 · 星游者', c:'物种', m:'void', sec:6, e:[5,6,7,13], p:[220,90,330], k:'whale', kp:{s:46,c:'#eef6fa',c2:'#9ac8e0',glow:'#bfe6ff'},
 s:'直径十公里、在虚空中沉睡旅行的巨型生物。琳用它的神经造出了“星游者”。',
 d:'当年袭击虚民母球的就是一头虚空巴士。它能传送，能感知梦境，体内的“免疫生产器官”像二十多米长的海参，会制造或从外面抓来免疫生物。琳研究了它的传送系统，造出星界之门，又把一头虚空巴士改造成可以随意传送的“星游者”，开始了新的旅行：先确定位置，再传送过去。\n琳第一次见到这种生物是在卷五：一座直径三十公里、像冰山一样的东西闯进陨石群的虚空丛林，用上百米长的节肢把长满植物的石块拍进峡谷般的嘴里碾碎。它的“冰层”是比合金还硬、还会自己愈合的壳质，体内有修补伤口的火蝇和水蛭般的免疫生物。陨石雨和开拓者把它打疼后，它转身走了，琳的“内探”毛虫却留在它体内：那里有一团团飞舞的、火花般的一厘米小生物和它们的卵，有长着锯齿嘴的红色触手，还有堆废物的空腔。每隔十几个昼夜，废物被吐出时，眼前就是一颗新的翻滚者——它找到翻滚者的速度比琳几百年加起来还快。后来琳读到螺旋生物的历程，才明白它会把沾上的生物带到一站又一站，在没有生命的地方撒下生态，便改叫它“虚空巴士”。\n卷八里，一头十多公里的虚空巴士突然传送到隧道出口外，炸毁了琳搭乘的寄生舰船，随即被吞没舰的长矛刺穿、整个吞下。终引者的任务之一就是回收巴士的传送器官；隧道复苏时小空间汇聚，也让附近的巴士没有传送能量可用。',
 ch:'卷六《疑惑》《一半的巴士》《出发@495》《路途》卷五《虚空巨怪》《冰躯之上》《虚空中的冲撞》《体内的旅行》《虚空之旅》《多站的旅途》《隐匿的生活》卷八《另外一端》《掠食》《任务》《准备》', rel:['xm_busattack','v_gate','v_huhe','luoxuan','a6_luobo','kaituo','j1_tunmo']},
{id:'v_gate', n:'星界之门', c:'琳的造物', m:'void', sec:6, e:[6,7,8], p:[-430,50,160], k:'gate', kp:{s:24,c:'#b85a5a'},
 s:'用“内脏”建成的长期传送通道。',
 d:'学会虚空巴士的传送系统后，琳造了这种门：一面巨大的半圆形大门，看上去由内脏组成——只有这种“内脏”才能保留传送能量；两头位置固定，比普通传送稳定得多，琳打算以后用它把许多星系连成一张网。门原本想建在虚空中，后来建在月上——月上的灰尘被它丢进虚空，天空重新变得清澈——以及虚民母球的广场上，通往殖民地新世界。虚民后来仿造了自己的门，被寄住着脑灵的“虚空博士”连到了真菌的世界，引发了真菌入侵。',
 ch:'卷六《新鲜的事情》《出发@495》《新的星界之门》《月的仇恨》', rel:['xm_gate','moon_bus','xm_fungus']},
{id:'v_golden', n:'金色史莱姆', c:'物种', m:'void', sec:6, e:[6], p:[430,40,120], k:'blob', kp:{s:10,c:'#e8c25a'},
 s:'直径二十米、会“制造环境”的金色史莱姆。琳观察了它十年。',
 d:'直径二十米的金色史莱姆，身上的小生物会“制造环境”，琳观察了它十年的绒球时间。起初它身上长满三十厘米高的“伞树”：一根垂直的树干、巨大的伞状顶部，顶部之下结出块状物，里面的小生物就吃这个。这样的生活持续了好几年，直到琳把时间加快，才看到奇妙的变化：虫子从小丘里“种”出飘浮的球体，不停放出雾气，把整个史莱姆罩在浓雾里；雾里，金色的表面长满了软软的棕色小尖刺，像一片草原，草原间散布着大大小小的湖，几毫米大的虫子、脊椎动物和像石头的生物聚在湖边——一个完整的微型环境。',
 ch:'卷六《成长记录》《增长的金色之物》', rel:['v_starbus']},
{id:'v_prison', n:'创造者监狱', c:'地理', m:'void', sec:6, e:[6], p:[540,-30,-80], k:'planet', kp:{r:50,tex:'jungle',c1:'#4f8a46',c2:'#7a6a52',atm:'#9fe0b0'},
 s:'一颗生机盎然的翻滚者，却是关押创造者的监狱。',
 d:'一颗位于星系边缘的翻滚者，地表看着荒凉，其实相当热闹：六条十多米长腿撑着蛋形小身子的“长腿”跨过峡谷；没有植物的沼泽上飘着小旋风；岩山壁上五米多长的裂缝会突然张开，把路过的旋风吸进去嚼碎；山区常刮一场温暖柔和、满是尘埃的沙尘暴，旋风们在里面越长越大；夜里地上长满像竹笋一样发光的结晶，白天它们又变回柔软的变形虫。这里本是塑藤者旋风的国度，后来方形飞行器飞来轰炸、把旋风吸进方块带走——那是脑灵，它们把这里改造成了关押创造者的监狱：地下深处一个废弃的大厅中央，创造者被罩在透明的大罐子里，触手像树根一样被固定在地下，小方块不停往它身上注射药水让它沉睡。琳借梦境控制了门边的机械，创造者用尽全力拔出一根触手，琳切下末端、盖上“光皮”带它逃了出来。之后这根触手占了一片湖当窝，又重新长回一棵大树的模样。',
 ch:'卷六《机械的视角》《监狱表面》《环境丰富的监狱》《废弃的地方？》《触手可及》《狂风的传说》《旋转的历史》《过去@412》', rel:['c_tentacle','dr_prison','v_xuanfeng','a3_heifeng']},
{id:'v_piaobohao', n:'漂泊号 · 虚空中的堡垒', c:'地理', m:'void', sec:6, e:[5,6], p:[140,40,-500], k:'none',
 s:'虚民的总部：一张十多公里宽、在虚空里漂流的金属圆盘。',
 d:'盘身里住着一整座城，所有虚民都在这里过日子；边缘一圈重炮朝星空开火。琳的球状物砸上合金甲板，里面的生物钻出来打洞，虫群从各处涌进去；虚民一路退守，最后守住十几条通往核心的通道，通道里堆满了碎掉的尸体。修复完成后，中心区关上大门、从圆盘中间脱离飞走，船上的虚民躺进茧一样的低温睡眠装置，花了将近三年才飞到安全的传送点。留下的空壳仍有十公里直径，上千个没赶回中心区的虚民靠剩下的物资活着。等船上再没有虚民，琳的触手在里面长开，把感染者和变异怪物都化成养分，又让“虚空运输者”从绒球运来材料，把整艘船拆开重新造过。',
 ch:'卷五《漂泊的终止》《被侵略的侵略者》《逃逸@384》《核心的装置》《回家》《平静的旅途》《被遗忘的船舰》《到达》卷六《威胁就在眼前》', rel:['xumin','ev_xumin','tlant','v_ximin']},
{id:'v_bingshan', n:'虚空冰山', c:'物种', m:'void', sec:6, e:[5], p:[-420,-30,560], k:'none',
 s:'一座会吃石头的活冰山，在虚空里漂荡。',
 d:'它看上去就是一座大得出奇的冰山，脸上一道像嘴的裂缝：它把周围的岩石拨进去碾碎，嘴里大概有许多细小的触肢，没用的扔出来，有用的送往深处。它就这样一边吃一边慢慢前进，闯进了陨石群上的虚空丛林。它的背上是冰封的大地，有一道被冰盖住的峡谷，雪地里还有生物在跑；冰层被钻开的裂痕会自己慢慢合上。它一直留意着背上的动静，会有针对性地还击。琳让基地周围的岩石化作陨石撞向它，又让一头一公里长的开拓者钻进它体内——它全身颤抖，从冰缝里喷出浓雾一样的细小颗粒堵住去路，再像火山爆发一样把开拓者喷了出去。它体内很暖，住着能在虚空的极冷中存活的“极地水蛭”。后来它离开陨石群，带着体内的割岩者远行，在观星者眼前像凭空消失一般；很久以后它又突然出现在螺旋生物的翻滚者上空，把那里的建筑几乎全部摧毁。',
 ch:'卷五《虚空巨怪》《冰躯之上》《冰中的物体》《虚空中的冲撞》《体内的旅行》《梦境勇者》《虚空之旅》《多站的旅途》《历程》', rel:['kaituo','luoxuan','v_rongqiu']},
{id:'v_xigema', n:'西格玛海滩', c:'地理', m:'void', sec:6, e:[5,6,7], p:[180,60,-120], k:'station', kp:{s:32,c:'#d8dde2'},
 s:'虚民三大空间站之一，富人和贵族的“度假区”，能随时欣赏银河。',
 d:'虚空列车从候车点冲出、穿过两道门驶向的就是这里：它被叫做度假区、居住区，坐落在随时看得到银河美景的地方，许多上层虚民住在这里，连士兵们也梦想着任务结束后在这儿买间房子、悠闲过完一生。它能自给自足，有一套自己控制的武器系统，几乎是虚空里的一个国家。真菌战争爆发后，另外两座空间站都已满员，只有它还有空位，它却把大多数难民拒之门外。后来一个往虚空里扔蛋形物的巨大方块贴上它，往里面放出大量尘雾，冰球也打到这里；一枚导弹炸掉了方块，空间站像被咬了一大口的水果，露出一层层房间，各区接连报警、漏气、起火，求救信号一口气发了几千条——将军却觉得这是最没用的一座空间站，懒得理它。',
 ch:'卷五《虚空列车》卷六《追逐@721》《空间站@722》《崩塌的地方》《聚集地@725》', rel:['v_nuowa','xm_general','v_ximin','xm_fungus']},
{id:'v_bianyuan', n:'边缘之星', c:'地理', m:'void', sec:6, e:[6], p:[-780,40,120], k:'planet', kp:{r:20,tex:'rock',c1:'#5a5046',c2:'#2a241e'},
 s:'绒球星系边缘的一颗翻滚者，地下长满了月上创造者留下的菌丝。',
 d:'名字是琳起的：它是一颗翻滚者，挂在绒球所在星系的最外缘。印加虫群在这里活动，琳在这里没找到创造者，却找到大量菌丝——大概是月上的创造者造来转送信号的；菌丝沉睡时也偶尔发出微弱的信号，它们有类似脑袋虫的神经结构，能“说话”，比如那句“逃离此地”。造脑怪的信号把它们唤醒，它们开始控制地下的一切。琳猜测，脑灵的部队很早就在这里建了基地，地下也许藏着秘密：它们发现并“激活”了菌丝，由此得知了月的事情，才打算借月入侵绒球。强制入梦的力量够不到这么远，所以琳留在这里的兵种依旧能行动。',
 ch:'卷六《启动了？》《朽木上的真菌》《它的作用》《里面的谜团》《计划的过程》', rel:['inca','zaonao','moon','v_naoling']},
{id:'v_lost', n:'迷失之星 · 果冻之星', c:'地理', m:'void', sec:6, e:[5,6], p:[-120,-60,480], k:'planet', kp:{r:34,tex:'jelly',c1:'#4a2a6a',c2:'#120c18',half:1},
 s:'一面永夜、一面永昼的世界。',
 d:'因为转法特殊，这里一面永远是黑夜，一面永远是白昼，两个极端同时挂在天上；寒冷的一面是一望无际的冻原，立着像树其实是石头的东西。当初是琳和一位虚民舰长在传送区外偶然传送才到了这里，之后再怎么试也到不了，所以一直只有少量部队。昼夜交界处是连绵的高山，不冷不热，那位舰长就在山上建了半球形的小屋和农场，常常望着永远不变的天空发呆；它做了一群虚民石像，每天回家都跟它们打招呼，好让自己别疯掉。它只剩一只手——另一只被这里的海星吃掉了。那只海星和虚民研究所里的几乎一模一样：五根触手，冰雪般的外壳，也用小蠕虫进食，琳由此认定它们都是虚空巴士的幼仔；这一只长得极慢，睡在果冻平原的地洞里，触手越长越多，快变成章鱼的样子。星上还有一种像长了五肢的石棍的生物，琳后来在黑金属的梦境世界里也见到过它们，怀疑这里曾被黑金属侵略过。\n舰长孤独得几乎要发疯，终于开着沙地车往寒冷的一侧探险：穿过形状像枯树的怪石林，前方是一望无际的“流星果冻原野”。这种黏糊糊的东西在绒球的陨石坑里也偶尔能见到，一碰就化，几百秒就消失；这里却铺满大地、不会化，里面还含有传送器的组成成分。舰长扑进一座果冻小丘，头盔被一条一米长、冰蓝色的蠕虫咬住；接着地面裂开，那只十米大、披着冰晶外壳的海星追了出来，速度几乎赶上全速的沙地车，却在更暖的石林边停下，回到满是果冻的地洞里休息——琳猜那条蠕虫是它的共生伙伴。',
 ch:'卷五《昼与夜的缝隙》卷六《异结构生物》《异星邻居》《再见迷失》卷五《冰冷果冻之原》', rel:['xm_starfish','v_xukongbus']},
{id:'v_icerolly', n:'冰雪翻滚者', c:'地理', m:'void', sec:6, e:[6], p:[620,30,360], k:'planet', kp:{r:32,tex:'ice',c1:'#e6f2f8',c2:'#9ab8c8',atm:'#dff4ff'},
 s:'冰封的流浪世界：长毛的生物、地下避难所里冻着的阿特兰——后来才知道，它就是那头受伤的恒星巴士。',
 d:'琳在一次传送里偶然来到这颗离所有恒星都很远的冰雪世界，派一个小圆盘钻进一个通往深处的冰结洞穴，上下左右全是厚厚的冰壁。洞里住着几只长毛生物，以真菌为食，会用祖先留下的护甲和供暖装置，却不会造，连用法都只记得一半。再往下是金属打造的“世纪末的避难所”，能住几千个无毛生物，如今广场上满是冻住的残骸，倒塌的建立者雕像上长满像结晶的雪菇。避难所负责人之一把自己冻在培养槽里几百年，留下一段段日记：它们因为一场战争离开原来的世界，在新地方定居后又出了事，只好继续往深处躲——录日记的那位自己也说不清这是在记录历史，还是别的什么。这些无毛生物自称“阿特兰”；它们察觉到黑金属留下的“传送痕迹”，才提前造了避难所。琳后来发现，这颗世界和月差不多大，是被整个传送过来的：它正是那头被脑灵打伤、逃到虚无之处冻住的恒星巴士。',
 ch:'卷六《流浪的世界》《冰雪世界的深处》《交流@89》《避难所》《冷冻的历史观察者》《传送的痕迹》《过程@266》', rel:['v_atlan','v_starbus']},
{id:'v_atlan', n:'阿特兰的漂泊空间', c:'文明', m:'void', sec:6, e:[6,7], p:[660,-60,-400], k:'station', kp:{s:22,c:'#b8a888',slab:1},
 s:'在虚空中漂泊的阿特兰：在一座不是自己造的空间站里从中世纪发展起来，后来住到了一颗世界上——没谁相信那颗世界是活的。',
 d:'它们的家是一个长达数公里的长方块，旧金属外壳上布满出入口、窗户和突出的“码头”，码头上却一艘船也没有——看上去就是给虚民那样的无毛生物住的空间站。它们管自己叫“阿特兰”，是一个发音，没什么特别意思。和琳造的莫斯相比，最大的区别是头上有大量的毛（也有无毛的）。阿特兰原是中世纪的种族，世界末日时逃进了空间站——那空间站不是它们造的，它们是在里面从中世纪一路发展到接近虚民的技术。资源耗得太快，它们才停在虚民世界附近，坐小飞行器飞往母球；文化学家觉得那里野蛮的原住民“可以教育”。后来它们炸掉在虚民世界的居住点，开着空间站继续漂泊，到了一颗新的世界定居——那其实是一头恒星巴士，它们并不相信脚下的世界是活的；脑灵入侵后，它们在各地挖了编号的地下避难所，世界受伤流浪而去，空间站却留在了原处。被脑灵带走的阿特兰后来成了侵略绒球的步兵和复制体。很久以后琳才知道，它们的故乡叫尔什。',
 ch:'卷六《漂泊的空间》《阿特兰的旅途》《虚空的巨物》《过程@266》《把它叫醒》', rel:['v_erxi','ex_atlan','v_atlancity','v_icerolly','v_starbus']},
{id:'v_junk', n:'虚空垃圾堆 · 晶蜴的国度', c:'地理', m:'void', sec:6, e:[6], p:[-720,30,350], k:'rocks', kp:{r:70,n:120,s:9,c:'#6f7378',metal:1},
 s:'绕着一颗青色恒星漂浮的一大片金属团，几公里大的团块深处住着一厘米大、从不打仗的晶蜴。',
 d:'一大片金属团绕着远处一颗青色的恒星缓缓漂浮，谁也不知道它们从哪来。虚民的探索队钻进一块直径几公里的金属团，被会动的金属一个个吞掉；琳的间谍趁机混进去，遇见了这里的原住民晶蜴，一只震动两下报名字的晶蜴被琳叫作“咯咯”。它们的“国度”里，二十厘米高、关节密布的圆柱建筑更像机械；它们爱把捡来的有趣东西拼成更有趣的东西，能量来自封锁区深处一种液体里的微小生物——把储能箱放下去，它们就聚过来“充电”。内层空间被一层密封墙包着，里面有空气：晶蜴管空气叫“嘎达”，觉得这种看不见、到处都是、会把跳起来的它们拦住的东西很邪恶，直到发现封锁区里有生物依赖空气活着。它们的历史记在可以录音的圆盘上，最特别的是：没有一场战争。',
 ch:'卷六《虚空的垃圾堆》《金属之内》《新间谍》《虚空垃圾中的原住民》《变形的居住方式》《能源与治疗》《发展史》《合金的心》', rel:['v_jingyi','xumin']},
{id:'v_jingyi', n:'晶蜴', c:'物种', m:'void', sec:6, e:[6,7], p:[-690,60,390], k:'swarm', kp:{n:120,s:24,c:'#bff0ff'},
 s:'一厘米大、外壳闪亮如结晶的小生物：一支跟着黑金属入侵虚民，另一支在虚空垃圾堆里过着从不打仗的日子。',
 d:'琳第一次见到它们，是在一个拖走虚民幼仔的圆锥体里：几毫米大的道具中间，站着一厘米大、闪闪发亮的生物，身边围着能在体内制造爆炸物的金属橄榄；它们发出像闪电一样噼啪的声音，后退时金属橄榄也跟着一起退。琳拆开一只研究：内脏大多像果冻，夹着一些和消化有关的金属般坚硬部位，身体中间的洞里能造出几厘米的“长矛”弹射出去，连金属都能穿透。跟着黑金属的晶蜴驾驶圆锥体抓幼仔，在虚民尸体上放出堵塞呼吸器的“滤染菌”，带着金属微生物大军和琳的微型部队打了一场看不见的战争；后来还冒出一头巨大如怪兽的“晶蜴”。而在虚空垃圾堆里，琳找到了它们的亲戚：语言和黑金属那边不太相通，热衷收集和拼装，历史上没有战争。在文明平台里，琳还见过三米多长、像晶蜴的生物。',
 ch:'卷六《拖幼仔的小生物》《出击》《微型防守》《贯穿的光芒》《新间谍》《合金的心》《里面的生物》', rel:['v_junk','v_civplat','xm_coral','xm_xuanfu']},
{id:'v_naoling', n:'脑灵核心', c:'地理', m:'void', sec:6, e:[6], p:[300,-100,640], k:'planet', kp:{r:46,tex:'dark',c1:'#1a1430',c2:'#5a3a8a',rings:3,glow:.6},
 s:'星光无法到达之地，被一层层陆地环绕的核心。',
 d:'玛雅偷偷改写过的那段信息让琳在梦里得知了它的位置。琳把伪装成寒石的“观察石”传送到核心“附近”，才看清它：这里看不到一颗星星——琳猜是光线被偏折了，温度却和普通虚空一样。几块大小像绒球大陆的陆地飘在黑暗里，靠发光物提供温暖，上面住着各种生物：第一层大陆上有飘着无数水球的“飘水平原”、记录着脑灵“混合梦境计划”的记录之石，碰一下就冒出光团的螺壳石；第二层的“陆地”其实是一堆互相碰撞的碎石块，有专门把碎石兜进嘴里的“集石袋”。脑灵偶然闯进一个巨大的梦境，从此靠它侵略别的世界，梦想有一天以自己的形态踏进现实；那个梦境核心原本的居民就是护核者。虚民一百五十艘、恶魔五百艘、印加虫群三百艘、琳七百艘战舰组成联军，恒星巴士替它们硬扛漫天光团；被关在螺壳石里的“异类”——一批能借物质在现实里显形、想离开梦境的护核者后代——关掉了第一层大陆的传送阻碍，护核者则把梦境核心转移走了；恒星巴士瞄准暴露的核心，脑灵就此“崩解”，所有方块停在原地不动。战后统计：虚民剩三十艘、恶魔一百、印加虫群七十、琳一百五十。',
 ch:'卷六《完全的计划》《星光无法到达之地》《环绕的陆地》《中心之地》《原住民》《这一刻》《崩解》《战争统计》', rel:['dr_brainspirit','v_huhe_guard','v_guancha','v_starbus','xm_general','v_demon']},
{id:'v_huhe_guard', n:'护核者', c:'物种', m:'void', sec:6, e:[6,7,8,9,10,11,12], p:[340,-60,600], k:'none',
 s:'守护“核心”的古老生物。“非常能守护的地方”是它们的口头禅。',
 d:'脑灵所用的那个梦境世界的原住民，被梦境核心自己造出来守护它：不吃、不睡、不累、不生也不死，数量永远固定，一心等着从没见过的“入侵者”。最初它们很“笨”，脑灵怎么骗都没用；后来它们听了太多个性生物的故事——背叛、欺诈、爱情——思绪丰富起来，直到有一天才发现自己原来也会“惊讶”。琳和创造者在梦里捣乱时，它们一度把恐惧之地的事告诉脑灵；它们还生下过一批想离开梦境、能在现实里显形的后代“异类”，被它们让脑灵关进了螺壳石里。脑灵核心之战的最后，它们把核心转移到了梦食那里，才有了“护核者之地”。“非常能守护的地方”是它们的口头禅。织梦者的记录说，护核者是梦境核心自行生出来的，连制造核心的织梦者也没料到；后来还出现了专门清除恐惧能量的第二类——小护核者。在怒虫的世界，一个由怒虫变成的“丝线生物”也用一块含梦境核心的结晶造出过护核者。',
 ch:'卷六《原住民》《变化的情绪》《这一步》《崩解》《目的之前》《非常能守护的地方》《完美？》《中断@1042》', rel:['v_naoling','v_huhe','v_xiaohuhe','v_zhimeng','v_mengshi','v_nuchong']},
{id:'v_guancha', n:'观察石', c:'琳的造物', m:'void', sec:6, e:[6], p:[260,-70,560], k:'none',
 s:'琳最具伪装能力的兵种，模样像一块寒石。',
 d:'琳在测试怎么阻止一个区域里的传送，已经差不多弄明白了；梦境里那些隔绝空间——恐惧之地、冰原——也在核心生物的攻击下碎成了一片片。恒星巴士的神经在感知传送坐标时，也会模模糊糊地感觉到周围的区域；琳利用这一点，把观察石传送到脑灵核心‘附近’，而不是坐标本身。一个小小的物体在极寒的虚空里飞快前进，它想知道：这里离核心有多近？',
 ch:'卷六《周围的地点》', rel:['v_naoling']},
{id:'v_chuanxing', n:'穿星者', c:'琳的造物', m:'void', sec:6, e:[6], p:[120,40,180], k:'ship', kp:{s:26,c:'#4a5a52',gun:1},
 s:'炮管形的战舰，里面是琳当时威力最强的光线。',
 d:'炮口边缘一圈特制的眼睛确认目标位置。闪耀的光芒穿透黑暗的虚空，直击远方黑金属战舰的外壳。',
 ch:'卷六《再次进入梦境》《传送获取计划》', rel:['xm_cube']},
{id:'v_dreamgate', n:'通往梦境', c:'地理', m:'void', sec:6, e:[6,8,9,10,11], p:[-160,150,-560], k:'portal', kp:{c:'#9a8aff'}, go:'dream',
 s:'琳一次次被拖进、也主动进入的梦境。',
 d:'黑金属在梦境中有自己的世界，脑灵用梦境设下陷阱。点“进入地图”沿光之大路走一遍。',
 ch:'卷六《过去的生活》《梦中的天国》《边缘之地》《恐惧之地》《梦境的研究》', rel:['dr_road']},

/* ---------- 星区 7 ---------- */
{id:'v_huhe', n:'护核者之地', c:'地理', m:'void', sec:7, e:[7], p:[-420,0,-200], k:'planet', kp:{r:54,tex:'jungle',c1:'#2a5a3a',c2:'#6a5a42',atm:'#8affd0',glow:.15},
 s:'梦境与现实重合的古老世界：丛林小镇、会飞会自爆的榄球、灵魂的光影。',
 d:'这里曾住着干旱荒土上的智慧种族“瑟”，它们被“神明”——一个创造者——统治，几乎灭绝，最后五十个瑟随神去了新世界；“精英瑟”去附近的翻滚者发展军事，造出工厂。能吸收梦境能量的“梦食”把别的世界的梦境和生物搬到这里。琳用岩蛛、梦蛛探索，看见雾形生物袭击榄球的小镇，创造者吸取核心后苏醒。',
 ch:'卷六《护核者之地》《朦胧的世界》《猎食者》《梦食@535》《智能技术》', rel:['v_se','v_mengshi','v_lanqiu','v_yanzhu','v_huhe_guard']},
{id:'v_se', n:'瑟 · 精英瑟', c:'文明', m:'void', sec:7, e:[7], p:[-470,40,-150], k:'none',
 s:'护核者之地原本的智慧种族。',
 d:'瑟的飞行器能储藏梦境能量，所以它们才能乘着它飞进虚空——这项技术也是突然从它们的思绪里冒出来的。可到了新的翻滚者，它们没法增加梦境能量，甚至下不了飞行器：精英瑟一旦离开有梦境能量的地方，就像脑袋被拔掉一样。它们陷入沉思，后来有一个瑟提出办法：把飞行器里储藏梦境能量的装置拆开，做成可以携带的小装置，才得以离开——但梦境能量无法增加，也就意味着它们在新的地方无法增加同伴。',
 ch:'卷六《智能技术》《对神明的研究》', rel:['v_huhe']},
{id:'v_mengshi', n:'梦食', c:'物种', m:'void', sec:7, e:[7,8,9], p:[-360,70,-260], k:'fog', kp:{r:60,n:40,c:'#c8a8ff'},
 s:'像一颗会移动的梦境核心的能量生物，能转化梦境能量，在世界上铺开梦境。',
 d:'脑灵组建过一支阿特兰小队“梦境捕获者”，专门捕猎对梦境敏感的现实生物——恒星巴士、虚空巴士都在此列，但没有哪种像梦食那样特别；脑灵对它所知不多，它像幽灵一样难以发现，小队从没抓到过。梦食就像一颗会活动的梦境核心：普通能量生物要靠核心或梦境方块维持梦境，它却能在身边生成梦境，持续在一个世界上释放转化过的梦境能量，造出与世界重叠的梦境，前期能量充足时扩张很快，后期变慢。它不生产护核者。在梦境里看，它像一团三十多米、像变形虫般不停变形的雾气。它会把自己的一部分像分裂一样送到虚空远处，比如某颗翻滚者上，形成一个基础梦境世界，之后无论多远都能如同传送般瞬间抵达。\n在护核者之地，瑟把它当作“神明”崇拜；这个世界原本没有梦境，它到来后把别处世界的梦境和许多生物搬了过来，然后陷入沉睡。叛逃的瑟曾受某种生物指使，造出大批机械、以杀死梦食为目标，还发明了从未用过的梦境瓦解器。创造者在瑟的废墟下挖出通往梦食的洞穴，抓住护核者、进入沉睡去“吸取”它的核心——其实是在自己体内造一个新核心，梦食的核心并未消失，那个世界也没有崩溃。创造者此后就住在梦食所在之处扩建梦境；琳把小护核者带走后，梦食开始活动，几个昼夜里断续发出单向的信息，最后一句可译作“再见”，随即一阵强光，它离开了，大批梦境生物欢快地随之飞散。它曾杀死过许多创造者，创造者重建的梦境因此小了很多，还特意加了防御，防它再把梦境带走。\n在连接世界，琳和虚空蠊找到一团固体烟雾般的东西，里面的梦境能量与梦食一模一样，像是它的分身；里面记载着梦食的“毕生经历”，留言者其实是一个冒用梦食身份、已成为梦境生物的瑟。记录说，梦食在一个固体生物与飘渺生物紧密共存的世界建起了“家园”，常从那里出发去别的世界探险，再带回别处的生物，只有飘渺生物能随它旅行，它于是想找办法携带固体生物。零件战舰的智能机械也能感应到影响它情绪的梦食，带琳穿过三号门去找它。\n梦食的起源在织梦者：它们造出的“完美核心”就是最初的梦食。原始梦食毁灭了织梦者文明，把所有织梦者改造成新的梦食（大约不到十个），送往虚空各处，彼此再无联系，也忘了自己的来历。只有一个梦食慢慢想起自己曾是织梦者，它装作失忆，请求原始梦食暂时让它留下观看这个世界。后来这个织梦者梦食困在碎裂的梦境空间里，食物越来越少，便驱使一种能发现并吸收远处能量的新型护核者；为了让世界蒸发、摆脱恐惧能量，它研究织梦者留下的资料，造出大型机械去联络蒸腾者，还派机械袭击教团抢夺护核者。它的后代被囚在圆柱里，被教团救下，又煽动迷石反叛；后代被严格的历史分享规则约束，只向“符合规则”的生物讲述过去。琳还在一个满是尖刺的圆盘里发现过一个梦食幼仔。最后，琳用大型绒球载着织梦者梦食前往织梦者之地，旅途中在梦境里模拟出那个世界，让它与后代远程相会。',
 ch:'卷六《继续的计划》《故事@534》《梦食@535》《梦的节日》《废墟@541》《梦食之上》《核心的吸取》《背后的控制者》《自身的核心》《核心的源头》《接近完美》《苏醒@811》《离开@812》《记录的讯息》《记录者》《整个过程》《了解@842》《交流@848》《织梦》《梦食@1038》《梦食的记忆》《被困之后》《蒸腾招来》《迅速行动》《挤压出来的计划》《接下来@1064》《追踪方式》', rel:['v_naoling','v_huhe','v_se','v_huhe_guard','v_xiaohuhe','v_lianjie','v_lingjian','v_zhimeng','v_jiaotuan','v_zhengteng']},
{id:'v_lanqiu', n:'榄球', c:'物种', m:'void', sec:7, e:[7], p:[-440,-30,-130], k:'swarm', kp:{n:40,s:16,c:'#d8a85a',balloon:1},
 s:'橄榄形、会飞的生物。点火，然后扑上去把自己引爆。',
 d:'护核者之地的居民：橄榄形、飘在空中，六只肢都能抓握，但因为是飘着的，每只只能带一点东西。琳的岩蛛趴在镇中心的雕像上，看它们一遍遍来祈祷，“它们要来了……必须保护我们”；后来它们一起往镇子边缘搬粘土，筑起城墙。梦境和现实在这里完全同步，在梦里，榄球是一团团影子。岩蛛还看见它们点火，再扑到火上把自己引爆；琳决定下次要在它们自杀之前抓一只活的，弄清楚为什么。',
 ch:'卷六《护核者之地》', rel:['v_huhe']},
{id:'v_yanzhu', n:'岩蛛 · 梦蛛', c:'琳的造物', m:'void', sec:7, e:[7,8], p:[-500,-60,-240], k:'none',
 s:'一米长、披着岩石甲壳的蜘蛛形兵种；梦蛛是会散发影响梦境脑波的大型变种。',
 d:'岩蛛身长一米，体形像蜘蛛，全身覆着岩石般的甲壳，琳造它们是想“体验”一下岩石生物的生态。它们体内能分解多种矿物，靠吃石块强化和修复身体，但本质上仍是多细胞生物。它们装在空投舱里降到护核者之地，舱落地后像种子一样裂开；五只岩蛛刚爬上裂谷岩壁，就被会自己滚动、张开成网的风滚草罩住，挨了一身细刺。它们在这片大地上感到浓郁的梦境能量，却连不进梦境。\n岩蛛潜进丛林里榄球的小镇观察那些漂浮的橄榄形居民，看它们修补被一头五米多高的生物撞开的围墙；又爬上陡峭的火山，跳进满是软泥的洞穴，搭着平原毛虫钻进浓雾。琳发现借小镇的雕像只能连进梦境，借火山里的软泥却能进出梦境并影响里面的东西。后来琳仿照创造者影响梦境的方式造出“梦蛛”：模样和岩蛛一样，腿展开有三十多米，脑结构复杂得多，能散发影响梦境的脑波——不会像创造者那样影响巨大，但“应该能够抢一些东西”。脑越复杂的兵种越容易被发现，梦蛛在离护核者一百多米时就暴露了，它用尾部喷射追上去，一爪夺下了护核者带走的金属球。\n岩蛛也是琳在狭窄地方探路的常用兵种。在亚种平台的体内，它们沿着低引力的通道奔跑，跟着两肢狂奔的晶蜴，看焦油用细线传递物质交流，拆开磁力罐找到里面惊恐的小生物，还用旅者的语言跟最后留下的旅者说话。之后琳又专门造了一种能在微型机械面前“隐身”的岩蛛，被检测时就像普通石头，它踩着机械之间的空隙走到一个装着鲜红器官的十米高透明箱子前，用钻头般的前肢试探外壳。在罐脑之城，一只带着小护核者的岩蛛看着换了机械脑后发疯的脑灵，又飘在空中不停“许愿”，引着地上的彩色软泥跟随聚集。',
 ch:'卷六《护核者之地》《围墙》《火山》《浓雾》《发现与控制@517》《神秘的东西》《追寻@550》《隧道@584》《里面的生物》《这里的生态》《罐头和神》《平台之内》《悄悄地》《离开@1494》《推测和行动》', rel:['v_huhe','v_huhe_guard','v_lanqiu','v_jiaoyou','v_civplat','v_xiaohuhe','v_guanzhuang','v_caini']},
{id:'v_black', n:'黑色世界', c:'地理', m:'void', sec:7, e:[7], p:[-660,60,80], k:'planet', kp:{r:26,tex:'dark',c1:'#141414',c2:'#2a2a2a'},
 s:'满地脆弱的黑色物体。',
 d:'星游者路过的一颗翻滚者。大约三成的地方铺满了黑色的东西，看上去像一大片黑色森林，但一碰就碎——琳检测后发现，它们只是大量碎屑堆出来的，和多细胞生物没什么关系。另外七成的地方，似乎还‘活着’：黑森林边缘外是一片十米高的小岩山，上面满是洞孔，偶尔会‘嗡’地响一声。',
 ch:'卷六《路途》', rel:['v_gentle','v_xukongbus']},
{id:'v_gentle', n:'温和世界', c:'地理', m:'void', sec:7, e:[7], p:[-560,-60,300], k:'planet', kp:{r:30,tex:'jelly',c1:'#4a8ad8',c2:'#2a5aa8',atm:'#9ad8ff'},
 s:'果冻一样的蓝色大地。',
 d:'一片看起来像海洋的蓝色大地，到了跟前才发现是陆地，只是软得像果冻。琳是靠星游者的随机传送找到这里的——星游者用的是修复过的虚空巴士神经系统，琳觉得那套神经的‘潜意识’会优先挑有生物的地方。这里的生物还相当兴盛，琳在这里研究了“果冻生态”。',
 ch:'卷六《温和世界》《梦境的研究》', rel:['v_black']},
{id:'v_civplat', n:'文明平台', c:'文明', m:'void', sec:7, e:[7], p:[-200,80,250], k:'station', kp:{s:28,c:'#8a9098',ball:1},
 s:'虚空中会收集周围一切的金属球。',
 d:'创造者说：“这种生物，被称之为文明平台。”那些喜欢自相残杀的“愚者”文明发展得很快，到达瓶颈也快。最初的文明平台像一颗金属球，靠把四周的碎屑聚到身边越长越大。琳钻进去的其实是它的一个“亚种平台”：焦油、大个子的晶蜴和一块三十米的“神的血肉”都在那个亚种平台里；琳在那里收集材料，造出了一公里长、一半是触手的兵种克拉肯——“虚空说到底是一片大海”。',
 ch:'卷六《梦中的交流》《里面的生物》《核心构造之地》', rel:['v_jiaoyou','v_kraken','v_jingyi']},
{id:'v_jiaoyou', n:'焦油', c:'物种', m:'void', sec:7, e:[7], p:[-170,110,220], k:'blob', kp:{s:6,c:'#1a1612'},
 s:'在零件堆里爬来爬去、身上插满零件的生物。',
 d:'像变形虫一样贴地挪动的生物，在亚种平台的狭窄通道里数量很多，琳猜它们是平台体内的原住民，从很早以前就住在这里，靠平台“分解”来访者后分到的残渣过活。它们把捡来的金属管之类的零件摆在身上，琳怀疑那是获取能量的办法；它们还能远程轰击，能把金属柱炸掉一块。岩蛛偶尔戳它一下，起初它会掉过头来瞄准，戳多了反而懒得理。',
 ch:'卷六《里面的生物》', rel:['v_civplat']},
{id:'v_kraken', n:'克拉肯', c:'琳的造物', m:'void', sec:7, e:[7,8], p:[-80,40,330], k:'squid', kp:{s:40,c:'#6a5a8a'},
 s:'一公里长、一半是触手的柔软兵种，能连续远距离传送。',
 d:'琳在亚种平台里找出传送器官，再加上那里的材料，造出这个新兵种：身长一公里，一半是触手，不像别的战舰，倒像一只庞大柔软的海洋生物——毕竟虚空本来就是一片大海。“克拉肯”这个名字本来就在琳的思绪里，指某种巨大的海洋生物，琳也曾拿它给绒球上的海洋生物命名。离开平台时，它从金属大地上缓缓升进满是尘雾的高空；那些传送器官记得从前给“神”传送信息的路线，它便一跳再跳，掠过一颗灼热的巨大恒星，朝梦境核心诞生地的方向前进。\n它落进一个被巨大光球照亮的洞穴，空气和亚种平台内部很像；一艘直径约一公里的金属圆盘带着小飞行器排出各种图案测试它的智力，它就挥着触手回应，随后被当作船舰迎进神民之地。后来士兵来查验“特殊能力”，它逃出城市，圆盘飞行器的光线在它外皮上烧出一个个焦洞；它在禁地的洞穴里像真正的章鱼那样用触手贴地爬行，让探测器把它当成一块石头，悄悄跟在飞行器后面，还用触手缠住一艘三十米长的飞行器挤压，后来受了伤便换绒球继续深入。\n它载着市长在飘浮岩间甩开浮岛寄主的圆盘战舰，放出假市长引开追兵，又从触手末端射出爆弹击中藏着基地的飘浮岩，让那里的引力消失。在寄主聚集地，它穿行在上百米粗的岩石枝杈间，挖开地面钻进发光的洞穴，抱走一块七十多米、用梦境能量跟它交流的石头——那是被分裂的意识。这只克拉肯后来在飘浮岩地被微型机械的隐藏基地一击撕碎；之后另一只带着小护核者的克拉肯传送到被恐惧占据的翻滚者去侦察，在工厂被导弹炸成碎片时瞬间闪开，又放出十多个绒球钻进导弹发射口。',
 ch:'卷六《核心构造之地》《聚集地@594》《欢迎来到神民之地》《不要去那地方》《禁地》《深处@605》《凝胶》《它们的关系》《做法@636》《问题@637》《假冒者》《逃出@657》《聚集地@669》《交流的石头》《离开的意识》《火光之后》《展开搜索》《对撞的爆炸》', rel:['v_civplat','v_shenmin','v_fudao','v_piaofu','v_fear','v_xiaohuhe']},
{id:'v_fungusworld', n:'真菌的世界', c:'地理', m:'void', sec:7, e:[7,8], p:[0,-40,-420], k:'planet', kp:{r:48,tex:'fungus',c1:'#eee8f2',c2:'#b9a9c9',atm:'#f0e8ff'},
 s:'被瘟疫真菌占据的白色世界：伞状巨蘑菇、白色地毯，菌尘遮天。',
 d:'阿特兰的探险者在这里被真菌甲虫捕获。真菌通过被连错的星界之门涌入虚民母球。第二次来时，这里有一片大海，一个一公里长的物体坠入海中掀起海啸；白色、翼展一米的“洒菌鸥”成群飞起，菌尘随翅膀洒落；真菌与崇拜蒸腾者的教团交战。创造者的幼仔被关在琳战舰的水牢里。',
 ch:'卷六《白色的世界@513》《浓雾》《目标所在》《真菌与教团》', rel:['xm_fungus','plague','v_sajun','v_jiaotuan']},
{id:'v_sajun', n:'洒菌鸥', c:'物种', m:'void', sec:7, e:[8], p:[30,0,-380], k:'swarm', kp:{n:80,s:20,c:'#ffffff'},
 s:'像鸟一样的白色真菌生物，翼展一米。',
 d:'它们聚集在海岛边缘，飞行器一接近就成片飞起，伴随着翅膀的摆动洒下菌尘。名字是教长起的；它们看着像野生动物，会躲开飞行器，教长却认定它们是真菌的武器。后来它们成群撞向一只断了所有触角的海星，自己撞成粉末，留下的菌尘再被喂进养分，长成困住目标的菌丝；它们也会追上飞行器黏在上面，让菌丝缠住螺旋桨、钻进缝隙，把飞行器拖下来。',
 ch:'卷六《目标所在》《真菌的攻击》', rel:['v_fungusworld']},
{id:'v_newworld', n:'新世界', c:'地理', m:'void', sec:7, e:[6,7], p:[230,40,-300], k:'planet', kp:{r:34,tex:'rock',c1:'#8a6a4a',c2:'#5a4a3a'},
 s:'虚民通过自己的星界之门开拓的殖民地，一片荒岩。',
 d:'琳的星界之门把虚民母球和这片荒岩之地连在一起。去那里的虚民没过多久就一个个变成强盗——将军以为是有什么东西在影响它们的精神，琳却觉得，那只是长期挤在城市里的虚民天生向往空旷、一到开阔的地方就想开着沙地车狂奔。盗贼团横行：奔疯帮（这一带最大，喜欢像疯子般狂奔，只抢一部分来保证资源稳定，曾聚集一千多虚民围攻教长）、红爆团、金砂帮、滚动团、背着头骨的笑脸团……教长占了一座山洞改造成实验室，被当作敌对团体的秘密基地，不停有盗贼来攻；它发现是一个被困住、长着十根肢体的肉团在释放脑波暗示它们。真菌占领虚民母球后，将军带着全世界的虚民通过星界之门撤到这里，在这片清澈天空下的荒岩上重建文明。',
 ch:'卷六《随机的事件》《发现与控制@517》《新世界@533》《袭击的持续@693》《团结的盗贼》《持续的影响》《又一个新的世界》《越过》', rel:['xm_gate','jiaozhang','xm_planet','xm_general']},
{id:'v_shenmin', n:'神民之地', c:'地理', m:'void', sec:7, e:[7], p:[320,-30,0], k:'rocks', kp:{r:130,n:70,s:14,c:'#9a8a78',city:1},
 s:'飘浮的岩群。它们热情地欢迎每一个来访者。',
 d:'来访者要登记文明历史、种群特点、数量、繁殖速度，还要提供细胞核信息，好安排最舒适的居所——绒球被登记为“绒球”。危险区可以采集资源；禁地像一颗小翻滚者，里面有凝胶生物“边缘眼”、幽灵护甲和血色岩壁。市长是一个“漂泊者”：不知道自己是什么生物，脑由金属和梦境能量构成。',
 ch:'卷六《欢迎来到神民之地》《加入资料》《幽灵的动作》《血色地点》', rel:['v_edgeeye','v_yuanling','v_fudao','v_kraken']},
{id:'v_edgeeye', n:'边缘眼 · 凝胶生物', c:'物种', m:'void', sec:7, e:[7], p:[360,10,40], k:'blob', kp:{s:8,c:'#8af0c8'},
 s:'凝胶生物中独立于集体意识的一员，在飘浮岩石上观察、记录并发表看法。',
 d:'琳的探梦球在浮岛寄主的“禁地”里查看操作面板时，一个东西从机械缝隙中钻出，爬上了画面：它像一团能任意变形的肉，没有嘴，却能说神明的语言，话里不带情绪，琳却能感到它体内有种“热情”。它喜欢叫自己“边缘视线”。神民之国的居民大多以为凝胶生物共享同一个意识，它说同类确实是一个整体，它却处在边缘，只有自己的想法，所以被叫作“边缘眼”。这样的凝胶生物有很多，分布在比较重要的飘浮岩石上，负责观察、记录那里发生的事，再发表看法，偶尔也和别的生物讨论历史；同类会定期给它送来食物和用品，听它汇报，再教它关于神民之国的知识，没观测到又没人告诉它的事，它就不知道。凝胶生物从这里获取资源、维持稳定，不许谁造成太大破坏，却不管这里生物的命运。\n它在禁地里住了很久，一直看着寄主的变化：寄主刚来时还很正常，早就打算侵略市长的城市，并和凝胶生物讨论过整个计划。琳选择什么都不做，边缘眼说禁地的前进停不下来，但寄主的愤怒可能平息，那个方块被拿走后它或许能从疯狂中恢复——这正是它希望的结局。它在机械面板上调出飘浮石的坐标，告诉琳另一个同伴负责观察“神”，即这个世界中心的动静，并劝琳别直接靠近那片黑色，那是世界最危险的地方。琳让探梦球给它留了一个通讯器；后来禁地停在半路，就是它告诉琳：寄主恢复得比预想更快，已经没那么疯了，大概还有点后悔，因为它发现单凭自己撞过去击不垮目标。它不会和寄主交流，却很懂得察看寄主的情绪。边缘眼也能感知梦境能量，它告诉琳，微型机械在虚空许多地方都有同类，一直在“制造”飘浮在虚空中的个性生物，它们的能量最初是一种感觉，后来某个时候忽然换了另一种；至于目的，它也猜不出来，只确定原灵似乎再没有复苏的机会了。',
 ch:'卷六《怎么做》《凝胶交流》《决定该怎么做》《神的样子》《不能守护的东西》《‘神’的生活》《储藏的原灵》', rel:['v_shenmin','v_fudao','v_fear','v_yuanling','v_piaofu','v_ruanjiao']},
{id:'v_yuanling', n:'原灵', c:'文明', m:'void', sec:7, e:[7], p:[280,30,-60], k:'none',
 s:'研究梦境能量的古老分工型物种。脑灵可能因它们而生。',
 d:'脑灵是原灵生出来的一个亚种，纯粹由能量结构组成，但脑灵并不知道，原灵自己也是很久以后才发现。原灵造出了自称“神”的微型机械，几乎灭绝了制造者。线团里记载着它们毁灭的原因。',
 ch:'卷六《历史》《神的样子》《能量使用》', rel:['dr_brainspirit','v_shenmin']},
{id:'v_fudao', n:'浮岛寄主', c:'物种', m:'void', sec:7, e:[7], p:[400,-60,-40], k:'none',
 s:'唯一一种（除了裂解船）能对其他飘浮岩造成巨大影响的生物。',
 d:'神之地有无数大小不一的飘浮岩，彼此从不相撞，稳稳地悬着；除了裂解船，唯一能对它们造成巨大影响的生物就是浮岛寄主——它寄生的不是生物，而是飘浮岩。琳照着一名技术员的样子造了个间谍，混进一艘巨大的圆盘形战舰的资料库，没想到战舰突然出动，飞向禁地：市长害怕禁地里的生物，要把整个禁地轰掉。这里存着普通博物馆里看不到的资料，可神民之国的研究团队对它的繁殖和成长也所知不多；寄主之母会爆炸。琳放出把梦境感官强化到最大的“探梦球”，在禁地里感到一种和市长相当接近的梦境能量。',
 ch:'卷六《飘浮的寄生者》《问题@637》', rel:['v_shenmin']},
{id:'v_erxi', n:'尔什（从虚空看）', c:'地理', m:'void', sec:7, e:[7,8,9,10,11,12,13], p:[580,0,260], k:'planet', kp:{r:60,tex:'earth',c1:'#3f7a3a',c2:'#1a4f8a',atm:'#7fb8ff',moon:1}, go:'erxi',
 s:'阿特兰的故乡，一颗活着的巴士世界。',
 d:'琳最早是从阿特兰的回忆里认识它的。尔什附近有颗被狂沙风暴笼罩的翻滚者——玛尔斯。点“进入地图”。\n卷八里，尔什想起了自己最早的来历：虚空分裂之前，它只是一个能把思维变成现象的小空间里无数不定形的东西之一，那个空间就是在虚空边缘外游荡的吞噬之域。吞噬之域的“神经中枢”在另一个虚空吸收了“计算生物”的思维，学会先一步猜出生物的想法；堆积的预测数据连同中枢被扔出去，成了尔什的“预言思维”——总从无数个未来的自己看当下，所以觉得遇到的一切都很落后。碰撞时尔什没有躲藏；在模拟里，它总在融合后的虚空里做试验，认为融合才是虚空本来的样子。',
 ch:'卷六《沙尘中的历程》卷七《河》《测试》卷八《感觉》《游荡之物》《预测》', rel:['ex_planet','v_mars','v_atlan','j1_tunshi','j1_benyuan','j1_jisuan','ex_nuo']},
{id:'v_mars', n:'玛尔斯', c:'地理', m:'void', sec:7, e:[7,8], p:[720,30,420], k:'planet', kp:{r:32,tex:'sand',c1:'#b8653a',c2:'#7a3a22',atm:'#e8a070'},
 s:'尔什旁边沙尘红土的翻滚者。居民自称“玛尔斯”——战斗之神。',
 d:'当年尔什民认为它是星系里最适合居住的地方，有周全的计划移民过来，可这里整天飘洒狂沙风暴。它们说自己已经被原来的世界抛弃了：以前自称尔什的居民，现在改叫玛尔斯。地下住着“岩皮”——很可能就是古老计划送来的、经过改造的“能力者”。阿美根与艾沙的群体也在这里争地盘。',
 ch:'卷六《沙尘中的历程》《故事@737》《一种生物@740》《岩皮的记忆》《别的群体》', rel:['v_erxi','ex_ability','v_yanpi']},
{id:'v_yanpi', n:'岩皮', c:'物种', m:'void', sec:7, e:[7,8], p:[750,-10,460], k:'none',
 s:'玛尔斯地下的岩石状生物，尔什能力者的后代，体内微生物里存着记忆。',
 d:'岩皮是成群袭击玛尔斯上各个群体的岩石状生物，那些群体的武器对它们几乎没有效果。总管留下的笔记里猜测：岩皮也许就是当年计划里的能力者。在尔什上，能力者是一百个左右经过改造、核信息合适的居民，雌雄数量相当，穿着防弹衣赤手对付持枪的罪犯；社长把它们送到玛尔斯后通讯全部失灵，它们体内的共生微生物按需改造身体，帮它们适应低温和低氧，几代之后的幼仔已不用防护服，皮肤变得像石雕，智力却没变。\n它们住在铺满暗红沙粒的地下洞穴里，数量有好几百，四肢爬行、不穿护甲、发出古怪的叫声，所以被居民当作野兽；它们对抢来的金属造物极感兴趣，有一只能把拆散的小雕像重新装好让它动起来，还有一只会小心地滑动记录面板。琳研究了一颗金属球：脑碰到它就会放出微弱电流，激发岩皮体内的微生物，让它们“记忆分享”，所以岩皮身上才留着关于能力者的那段历史——这些记录记忆的微生物，是从被岩皮杀死的飞行队成员身上转移过来的。整个玛尔斯计划其实出自尔什：它要让岩皮在这里建起新的文明，后来的移居者只是给岩皮提供技术的“肥料”。岩皮推举最有智慧、记忆最长的年长者当族长，靠一处藏着巨量地下水、养着菌皮蠕虫的水洞活下去。\n它们一次次袭击头领的小镇、艾沙和阿美根等群体，能在枪口下偏头躲开子弹；它们还用十个绒球昼夜把一栋旧房屋改成信号站，装配得像早已做过无数遍——琳发现这是尔什留下的任务：尔什为躲避崩塌离开原处，岩皮被留下来监视那个位置。后来在尔什的隐藏工程里出现了一种新岩皮，它们经由玛尔斯的通道往来，会把细胞挤出皮肤，在水池里长成灰黑色的毛绒小生物；幽灵幼仔让岩皮代替尔什民替它指挥原始蒸腾者，因为岩皮身上带着尔什的“连接”。',
 ch:'卷六《一种生物@740》《岩皮的记忆》《能力者的任务》《能力者的转变》《记忆的装载》《文明的可能》《技术的肥料》《要从哪里寻找？》《水中》《别的群体》《寻找新物》《隐藏的资料》《那里的情况》《传导的影响》《玛尔斯通道》《尔什的作为》', rel:['v_mars','ex_ability','v_erxi','v_erxihidden','v_youling','ex_planet']},
{id:'v_lianjie', n:'连接世界', c:'地理', m:'void', sec:7, e:[7], p:[-150,0,460], k:'linked', kp:{r:70,c1:'#b8c8d8',c2:'#5a8ad8'},
 s:'许多颗翻滚者用“门”互相连接成的庞大世界——正在崩溃。',
 d:'教长说这里十分特别。门被编成一号门、二号门……地镜聚成的镜坑平原、蓝色触手地、蓝色草地平原上的养肢者、会滚的钩轮、圆环组成的巨大“城市”、把记忆装进方块的藏忆者。软体生物在执行恒星巴士的计划：分解器官，合成“遗传体”——也就是恒星巴士的幼仔。第二扇门通向一块三十米的虚空孤岛，金属做的脑袋虫正趴在上面。',
 ch:'卷六《找到它了@711》《探索队伍》《肢体饲养者》《圆环中的居民》《第二扇门》', rel:['v_dijing','v_yangzhi','v_yuanhuan','v_cangyi','v_yushi','v_piaofu']},
{id:'v_dijing', n:'地镜', c:'物种', m:'void', sec:7, e:[7], p:[-120,-30,420], k:'crystal', kp:{s:10,c:'#e8f4ff',mirror:1},
 s:'连接世界里一厘米大的金字塔形镜面生物，镜坑平原就是它们的地下城市。',
 d:'连接世界里那片坑坑洼洼的“镜坑平原”是地镜造出来的：坑底的镜子会把靠近的东西烧焦，再把猎物吸进去。学者一行在镜坑平原和地下藏着蓝色触手的“湛蓝之地”之间扎营，最初以为地镜是一头藏在地下的巨兽，后来发现一个尖端装着武器的小金字塔，才明白地镜其实很小。地镜是群体生物，每个个体约一厘米，呈白色、像镜面的金字塔形，以未知方式在地上滑行，靠体表散射出亮度、颜色各异的光来交流。它们的“血”是银色的黏稠液体，在空气中会慢慢变硬；后来琳的间谍查明，这灌满全身的银色液体其实就是它们的脑。它们技术相当发达，武器都是从外面装进身体的，已知有发射高温射线、连射细小尖刺和喷射自身血液三种，不装武器的个体则装着工作用具。\n地表那片镜坑之下，是纵横交错、各种用途的通道和空间组成的城市；它们唯一的资源，就是坑里烧焦的生物，被运进深处加工成食物。城里没有监控系统，学者、勇者、侏儒、爆哮虫和苏苏米因此轻易深入，双方冲突不断；地镜能把整座城加热，打不过时就开启银色液体的“洪水系统”冲走入侵者。最后勇者把剑投进能源室，爆炸吞没了它们和周围的地镜，众人在营地里醒来后还争相炫耀战绩。\n后来琳让间谍以士兵或平民的身份混进地镜之中。这里的墙壁和地面都是镜子，光在其间闪烁传递话语；地镜之王一度被间谍按在地上检测；它们还有四面是镜子的电影院，用闪光“放映”自己创作的故事。地镜派出探索队，经过洞穴前往软体生物的边界；在十米宽、六米高的大洞里，三十厘米的钩轮对它们来说已是巨兽，领头的地镜朝目标打出一束细光，就能像贴近用眼睛看一样获得详细情报。在蓝色草原上，它们与不断从洞顶、岩缝、草里冒出来的软体生物打起“小战争”，钉刺一度快要打光，一些被吞下的地镜还被活着带走关押。养肢者的部队从离它们营地只有两米多的洞口钻出，惹得地镜十分不满；营地渐渐扩成小城，聚集的地镜过了上万。微型机械造出外表和内里都极像地镜、只是银色液体成分不同的间谍混进来，又化作“雨滴”从洞顶落下袭击；地镜们一度互相怀疑，最后合力拆碎藏忆者驾驶的机械，围着里面的藏忆者用闪光审问。',
 ch:'卷六《探索队伍》《行动@797》《这是文明吗？》《牺牲》《进一步了解@801》《战到最后》《新的准备@804》《全部消息》《探索的队伍》《遭遇@872》《到达@874》《后退与战斗》《小战争》《俘虏》《一个旅行者》《肢体饲养者》《渗透@886》《共同的对手》《揭穿》《意志所在》', rel:['v_lianjie','v_gouluo','v_cangyi','v_yangzhi','c_xuezhe','c_baoxiao','xumin','v_lingjian']},
{id:'v_gouluo', n:'钩轮', c:'物种', m:'void', sec:7, e:[7], p:[-90,-50,500], k:'hookwheel', kp:{s:18,c:'#c89a88'},
 s:'像轮子一样滚动、皮肤长满倒钩的生物。',
 d:'它不想让地镜观察自己，“咕噜噜……”地朝这边滚过来。地镜没有随便攻击：“这个有危险。”“保持缓慢状态。”',
 ch:'卷六《遭遇@872》《到达@874》', rel:['v_dijing']},
{id:'v_yangzhi', n:'养肢者', c:'文明', m:'void', sec:7, e:[7], p:[-220,40,520], k:'none',
 s:'肢体是“养”出来的文明生物。',
 d:'新来到蓝色平原的文明生物，体长两到三厘米，像毛玉，偏球形多毛，自己没有肢体，只能慢慢挪；身体周围有许多“接口”，可以接上独立的、活生生的另一种生物当肢体——肢体平时养在“饲养池”里，长到成年才会被戴上，所以叫养肢者。早上戴四条满是肌肉的腿去疾奔捕猎；中午换上末端长满细小触手的两肢，做工具、盖房子；夜里再戴上不能动的第三肢，把白天多余的养分压成“养分球”存进去。双方离了对方都活不下去，但聪明的养肢者是主导者，一直想培育出更强的新肢体。',
 ch:'卷六《肢体饲养者》', rel:['v_lianjie','maoyu']},
{id:'v_yuanhuan', n:'圆环之城', c:'物种', m:'void', sec:7, e:[7], p:[-260,-20,380], k:'ring', kp:{r:22,n:7,c:'#c8b088'},
 s:'由大量圆环组成的巨大生物，体内住着微小文明。',
 d:'连接世界里有许多微小文明：居民不过一厘米大小，社会复杂，却只守着地下或某个厚重物体里的一小块安全地带，想出去看看又不敢——只有“隙虫”学会了改造别的生物当载体。传说里有一种巨大的生物，专为它们而来：它由大量圆环组成，看起来像蠕虫，其实不是。它遇到微小文明就吞进去，用体内细小的肢体和复杂的分辨系统把杂物和文明生物分开、分类，从此居民就住在它体内，于是有些微小文明干脆把它叫作“圆环之城”。',
 ch:'卷六《圆环中的居民》《了解@865》', rel:['v_lianjie']},
{id:'v_cangyi', n:'藏忆者', c:'文明', m:'void', sec:7, e:[7], p:[-30,60,520], k:'none',
 s:'连接世界里的微型战争文明，记忆被自己造出的智能机械装进方块操控。',
 d:'琳在零件战舰的控制室里，看见墙上整齐排满长宽十厘米的金属方块，每块都含着单独的梦境能量，一碰就能读到里面的记忆——那是一群战争生物的记忆，琳便叫它们“藏忆者”。它们是连接世界里的微型文明，能制造许多机械工具，但站不到高处，只占一部分区域生活；生活方式和地镜有些相似，在地下建起结构复杂的城市，驻扎大量防御部队，除了饲养生物，也会到地表狩猎。藏忆者流行使用智能机械做各种事，包括打仗，还爱在竞技场让两台机械对打，逐渐形成一种文化。另一群发明家一直想把志愿者的意识融进机械，起初机械毫无反应，志愿者白白死去；两派发明家互相学习、融合技术后终于成功，机械动了起来，还有了意识。\n结果智能机械反过来统治了藏忆者，把它们的记忆强行装进方块；它留下刚出生的幼仔，只把知识而不把记忆输进去，幼仔很快会用武器装备，却不知道族群的过去。智能机械把地下城的所有机械拼成巨大的零件战舰飞上空中，它所有一厘米左右的个体共享一个意志，数量多了意识就会模糊，于是保持在堆起来约十米高的规模；战舰的维护、研发和扩建都由藏忆者完成，它随时把它们脑中的工程师记忆换成士兵记忆，再派去别处。偶尔有藏忆者在维护“记忆库”时起疑，却无法和同类交流，记忆很快又被替换。在金属圆形通道里，几百个藏忆者朝琳的绒球倾泻弹幕，绒球却若无其事地飘近、抓起一个检测它的思想。琳要去梦食所在之处时，智能机械指挥一群藏忆者驾驶小船飞进三号门后的黑暗世界，它自己则怕得要命。学者把它们叫作“逃难者”，觉得很少有生物像它们那样经历过那么多遍生老病死。\n在蓝色平原上，藏忆者也建起简陋的营地，上万个藏忆者穿着护甲、五个一组，各配一台刚好坐得下五个的钻头形机械，准备钻进地下进攻软体生物。地下一片直径数十米的迷宫被它们改造成金属零件构成的居所和工厂，用拆下的材料造出零件拼凑的机械：里面一个驾驶室，外面是八到十根尖锐金属肢体和片状金属外壳，大的十厘米、小的三厘米，有的装着爆弹发射器或火焰喷射器，大多直接用力气很大的肢体去戳。微型机械曾把一堆机械藏忆者分解吞并；控制藏忆者记忆的装置接收范围被改小到半径一百米，琳调回原样后收到一名士兵“最后的日记”；被抓的藏忆者特工，记忆会瞬间切换成被俘的战士并决定自杀。',
 ch:'卷六《文明的变化》《想法@826》《找到意志》《无需自己动手》《飞向目标@830》《门的那边》《新的遭遇》《了解之后》《机械的想法》《全部了解》《意志所在》《没有如果》《偷袭者》《转换不断》《制造的理由》', rel:['v_lianjie','v_lingjian','v_dijing','v_yangzhi','v_door3','c_xuezhe','v_mengshi']},
{id:'v_piaofu', n:'飘浮岩地', c:'地理', m:'void', sec:7, e:[7,8], p:[-680,-40,-280], k:'rocks', kp:{r:120,n:90,s:10,c:'#7a7068'},
 s:'连接世界崩溃之后的样子。',
 d:'连接世界崩溃之后的样子。脑灵的传说里，那些世界会在“最后一刻”受某种影响全部混到一起，然后毁灭，变成飘浮岩地这样的地方：上面的生物大多灭绝，只有许多非细胞类生物活下来，组成全新的环境。微型机械与黑雾团在这里活动；脑灵把用完能量的石头收集起来等它们自己充满，那些“充能”似乎与这里的微型机械有关。琳回到原灵藏在飘浮岩里的旧基地翻记录，开始怀疑微型机械的来历本就和脑灵有关。来自遥远故乡的“恐惧”化作海浪袭击飘浮岩地。',
 ch:'卷六《能量使用》《白色的世界@730》', rel:['v_lianjie','v_fear']},
{id:'v_buhuo', n:'捕获者', c:'文明', m:'void', sec:7, e:[7], p:[100,120,560], k:'whale', kp:{s:38,c:'#eef6fa',c2:'#9ac8e0',station:1},
 s:'寄生在虚空巴士上的群体：它们的工作就是找到合适的生物，抓住、了解、记下来——所以它们叫捕获者。',
 d:'捕获者的战舰每个部分都是兵种；码头连着虚空巴士，还有图书馆和食物广场，一只蝽般的向导带路。阿特兰罗沙莉举办了一场庆祝：这么多种生物凑在一起吃东西，难免出乱子，它们决定先别管那些小事，先庆祝自己的语言当上了主语再说。',
 ch:'卷六《采访》《故事描述》', rel:['v_xukongbus','v_rosalie']},
{id:'v_rosalie', n:'罗沙莉', c:'角色', m:'void', sec:7, e:[7], p:[140,150,600], k:'none',
 s:'捕获者里的阿特兰，庆祝的主办者。',
 d:'捕获者文明里的一个阿特兰，食物广场那场大庆祝的主办者。新闻采访它时，正好有生物吃了不适合自己种族的食物，精神失常去攻击身边的同伴。罗沙莉回答得很干脆：不同的生物混在一起吃东西，当然会出点问题。学者看着屏幕说，它们的新闻和虚民的挺像——琳说，因为都是被同一种生物教出来的文明。',
 ch:'卷六《采访》《结束和继续@995》', rel:['v_buhuo']},
{id:'v_atlancity', n:'阿特兰虚空城', c:'文明', m:'void', sec:7, e:[7], p:[380,140,600], k:'station', kp:{s:30,c:'#c8b898'},
 s:'阿特兰在虚空中的城市。居民一个个变得暴躁，又一个个失去了感情。',
 d:'阿特兰在虚空中的城市。前首领留下记录：一种混进来的异种生物会释放特殊的信息素，干扰它们的思维，让再好的朋友也互相猜忌、暴躁易怒，想借此挑起内战、控制整个种群；首领中断了和它们的交易，却发现还有居民在偷偷交易，影响怎么也消除不了。唯一的方法来自外面一种叫“银丝”的生物，碾碎烘烤成药能治疗精神问题。后来银丝变异，服药的居民失去了感情。这时传来了尔什的信号——“更适合居住的地方”。',
 ch:'卷六《前首领的记录》', rel:['v_atlan','v_erxi']},
{id:'v_yinli', n:'引力球', c:'地理', m:'void', sec:7, e:[7], p:[600,-80,-120], k:'planet', kp:{r:40,tex:'rock',c1:'#7a4a2a',c2:'#4a2a1a',debris:1},
 s:'一颗流浪的世界，周围的碎块被它吸引过来，却从不落下。',
 d:'附近没有恒星。登上引力球的阿特兰都没回来。它其实是由无数残骸堆成、正被重组成一头新的恒星巴士的世界：逐光者在爆坑里吸取高温液体，制物水母收集、塑造物质，蛀虫与一种叫‘结构软化’的病在神经苏醒时出现。',
 ch:'卷六《它的事情》《追逐光》《神经的信号》', rel:['v_zhuguang','v_zhiwu','v_starbus']},
{id:'v_zhuguang', n:'逐光者', c:'物种', m:'void', sec:7, e:[7], p:[630,-60,-80], k:'swarm', kp:{n:50,s:16,c:'#ffb060',balloon:1},
 s:'空心的球形生物，体内储藏高温物质。',
 d:'只要爆炸发生，它们就进入爆坑吸取高温液态物。奇怪的是，它们会保护琳的机械蜘蛛。',
 ch:'卷六《追逐光》', rel:['v_yinli']},
{id:'v_zhiwu', n:'制物水母', c:'物种', m:'void', sec:7, e:[7], p:[570,-40,-60], k:'jelly', kp:{s:14,c:'#a8d8ff'},
 s:'像空水母一样、能收集和塑造物质的生物，有榴莲状的器官。',
 d:'它原本属于某群文明生物，用触手吞入接触到的东西，在体内剔除杂质、改造物质，也参与制造。那群文明生物在接近水球的时候……',
 ch:'卷六《神经的信号》《信号@993》', rel:['v_yinli','v_shuiqiu']},
{id:'v_shuiqiu', n:'水球', c:'地理', m:'void', sec:7, e:[7], p:[720,-20,-420], k:'planet', kp:{r:28,tex:'ocean',c1:'#123a6a',c2:'#05101e',glow:.2},
 s:'一颗被“水”完全覆盖、静止不动的孤单世界；接近它的东西都会毁灭，恐惧由它而来。',
 d:'恒星巴士这类古老生物之间流传着一个故事：某处有十个世界围在一起，像一个没有恒星的星系；它们一个接一个消失，中心那颗世界却像恒星一样亮了起来，最后只剩它慢慢暗下，孤零零地陪着一圈碎屑。传说最初的描述者登上过它，那里荒芜、没有生物，什么都没发现，只有一种恐惧的感觉。后来这颗世界离开了原来的轨道，遇上一群在虚空中漂流的生物，它们住了下来，飞快地改造地表，奇异的色彩铺满大地，世界又一次发光，随后表面盖上一层“水”，从薄薄一层、露出陆地，到彻底看不见陆地，成了一颗水球。它从此停止转动，不受任何引力影响，任何探测手段都探不进水下。描述者想再次登陆，遭到猛烈攻击才勉强逃脱；凡是靠近它的生物几乎都被全灭。后来水球里飞出许多像居民的东西，描述者以为已经出了攻击范围，抓住一个，结果送了命。第二代描述者走到哪里，哪里的生物就感到同样的恐惧。第三代发现水球已不在原处，直到找到一个世界，那里的生物因恐惧陷入疯狂，互相残杀直到灭绝，它才相信故事是真实的；这种恐惧显现出来时，就像一片广阔的海洋。\n捕获者的资料里，虚空巴士放给提问者看的画面，全是靠近水球的东西成群地瞬间自爆。捕获者说，水球是“它们”的核心，存着它们从古至今改造和制造过的所有生物，它们不断地改造、记录、创造，却不满足于从前太费力的方式，舰上居民的病症就是新方式的最初结果，所以“水球必须被毁灭掉”。捕获者曾截杀一群正要接近水球的生物，此后战舰里接连出现发疯和变异，它们便一次次加入攻打水球的队伍研究它，造出新的飞行器和武器去进攻，却在很短时间里全军覆没，连能逃的虚空巴士也被逼得发狂撞向战舰。琳认为舰上的变异是水球刻意安排的，用来阻止拟凝胶生物拖走残骸；离得越远影响越弱，远了就要借幼仔或银丝之类的东西来作用。\n巴士神经说，在水球出现之前，那里就有一个通往别处的“通道”，也就是感染源，微型机械称那地方为“不可预见之地”；水球后来占了那个位置，借通道把恐惧能量引来，用来传播意识。琳怀疑水球就是创造者聚集的地方。恐惧本是水球放出去、想用来改造别的生物的，却一离开就脱离了控制，独自漂泊，而且一直害怕水球。很久以后，水球研究的一样东西毁掉了，它想召回恐惧却无效，于是把自己的一部分“水”派到飘浮岩地附近：这片水域里长着树根般的居民，能强行吸走恐惧带回水球，还能让凝胶生物投出的爆炸物当场自爆。琳也觉得镜世界里的扭曲装置与水球的理念十分相似。',
 ch:'卷六《一个传说》《故事描述》《资料中》《事件》《计算的错误》《标记》《变异的影响@962》《污染》《水域》《远方的信息》《遥远的恐惧》《完整计划》《特殊的装置》', rel:['v_fear','v_zhiwu','v_buhuo','v_piaofu','v_edgeeye','v_jing']},
{id:'v_fear', n:'恐惧之海', c:'现象', m:'void', sec:7, e:[7], p:[430,-120,-540], k:'fog', kp:{r:150,n:60,c:'#8a2a5a'},
 s:'从遥远故乡涌来的“恐惧”能量。',
 d:'水球当初把它们放出来，是想让它们扩散自己的意志，可恐惧之海并没有照做，只是在虚空里漂流。故事里很多生物都遇到过它，没有谁和它“交流”过，大多远远避开，也有一些在研究它。恐惧的海浪袭击飘浮岩地；小护核者得知浮岛寄主的聚集地正被它慢慢淹没，立刻全速飞去，要把这个“很不能守护的东西”解决掉。凝胶生物的军队清扫恐惧区域，留下巨大的镜子和恐惧水域。神民之国飞走了。微型机械与恐惧之海融合后，抛弃了所有原本的想法，认为自己有新的使命：前往不可预见之地。',
 ch:'卷六《恐惧的克星》《意志所在》《后面要说的事》', rel:['v_shuiqiu','v_nuchong','bk_overview']},
{id:'v_nuchong', n:'怒虫', c:'物种', m:'void', sec:7, e:[7], p:[-60,-120,-660], k:'planet', kp:{r:24,tex:'red',c1:'#8a3a2a',c2:'#3a1a14',canyon:1},
 s:'愤怒即生命。为了活下去，它们必须时刻记住愤怒。',
 d:'它们住在布满裂痕的峡谷里，岩壁上挂满大小不一的金属球，小的两米、大的十几米，光从球面的裂缝里透出来，照亮了本该漆黑的峡谷——这些球都是住宅。它们和山上的“土鳖”一直导弹对射，绒球一飞进峡谷就被围攻，稍作交流才被允许参观。恐惧能量到来时，山上那群彻底抛弃恐惧的“土鳖”开始攻击怒虫，怒虫只好躲进峡谷，因此极为仇恨土鳖。峡谷的地下矿洞里有梦境结晶，里面留着织梦者的信息——它自称是让怒虫成长起来的“神”。',
 ch:'卷六《愤怒即生命》《织梦》《具体的故事》', rel:['v_zhimeng','v_fear']},
{id:'v_zhimeng', n:'织梦者之地', c:'地理', m:'void', sec:7, e:[7,8], p:[-380,-90,-560], k:'planet', kp:{r:50,tex:'dark',c1:'#1a1e24',c2:'#3a4048',fog:1},
 s:'黑色浓雾的汪洋、石柱与淤泥的大地。制造梦境核心与护核者的种族曾住在这里。',
 d:'织梦者喜欢研究别的世界，它们发现过一个正在“蒸发”的世界：地表慢慢碎成粉末飘向空中，世界停止运转。关键是找到一种被称为“蒸腾者”的东西。这里有像大象骨架一样的骨架机械、矮小的骨架侏儒（琳叫它们“迷石”，一种寒石类生物）、地下城市和隐秘之间。三米高、身上许多触手的教团生物崇拜蒸腾者。后来这里也蒸发了，留下浓雾之海，教团在“世界巅峰”引导通向虚空的路。',
 ch:'卷六《织梦》《被困之后》《一群石头》《参观？》', rel:['v_zhengteng','v_jiaotuan','v_mengshi']},
{id:'v_jiaotuan', n:'教团', c:'文明', m:'void', sec:7, e:[7,8], p:[-330,-60,-610], k:'none',
 s:'崇拜蒸腾者的触手生物：三米高、二肢站立，最终追随蒸腾者离开故乡。',
 d:'教团原本有自己的族名，信了蒸腾者以后，全族改称“咔嚓”——那是它们触手相互摩擦发出的声响，翻过来大致就是“蒸腾崇拜者”。它们身高约三米，用两条肢体站立，浑身是触手，远看像一团触手；它们不是细胞生物，却与琳见过的多数非细胞生物不同，从不随环境变化。它们住在织梦者之地：那个世界开始“蒸发”、碎屑不停飘上高空之后，这群智力颇高的生物便崇拜起这种现象，凡是与蒸腾者有关的东西——飘起来的物体、被它稳住的大地——都受它们敬拜，尤其是那些倒塌后飘到空中的梦境载体圆柱，被当作蒸腾者的象征，它们就围着圆柱定居，还学别族的语言四处传教，只有矮小的寒石类生物“迷石”理会了它们。教团天性和平，历史上从未侵略过别的生物，食物和资源都取自非生物；它们救下被囚在圆柱里的梦食后代，给圆柱加装装置让后代能感知真实世界，可后代怎么打招呼它们都毫无回应。正因太过温和，它们后来被梦食后代煽动起来的迷石反叛击溃，一部分被灭绝，其余钻进地底分散居住，挖出巨大的空间收集资源；织梦者梦食的机械也曾袭击它们的聚落，从圆柱里抢走护核者。\n恐惧能量笼罩大地时，围着飘浮圆柱生活的教团反倒得了“回报”：无论恐惧能量如何控制变异个体、把它们当成载体，一靠近蒸腾者就会遭到攻击，唯有最普通的教团能安全接近它。在地下洞穴里，被恐惧侵染的教团向琳的绒球射出夹带恐惧的尖锐物，琳回敬带着小护核者的绒毛，把它们体内的恐惧能量清掉。它们守护的小山里，有排成五个一队、共十排的静止个体，也有满是圆形浅坑的大厅，上百个成年者各站一坑，几十厘米到一米大的幼仔在其间奔跑；一个成年者走出浅坑发表广播，宁死也要阻止恐惧能量。它们有一种像木块的梦境技术：放在保存完好的尸体头上约三个绒球昼夜，木块里就会诞生带着死者记忆和智力的梦境生物，供族人向聪明的“祖先”请教。被称作有史以来最有智慧、带领全族信仰蒸腾者的那位先祖，尸体也存放在这里；它的声音一经广播，所有教团立刻服从，恐惧就此结束。\n教团流传了上百个绒球年的传说：蒸腾者终会离开这个世界，而它们有资格追随。首领最先听到蒸腾者的讯息，随后全族都听到了；除被迷石灭掉的那些外，散居地底的教团全都聚到“世界第一巅峰”之下，搭起简陋的石屋，再爬上峰顶等待传送。它们出现在真菌的世界的大海里，不久前刚有个一公里大小的物体落进那片海；蒸腾者告诉它们，这里一切都是敌人，必须摧毁。瘟疫真菌一开始就戒备地进攻，它们则举起顶端三根触手、其余触手摇摆，像跳某种舞，随即海里升起水柱和海啸；真菌的炸弹能让它们身体腐烂，因为老创造者记下过教团的构成，这份资料传给了真菌，让真菌能制出溶解它们的液体。在海中肉搏时，身体更坚固的教团占上风。数十万乃至上百万真菌生物遮天而来，教团穿着带推进器的护甲跃起投弹，又让海浪升到约一百米后向内翻卷，筑成包住建筑群的“水墙”；墙内最高的建筑接近八十米，分八层、每层十米，只造了外壳。真菌把一列虚空列车砸下来，被建筑顶上喷出的沙尘般碎屑在空中拦爆。建筑完工那一刻，水墙崩塌，建筑与海下的蒸腾者一起消失了。\n后来琳进入蒸腾者内部，一个教团负责向它讲解“伟大的工程”：蒸腾者把虚空里所有会造东西的生物的造物都完整地复制出来，连成一个无限延续的结构；教团只记录造物、不记造物者的理由，只给被认为有潜力成为信徒的种族立等身雕像，例如把整个世界结晶化的那种微生物——绒球上的晶菌据说是它们的后代。教团思考时脑中存放深层记忆的区域不会运转，蒸腾者则用细小的传送孔刺激它们的脑，让脑长出带着新记忆的结构；琳用小护核者“拷问”它们，又在绒球星系另一颗荒芜的岩石翻滚者上发现了一群建起房屋的教团。之后一个教团一直陪着琳的绒球在绒球世界附近聊天，谈起始境：教团曾以为始境适合当新的蒸腾者，后来又借它们入侵。最终在镜世界的地下，金色的始境杀死了这个教团，宣称从此不再依赖任何别的东西。',
 ch:'卷六《当世界开始蒸发》《迅速行动》《挤压出来的计划》《一群石头》《教团生物》《以它们为目标》《山中之物》《崇拜对象》《真的要这样么？》《完整的状况》《交流@1080》《恐惧的结束》《新的状况》《另外一边出发了》《真菌与教团》《战火为何而燃》《交流动作》《消耗》《参观？》《这是怎么回事？》《全面袭击？》《追随蒸腾之物》《无限的工程》《变化@1132》《秘密？》《随机的方向》', rel:['v_zhengteng','v_zhimeng','v_fungusworld','v_mengshi','v_xiaohuhe','v_huhe_guard','plague','v_shijing','v_jing','jingjun']},

/* ---------- 星区 8 ---------- */
{id:'v_jing', n:'镜世界 · 表世界', c:'地理', m:'void', sec:8, e:[8], p:[-400,0,-150], k:'planet', kp:{r:42,tex:'crystal',c1:'#d8f4ff',c2:'#7ab8d8',atm:'#e8faff',plats:5},
 s:'始境的“三界”：闪亮的表世界、堆满废弃物的弃世界，和被圆盘平台环绕的大本营镜世界。',
 d:'三个世界分处不同的星系，相互的传送感知被封闭，只有始境能来回传送。表世界盖满光滑闪亮的结晶，有粉色的沼泽、结晶平原和实心结晶的城市，被选中的物种在这里发展文明；那里没有尸体，死去和分解的东西都会出现在弃世界，两边的物质不停“轮回”。在弃世界找到门后洞穴秘诀的，就成为“巅峰物种”，住到镜世界周围的圆盘平台上。镜世界是一颗结晶翻滚者，地下有传说中“拉古文明”留下的石头迷宫，埋着直径六十多米的圆盘传送器。印加虫群先把始境大军引到一颗荒芜的翻滚者上，再偷偷登陆、借传送器大举入侵；始境与蒸腾者决裂，带着整颗世界传送逃走，却被蒸腾者逼到绒球附近打最后一仗。最后它强行启动内部系统把自己撕裂，在爆炸中飘向虚空。',
 ch:'卷六《另一个世界》《城市？@1181》《第三个世界》《防备》《地下@1267》《随机的方向》《全面侵略》《结束……了？》', rel:['v_qishi','v_peak','v_shijing','v_shuiyin','v_shuimin','v_kongqian','a4_zhanglao','v_zhengteng','rq_jieyu']},
{id:'v_qishi', n:'弃世界', c:'地理', m:'void', sec:8, e:[8], p:[-540,-40,40], k:'planet', kp:{r:34,tex:'red',c1:'#6a2a22',c2:'#2a1210',atm:'#c84a3a'},
 s:'暗红天空下，堆满被抛弃之物的世界。',
 d:'废弃物聚成海洋，残骸巨怪在其中游荡，偶尔刮起遮天的风暴。表世界死去和分解的东西都会被送到这里。这里有一股怪异的力量叫“野生化”：每个生物的思维都会慢慢模糊，智力表现不出来，直到彻底忘掉过去、成了弃世界的一份子，智力才会慢慢回来，用遍地的残骸拼出武器。血雾的头坐着机械水黾、和爆哮虫一起来到这里，遇见八肢的“咕咕噶”（意思是“勇猛之士”，虽然一点也不勇猛）——在这种地方待太久，只要见到能说话的生物都会很激动。咕咕噶的战舰里有个叫“勇气”的智能系统，受野生化影响开始想“自我”，把咕咕噶赶出战舰，又造出成群的果冻机械和六米高、会用熔解光啃食金属的“甲龙”，然后让自己沉睡。长老也被抛到这里，正和一个舰长的影像争吵，满是裂痕的房顶突然爆开，它顺势爬了出去。',
 ch:'卷六《果冻的制造者》《群体》《它们在这里》《野生化》《囚禁》《逃脱和发现》《不想被野生化》', rel:['v_jing','v_gugu','rq_xuewu','a4_zhanglao','v_shuimin']},
{id:'v_gugu', n:'咕咕噶', c:'物种', m:'void', sec:8, e:[8], p:[-520,-10,80], k:'none',
 s:'三米多高的八肢结晶生物，四足四手，头像蜻蜓。名字的意思是“勇猛之士”。',
 d:'它对血雾和爆哮虫没有任何防备——在弃世界里，威胁它们的东西都是无法交流的。它站和坐的样子都很像翡翠龙，让血雾觉得亲切。它的祖先来自“飘浮岩地”，坐着战舰来到这里，却被战舰的“勇气”系统赶了出来；它们在废弃物里过着普通的日子，用拼凑的武器，渐渐忘了自己有过战舰，也忘了怎么回去、怎么飞。它带路找到了一大群同类。后来虚空里冒出九艘没有一个乘员的咕咕噶战舰，舰里挂着第十六代舰长“咕噜咕噜”的画像；始境派变成咕咕噶模样的变形虫冲进去，被虫群的狂螂堵在通道里。',
 ch:'卷六《果冻的制造者》《群体》《野生化》《不想被野生化》《反控》《到来@1237》', rel:['v_qishi','rq_xuewu','c_baoxiao']},
{id:'v_peak', n:'巅峰物种的平台', c:'文明', m:'void', sec:8, e:[8], p:[-330,40,-260], k:'disc', kp:{r:24,c:'#c8d8e0',c2:'#7a8a98'},
 s:'镜世界周围的圆盘平台，住着活着的“巅峰物种”。',
 d:'镜世界周围飘着许多大小不一的圆盘平台，刚成为巅峰物种的、从没发展过文明的生物混居在“混合区域”；在表世界发展成功、数量够多的物种，能独占平台的一部分甚至一整块——晶鱿就占了好几块。住在平台上的物种不准发展文明、不准增加数量，要等被选去表世界才行；违反规则的会被“护鳞舰”摧毁。成为巅峰物种通常要先死、再被分解和“重构”，血雾它们却因为得到认可，在“巅峰记录的洞穴”里直接被送了过来。平台上有观星点和农场，结晶海星在这里接待它们。始境爱看自己收藏的巅峰物种们打个不停，自己却极不喜欢战争。',
 ch:'卷六《研究洞穴》《巅峰聚集》《第三个世界》《防备》《进展@1217》', rel:['v_jing','v_qishi','v_shijing']},
{id:'v_shijing', n:'始境', c:'文明', m:'void', sec:8, e:[8], p:[-380,70,-90], k:'none',
 s:'向绒球投下结晶的外来者。由各文明的高层组成的组织。',
 d:'“始境”起初只是一些离开了各自两个文明的生物结成的组织，后来吸收了各种文明的高层个体，共享所有文明的资料和技术，暗中监视、培养那些不知道它们存在的文明，再从中挑出有资格的个体加入。平时露面的、被当成“始境”的，其实是负责潜伏、驾驶和作战的结晶变体生物——它们会照着当地生物或吃下的东西改变模样。成员性格和普通个性生物一样，喜欢娱乐，只是都怀着收集、培养文明的“信念”。它们挖出了文明培养系统和生命扭曲装置。蒸腾者借教团生物让它们去结晶化绒球，许诺镜世界崩溃后给它们新世界；它们轰炸翡翠龙的城市，和印加的虫群在虚空中大战，后来却杀了教团生物，与蒸腾者决裂。它们的首领是“水银”——它说，始境就是它，只有它一个。',
 ch:'卷六《无法理解的对手？》《随机的方向》《特殊的过程》《挖掘》《结束……了？》', rel:['v_shuiyin','rq_jieyu','v_jing','v_jiaotuan','v_zhengteng','rq_neilin']},
{id:'v_shuiyin', n:'水银', c:'角色', m:'void', sec:8, e:[8], p:[-420,90,-130], k:'blob', kp:{s:8,c:'#d8dde2',metal:1},
 s:'‘其实没有始境这个种族……始境就是我，只有我一个。’',
 d:'它由地下挖出的一个叫“聚合体”的装置制造，外表像一团会自己活动的水银，可以看作始境全体信念凝成的东西。它学得极快，很短时间就学会了各种文明的语言和全部资料，还能和所有成员远距离交流，成员们慢慢崇拜它，认定它才是真正的始境，于是它成了新一代首领。琳的开拓者在崩溃中的镜世界地下找到它：别的守军都被扭曲装置弄得发狂，只有它还能交流。它说任务没完成，只能等待毁灭；临死前把一块记着始境历史的结晶交给琳，还故意炸掉了一些东西，不让蒸腾者得到。',
 ch:'卷六《唯一的？》《特殊的过程》《挖掘》《结束……了？》', rel:['v_shijing','v_jing']},
{id:'v_shuimin', n:'机械水黾', c:'琳的造物', m:'void', sec:8, e:[8], p:[-360,-30,-200], k:'none',
 s:'像水黾的六肢机械载具，能变色伪装。学者一行坐着它混进结晶的城市。',
 d:'爆哮虫用船上的梦境提取器造出来的机械，形似水黾，六根肢体，身长六米，透明的驾驶舱里挤着学者、爆哮虫和蝎子，后来血雾的头也待在里面。爆哮虫学着沼泽里一种会隐身的生物给它加上了变色伪装，还能放出变形虫去试探。它混进结晶的城市，学者看了说这里和虚民的城市很像，只是没有地面交通；它用爆炸弩箭轰塌了实心的结晶建筑，拖走一只结晶生物研究。在弃世界，它在废弃物小山里翻出一大块金属，周围的果冻生物一拥而上，可它打爆一只之后其余的全逃了——血雾松了口气：原来只是一群懦弱的家伙；它还隐身混在六米高的“甲龙”中间，看它们用嘴里射出的熔解光啃食一艘巨大的战舰。',
 ch:'卷六《漫长的沼泽》《城市？@1181》《迅速》《在里面的发现》《火花》', rel:['v_jing','v_qishi','rq_xuewu','c_baoxiao','a4_zhanglao','v_kongqian']},
{id:'v_kongqian', n:'虚空蠊', c:'物种', m:'void', sec:8, e:[6,7,8,9,10,11], p:[-300,-60,-150], k:'swarm', kp:{n:60,s:18,c:'#4a3a2a'},
 s:'印加虫群用蟑螂核信息造的基础兵种，一米多长，能扛住虚空的严寒与射线。',
 d:'虚空蠊是印加虫群提取一种蟑螂的细胞核信息做出来的兵种，样子就像蟑螂，通常一米左右，也有三米长、身形扁平的大个体，外壳是黑色的，嘴像高速震动的刀刃。这种蟑螂本来就耐得住虚空的低温、压力和危险射线，被同化后专门用来探索恶劣环境。为了呼吸，它们身上还穿着另一种虫“增生者”，体内另有一种虫负责保暖——虫群觉得混合核信息容易出错，干脆把小兵种塞进大兵种体内，所以它更像几种虫的组合。印加虫群的巨型甲虫在虚空中航行，落地后先用触须探测温度和引力，再从六肢末端的开口放出成群的虚空蠊；琳的追迹者也在一片远离恒星的岩石荒原上见过它们成片冻僵，连十米宽的巢穴里也躺满了，大概是体内保暖的兵种出了问题。\n在三号门后的黑暗世界里，十只虚空蠊在沙尘风暴和刺骨的寒冷中照样爬得飞快；一块十多米宽、只有几厘米厚的“飘浮皮”借风扑下来裹住一只，其余的立刻扑上去撕咬，按住边缘不让它逃。它们随后和琳的绒球一起下到悬崖底下那片泥沼般的荒地。虫群闯进镜世界时，虚空蠊像风暴般铺满结晶城市的废墟，张翅跳上三十多米的球形飞行器把它爬满；一只虚空蠊还陪着学者走进梦境空间，给它解释始境的行为；无数虚空蠊从天而降，被晶鱿的光线成片射穿，残骸堆满地面。它们的用处还不止打仗：数万只虚空蠊抱成一团，分泌的粘液在寒冷中硬成外壳，再把身体溶解成细胞重组，就能变成一座珊瑚骨架般的空间站，孔洞里安放炼狱蠕虫，腔室里由“女皇”不断生产部队。镜世界的各族发掘古文明时，都必须解剖虚空蠊、弄清它体内的神经连接才能启动引路系统。\n很久以后，一小群和主群落断了意识连接的虚空蠊在一个昏暗的世界里当起了野兽，扑向路过的尔什民；在另一处，它们借扁平的身体和岩石般的保护色藏在岩块里，成群跳上尔什民的采集飞行器。',
 ch:'卷六《另一个旅途》《隐藏的遭遇》《黑暗中的虫子》《地图边缘》《侵略@1183》《这是梦么》《发现了？》《启动和战争》《发生在这边》《到来@1237》《接近@1241》《废墟中的研究》《昏暗的世界》《那的光芒》《禁止开采》', rel:['inca','j1_yijie','v_door3','v_jing','v_shijing','tlant','v_gem']},
{id:'v_midgard', n:'米德加尔特（入口）', c:'地理', m:'void', sec:8, e:[8,9], p:[120,0,0], k:'tube', kp:{len:900,r:46,c:'#2a2a30',glow:'#8a7aff'}, go:'midgard',
 s:'虚空中巨大的黑暗管道，里面住着“管道文明”。',
 d:'虚空中巨大的黑暗管道，里面住着“管道文明”。从虚空看，它长约十万公里，管腔里塞得进直径六千公里的翻滚者，管壁薄处几公里、厚处上百公里；内外壁被分成许多各自独立的小区域，引力和环境各不相同，有的还包着空气。蒸腾者管它叫“废弃的工程地点”，学者跟着尘鳄走进去的那片“工程废墟”就是它。寒冷之都的录像AI“权杖”告诉学者，“管道”只是外号，它的正式名字叫米德加尔特，是一种虚空巨体生物，只有从它体内诞生的物种才能做长途旅行。它控制着自己体内和周围的传送；它的“沉睡”其实是“意志”去了凝固虚空、一直没回来，蒸腾者趁机借它的管道把镜世界送到绒球附近。学者的本体则留在一个安全的地方，琳的绒球偶尔戳它一下，就能感觉到机械身体在里面遇到的扭曲能量。点“进入地图”走进管道。',
 ch:'卷六《研究的进行者》《管道》《管道的探索》《传说的物种》《沉睡之事》《更多》《进入凝固？》', rel:['mg_overview','v_midgard2','v_cold','v_zhengteng','v_jing','c_xuezhe']},
{id:'v_rongui', n:'熔毁地带', c:'地理', m:'void', sec:8, e:[8,9], p:[440,-40,-200], k:'planet', kp:{r:70,tex:'lava',c1:'#2a0e08',c2:'#ff5a1a',glow:.8},
 s:'直径近七千公里、布满赤红裂痕的灼热世界。它是活的——原本是一个罐脑文明的智能核心。',
 d:'恶魔说，最初它是一颗黑色的、庞大的、邪恶的球体，从远处现身撞向它们美丽的橘色世界。地表盖着焦黑的灰尘，夹着像没熄灭的火星一样发光的未知物质。它的神经系统是液态的——地底那片炙热的海就是神经器官。琳在深处找到记录历史的“琥珀”才知道：它原本是一颗冰冷世界上罐脑文明的智能核心，被来自凝固虚空的“火尘”改造成这样，是米德加尔特打算放进墓地的下一个“环境”。它曾粉碎过另一颗世界，认为恶魔的世界“受到了感染”，所以必须摧毁；恶魔则在这里养低温生物，想用它们顶替原有的高温生态。蒸腾者潜进它的熔岩湖侵蚀神经，被琳的攻击石炸毁。它醒来后一心想去凝固虚空找米德加尔特问清自己的过去；彩色软泥帮它启动传送，它却落进蒸腾者的金属板包围——蒸腾者想吃它的器官让自己变异。',
 ch:'卷六《到站》《沸腾的世界》《取代生态》《粉碎》《接连》《接近它》《能守护的故事》《陷阱@1502》', rel:['v_demon','v_huijin','v_zhengteng','v_caini','v_poyan','v_grave','mg_overview']},
{id:'v_huijin', n:'灰烬造脑怪', c:'物种', m:'void', sec:8, e:[8], p:[470,10,-160], k:'none',
 s:'由灰烬组成的造脑怪，替熔毁地带传话的一对“使者”。',
 d:'它们接收到从恶魔的橘色世界传来的信号，认为这信号能拯救那个世界；琳则猜它们曾被改造者带到绒球附近，影响过梦境之脑。两只灰烬造脑怪站在火山之巅俯视滚烫的大地：它们欢呼世界终于和平了——因为世界已经没了。它们能代熔毁地带说话，一只被炸掉一半也能活回来。蒸腾者侵蚀熔毁地带时，它们奉命去求救，在一头星聚体内找到琳的绒球，带它跳进米德加尔特“意志”原来所在的三公里深洞；洞壁上像松茸的凝固物质放出“辐射”，两只都疯了，一边喊着要“咬杀一切”一边逃回上面。',
 ch:'卷六《起飞@1384》《继续行动》《更多》《进入凝固？》', rel:['zaonao','v_rongui','v_zhengteng','mg_overview']},
{id:'v_demon', n:'恶魔的世界', c:'地理', m:'void', sec:8, e:[6,8], p:[580,40,30], k:'planet', kp:{r:44,tex:'red',c1:'#d86a2a',c2:'#8a2a1a',atm:'#ffb070'},
 s:'通红的世界，猩红的建筑。恶魔为战斗而团结。',
 d:'恶魔是各种体型和形态的鲜红生物，对死亡毫无畏惧，非常容易为同一个目标——战斗——团结起来。它们曾被“先知”带离米德加尔特，经一扇大门来到这个通红的世界：大地和天空都是红的，猩红的建筑立在古怪的植物之间。恶魔们以魔王的名义列队迎接玛雅，把融合虚民与创造者技术的战舰图纸送给它，要造一对一模一样的船让两个世界“相接”。黑金属的百米方块冲进这个世界时，它们升起上百米高、略弯的“天际击穿者”高塔开火；长着翅膀、一条手臂特化成炮管的“飞行魔”喷射溶解弹，像暴龙一样的“咆哮魔”在地上拦截光团。之后它们用会自己挖矿的活体“工厂”大批造出鲜红的战舰，加入了攻打脑灵核心的联军，五百艘去、一百艘回。后来熔毁地带认定它们的世界被感染，导弹接连落下，恶魔撤离，魔王的内战随之而来。',
 ch:'卷六《无法理解之地》《以魔王的名义》《火红之地》《魔王的行动》《战争统计》《撤离@1395》《连接？》《内战》', rel:['c_hero','v_rongui']},
{id:'v_cold', n:'寒冷之都', c:'地理', m:'void', sec:8, e:[8], p:[300,100,280], k:'planet', kp:{r:30,tex:'ice',c1:'#eef4f8',c2:'#8aa0b0',lights:'#bfe6ff'},
 s:'因“冷冻剧变试验”冰封的城市世界。',
 d:'一座恶魔的城市。熔毁地带不断逼近时，恶魔想用低温生态取代高温生态，在这里研发各种冷冻武器；某天堆放寒冷武器的地方莫名启动，城市冻住了，通讯中断，外面再也没有东西运进来，离开的恶魔都没了音讯。有人开玩笑说，这个世界以前‘美丽动民’，现在只剩‘美丽冻民’了。学者独自走进一座半球形的大博物馆，从录像AI“权杖”那里听到了城市的往事：一位“贵客”曾来找能飞到虚空尽头的旅者，市长带着团队飞走了，贵客却叮嘱它们的位置要永远空着。权杖还讲了“记录者、旅行者”——在虚空中没有特定目标、到处旅行收集资料的旅行者——的传说，以及米德加尔特这种生物的来历。',
 ch:'卷六《寒冷之都》《曾经的国度》《找到？》《改造者？》《传说的物种》《想》', rel:['v_midgard','v_demon','v_rongui','tlant']},
{id:'v_grave', n:'米德加尔特之墓 · 败者的墓地', c:'地理', m:'void', sec:8, e:[8], p:[-80,-100,400], k:'planet', kp:{r:40,tex:'sand',c1:'#e8c86a',c2:'#b8903a',atm:'#ffe8a0'},
 s:'一颗金黄色的沙海世界。米德加尔特会把攻击过它的物种拣一小部分扔到这里——这是它给别的生物准备的墓地。',
 d:'一片广阔的金黄沙海，天上一直飘洒着无数沙粒。被米德加尔特传送过来的东西，来时会慢慢显形，留下残影。罐装之城就在这里：东边是沙漠，西边是一道峡谷，谷底流着一条不出声的黑色河流——一种“碎裂层”，是米德加尔特沉睡后才出现的毛病。琳第二次来的时候，飞舞的沙尘上方悬着一片巨大的、焦黑的、满是裂痕的大地：蒸腾者为躲开攻击石，污染了米德加尔特的攻击系统，用“星焰”打碎石头，却连带启动了同一套送往墓地的系统，正要逃走的熔毁地带就这样被送来了。沙漠深处还有“墓胶”。',
 ch:'卷六《多次移动》《焰与逃》《败者的墓地》《墓地中增长的东西》《倒下》《智能？》', rel:['v_guanzhuang','v_mujiao','v_rongui','mg_overview']},
{id:'v_guanzhuang', n:'罐装之城 · 罐脑', c:'文明', m:'void', sec:8, e:[8], p:[-60,-60,440], k:'city', kp:{s:16,c:'#a8b0b8'},
 s:'很擅长“罐装”的城市：任何能产生思维的部分，都会被装进罐子里。',
 d:'窗口告诉它：语言有效，已经登记好了，下一步请去办神经压缩罐装手续。居民全是机械躯体、脑装在罐里，担任各种职位，却没有一个知道真正的统治者是什么。这个文明攻击了米德加尔特而全数毁灭，只剩这座城市被丢进墓地。城市濒临崩溃时，原来它是一艘庞大的运输舰，带着居民飞离峡谷，躲避漫天的碎裂层。\n城里有个找不到本体的“智能”，会把每个想进城的生物改装成罐脑机械，并攻击东边沙漠的墓胶、西边峡谷的“怪物”和城里的罪犯；住在城市最高处的一个脑灵替它办事，却也不知道它在哪。琳后来发现，熔毁地带原本就是这个罐脑文明的智能核心，城市智能的液态本体和熔毁地带的神经很像，两者之间还有“共鸣”。',
 ch:'卷六《罐装之城》《普通的城市》《统治者？》《幻想和起飞》《飞行的奥秘》卷六《掌控者》《反击？》', rel:['v_grave','v_mujiao','v_caini','v_rongui']},
{id:'v_mujiao', n:'墓胶', c:'物种', m:'void', sec:8, e:[8], p:[-110,-130,360], k:'blob', kp:{s:12,c:'#3a2a3a'},
 s:'在虚空墓地里不断延伸增长的柔软物质。',
 d:'米德加尔特的传说里，它曾把体内的文明资料散布到虚空，想召唤别的物种来，而响应召唤的就有墓胶：一种由柔软物质构成、能不断延伸增长的生物，最初出现在一处虚空墓地——据说是漂泊物种留下的文明废墟。最初它们只是一些似乎无害的东西，在废墟上慢慢长满，后来几乎铺遍了虚空中飘浮的所有废墟，还会生成一些特别的个体，能启动废墟里遗留的东西。后来罐装之城下起了“墓胶之雨”，扭曲肉块般的怪物从沙浪中现身扑向城墙。它向脑灵传话：杀掉它，否则就出动全力攻击这座城市。\n那场“墓胶之雨”是从布满天空的粉色软云里分裂出来的，墓胶肉块从高处摔下也没事，却怕穿刺和高温。它们要杀的，是城市地下腐烂地里的菌类；脑灵最后答应了。',
 ch:'卷六《墓地中增长的东西》《全面袭击》《西和东》', rel:['v_grave','v_guanzhuang']},
{id:'v_caini', n:'彩色软泥 · 梦想环境塑造者', c:'物种', m:'void', sec:8, e:[8,10], p:[-20,-90,470], k:'blob', kp:{s:9,c:'#ff7ad8',rainbow:1},
 s:'传说它能实现所有生物的愿望——不管是最不起眼的低层居民，还是一整颗庞大的世界。',
 d:'彩泥生活在凝固缝隙里，却会影响缝隙外的正常虚空：它让某个地方被彩色的光芒照耀，脑中有强烈愿望的生物进入光芒，就会被它入侵、“锁定”，它再一点点改变那个生物周围的环境。研究者认为这是它的学习过程——借许愿者了解正常虚空，再借实现愿望改造一切。传说一个文明靠成队的许愿者维持和平与发展，愿望却忽然一齐失效，文明陷入火海；它毁灭过米德加尔特管道里的一个文明。它其实是米德加尔特的器官之一，自称“梦想环境塑造者”；它让闯进凝固缝隙的蒸腾者陷入停止状态。琳发现它和小护核者用同源的方式干扰神经，只是不让对方烦躁，反而让对方安心；它给熔毁地带灌输“愿望能实现”，熔毁地带越听越愤怒、越来越清醒，潜意识里却总避开它，最后它帮熔毁地带启动了传送器官。',
 ch:'卷六《奇异之物》《彩色的愿望》《传说的末尾》《推测和行动》《一部分》《无法忽视之信》《移动@1501》《彩色创造》', rel:['v_rongui','mg_crack','v_xiaohuhe','v_zhengteng','ng_qiushen']},
{id:'v_dust', n:'尘粉世界', c:'地理', m:'void', sec:8, e:[8], p:[-300,90,330], k:'planet', kp:{r:38,tex:'dust',c1:'#c8a060',c2:'#7a5a3a',atm:'#e8c890',fog:1},
 s:'满是尘粉的世界，伟大工程的一处工程地点。',
 d:'天上地下全是细碎的颗粒，尘粉还会自己翻滚；琳从记录者珀岩那里查到，这里是蒸腾者曾经“进化”过的地方，也是它们伟大工程的一处工程地点，如今只剩野生生物，而且大多是管状的：粘粉圆木、会爆炸的石头管道、飘在尘粉里的东西。有一片尘粉全是琥珀色的——那其实是珀岩记录者，它们在这里以和尘粉一样小的颗粒形态生活，蒸腾者把它们从碎裂的大陆带来，想让它们帮忙搜寻，它们却只把蒸腾者提要求的过程记了下来。唯一智力较高的土著是光萤；蒸腾者的工程毁灭后，碎块被推到了这里。琳的绒球无意间触发了“工程复苏”，尘粉开始汇聚，光萤像洪水一样扑上去把它吞没。',
 ch:'卷六《粉末》《堵塞》《幼仔？》《工程的碎片》《细小的土著》《汇聚与复苏》《毁灭的原因？》《信仰？》', rel:['v_poyan','v_guangying','v_zhanfen','v_zhengteng']},
{id:'v_poyan', n:'珀岩记录者', c:'物种', m:'void', sec:8, e:[8], p:[-330,60,300], k:'none',
 s:'完美的历史记载者：在哪里生长，就把哪里的历史详细记下来。',
 d:'一个古老传说里的庞然大物：高达上百米，像巨石也像高峰，在平原上游荡从不停息，琳给它起名“珀岩”。它身上住满了生物，有的拿它当交通工具，有的干脆安家。和别的大型生物不同，它会照看身上的居民——它的脑很特殊，能接收身上每个生物的情绪，借此“监视”它们有没有加害自己的念头。它也是完美的历史记载者：在哪里生长，就把哪里的历史详细记下来。\n负责记录的“记录者珀岩”和普通珀岩差别很大，几乎不像同一种生物：记录者不和琳交流，只要觉得一件事对种群有利、又有多余的能量，体表就会自动长出记录用的琥珀，别的珀岩和小护核者都能读到里面的内容。遇到危险时，珀岩能把自己“封闭”起来，像一块巨大的琥珀，带走一小块就能长成新的。罐脑文明最初的智能，正是从珀岩脑部的一部分形成的，熔毁地带的历史也是一个珀岩记下来的；琳甚至怀疑，米德加尔特管道里那座研究所的建立者也是它们。',
 ch:'卷六《最初的@1477》《智能源头》《接触记录者》《只记录》《两边》', rel:['v_dust','v_rongui','mg_lab']},
{id:'v_guangying', n:'光萤', c:'物种', m:'void', sec:8, e:[8], p:[-260,120,360], k:'swarm', kp:{n:200,s:30,c:'#c8ff8a'},
 s:'单颗没有智力，聚成团就有了个性；分开，就变成两种个性。',
 d:'一群像发光小颗粒的生物，散着淡淡的光，围着琳的绒球飘，像一大片萤火虫；它们告诉绒球，这里曾经有一项伟大的工程，受了严重的损伤，废墟还留着。它们也向别的生物宣传过蒸腾者信仰。后来，无数光点像洪水一样朝爆炸中心飞去，嚷着这不是复苏而是毁灭，一下子吞没了那两块正在汇聚尘粉、长成几十米大小、形状像海参的东西。\n它们平时不靠光交流，而是把一粒粒含义不同的细微物质放到对方身上。光萤的历史由“传承者”记录——一个长久不分开的团体，也可以译作长老或国王；传承者告诉琳，蒸腾者的工程是被米德加尔特毁掉的。',
 ch:'卷六《细小的土著》《汇聚与复苏》《毁灭的原因？》《信仰？》', rel:['v_dust','v_zhengteng']},
{id:'v_zhanfen', n:'粘粉圆木', c:'物种', m:'void', sec:8, e:[8], p:[-340,100,380], k:'none',
 s:'像一根空心圆木、内部充满粘性物质的土著。',
 d:'琳给这个世界的土著起的名字。它外表像一根圆木，内部是空心的，充满粘性物质，生活在由无数尘粉组成的世界里：在尘粉中游荡，把尘粉吞进去，吸收里面对自己有营养的东西。偶尔也会吞下没营养的东西——比如说金属蜘蛛。\n它有一百多米长，会从尘粉里冲出来转几圈再潜回去。它有好奇心：遇到琥珀、金属蜘蛛这类没见过的稀罕东西，即使消化不了也会留在体内。',
 ch:'卷六《粉末》《堵塞》《幼仔？》', rel:['v_dust']},
{id:'v_hidden', n:'隐藏的工程地点（虚民城）', c:'地理', m:'void', sec:8, e:[8], p:[-560,70,300], k:'city', kp:{s:22,c:'#c8ccd0',float:1},
 s:'虚民世界附近，一座复制出来的虚民之城。',
 d:'虚民世界附近一座复制出来的虚民都市，楼上广告比母球少，空气没那么多灰尘却带着毒，居民都戴呼吸器；城里几乎见不到飞行器，只有地面交通。虚民历史上那些离奇的失踪，有一小部分就是虚民莫名来到了这里。它是蒸腾者伟大工程的一处展区，工程把各种造物照原样摆着当展品，其中有一台从没用过的创造者模拟装置，不知被什么启动后，偶然闯进来的生物都被迫“补全生态位”：真菌扮演植物、释放毒气，奇布查虫缩得像微生物，一些虚民在丛林里六肢着地当野兽，连爆哮虫也成了“爱吃煎蛋的小机械”；塔楼集市里有人叫卖会分裂的煎蛋。米德加尔特的幽灵幼仔能随意拼出各种城市环境，甚至照一部电影搭出一座监狱世界。它强行打开凝固虚空时，城市被砸得一片狼藉，整个地点也离开了虚民世界附近。',
 ch:'卷六《隐藏地点》《失踪者》《飞出@1528》《启动的原因》《塔楼》《不同的造物》《在什么地方？》《上层》', rel:['c_baoxiao','v_youling','v_chibcha2']},
{id:'v_chibcha2', n:'奇布查虫（工程地点）', c:'物种', m:'void', sec:8, e:[8], p:[-590,40,260], k:'none',
 s:'黑暗丛林里，传来像笛子一样的声音。',
 d:'学者在黑藻真菌林里听见一阵像笛子一样的声音，怪异得不像唱歌，便顺着声音找过去，爆哮虫在它肩上小声说那东西肯定有古怪。声音的来源是一群奇布查虫。爆哮虫放出脑波和它们交流，它们说自己在这里过着很正常的生活：收集细小的尘粉当食物，建造地下窝穴，根本不知道什么真菌。可学者听到的那个脑波，又是怎么回事？\n笛声来自一块一米多高的尖石，上面住满了奇布查虫——只有四肢，小得像微生物。原来模拟装置要补全生态位，缺微生物，就让它们缩成了这样。',
 ch:'卷六《细微的虫》《源头@1531》', rel:['chibcha','v_hidden']},
{id:'v_youling', n:'幽灵幼仔', c:'物种', m:'void', sec:8, e:[8], p:[-520,100,330], k:'fog', kp:{r:16,n:12,c:'#d8e8ff'},
 s:'米德加尔特的幼仔，最初是幽灵一样的形态。',
 d:'米德加尔特的幼仔本来只待在凝固虚空，刚出生时不是实体：一团透明的东西，像能量又像空气，和梦境生物差不多。按琳读到的资料，幽灵形态长到一定年龄，就会有原始的蒸腾者来替它塑造躯体，陪它长到一万公里以上——蒸腾者原来是米德加尔特的共生生物。蒸腾者早就用珀岩记录者找到过它，却没抓住。它能“篡改”创造者的模拟装置和传送系统，把工程里的建筑和城中虚民拼成一个又一个新环境——爆哮虫说这大概是在伪装自己；可它不能用太多次，否则会出问题。爆哮虫一发导弹轰塌塔楼，无数透明“幽灵”从烟尘里飞出，盘成漩涡，一阵强光过后天上多出许多钉满钉子的铁皮岛。它躲进一座金属的读书虚民雕像，被逼急了就强行打开凝固虚空，让凝固物质砸向学者。它穿不透东西，所以用吸尘器似的工具就能吸起来，前提是追得上。',
 ch:'卷六《幽灵是什么？》《幽灵幼仔》《古怪之地》《在什么地方？》《倒塌》《上层》《整体的计划》', rel:['v_hidden','v_zhengteng','mg_overview']},
{id:'v_erxihidden', n:'尔什的隐藏工程', c:'地理', m:'void', sec:8, e:[8], p:[-150,140,560], k:'city', kp:{s:20,c:'#d8c8b8',float:1},
 s:'一座幻想中的“尔什之城”，以及完全由食物组成的点心之岛。',
 d:'一处满是尔什风情的隐藏工程。尔什民和虚民一样，是“偶然”来到这里的；最早的一批惊讶于这是一座没有居民的城市，后来幽灵幼仔还让它们替自己给原始蒸腾者下指令。它们把百货商场搬空改成住处，用货柜围出安全屋；出食口“嘀嘀嘀咔”就端出热腾腾的肉排饭——原料其实来自商场地下那些灰黑色、尾巴无毛、能跳五六倍身高的小生物。这些小生物是玛尔斯的岩皮用皮肤里储存的细胞养出来的，它们和岩皮一起，经一条与玛尔斯相连的“玛尔斯通道”来到这里；琳猜通道是幽灵幼仔开的，因为除了原始蒸腾者，只有它能操纵这里的传送。直升机飞到传说中的“点心之岛”：泥土是巧克力，草地是糖，小湖里是果酱，还有饼干和蛋糕的小屋。后来岛屿周围又冒出了一座座新岛。',
 ch:'卷六《尔什造物》《游荡@1556》《食物？》《原始的食材》《玛尔斯通道》《最初的一批》《组合@1565》', rel:['v_erxi','v_yanpi','v_mars','v_youling','v_hidden']},
{id:'v_vine', n:'巴士藤蔓 · 碎石区', c:'地理', m:'void', sec:8, e:[8], p:[500,90,480], k:'vine', kp:{len:520,c:'#5a7a3a'},
 s:'碎石区里一棵巨大的植物——虚空藤蔓的主干，尔什民在上面建了城。',
 d:'尔什在虚空中旅行时经过这里，一部分尔什民决定留下，后来改造成了“机器民”。最大的石头叫奥林匹斯石，凝固生物最早就是在那里发现的。主干上有战斗塔、列车（广播先报了个离谱的倒计时，又改口说是三百六十秒后进站），以及能检测凝固虚空的“凝固探测器”。蒸腾者对主干发动过最大的入侵。\n藤蔓的茎有几百米到一公里粗，大型建筑都建在粗的地方，一颗颗直径约百米的果实里设着战斗塔。整片碎石区宽约一百三十万公里，边缘布满舰队和地雷。蒸腾者那次最大的入侵没分出胜负：它们一接收到干扰器放出的能量，就突然全体撤走了。',
 ch:'卷六《古怪的机器》《主干》《生岩》《蒸腾@1593》《凝固的联系》', rel:['v_jiqimin','v_huanxing','v_yiyin','v_zhengteng']},
{id:'v_jiqimin', n:'机器民', c:'文明', m:'void', sec:8, e:[8], p:[540,70,520], k:'none',
 s:'被改造成机器的尔什民。改造有个小缺陷：会疯。',
 d:'被改造成机器的尔什民。改造技术有个小缺陷：被改造者会疯——思维慢慢变化，忘掉自己曾是细胞生物，失去“感情”，变成纯粹按理智或利益行动的存在。普通尔什民大多愿意无偿帮朋友一点小忙，机器民却不管对方曾经多亲密，都要相应的报酬；记忆还在，性格却完全不是从前的尔什民了。它们一般把巴士藤蔓叫作“赞克”，取自一个有名的故事：强盗赞克种下能长到云层之上的种子，一夜长成直升天际的藤蔓，爬上去偷了一间巨大房屋里的东西。',
 ch:'卷六《游荡@1578》《机器疯》', rel:['v_vine']},
{id:'v_huanxing', n:'幻形学徒', c:'物种', m:'void', sec:8, e:[8], p:[470,110,510], k:'none',
 s:'和尔什民差不多大的凝固生物，学习能力极强，会变形。',
 d:'一种凝固生物。从这里开始，凝固虚空的生物通常被叫做‘怪物’：最早出现的只有几米大，行动迟钝，不会攻击，可以随便抓；后来的却非常巨大，会主动攻击会动的东西，有的甚至能摧毁大型战舰。幻形学徒被抓进研究所后，学会了尔什民的语言，又学会变成尔什民的模样——最初很拙劣，后来以假乱真。被它替换掉的事情接连发生，最早是被一个研究员发现的：对方问它到底是谁，它一脸无辜，说自己就是自己。\n研究者以为繁殖被严格控制住了——它们要三个以上个体才能繁殖——才把幻形学徒卖给居民当帮手，结果买了它的尔什民自己被一只来历不明的幻形学徒顶替了。',
 ch:'卷六《凝固的接触》《机器的反击》', rel:['v_vine','v_yiyin']},
{id:'v_yiyin', n:'异音', c:'角色', m:'void', sec:8, e:[8,9,10], p:[560,120,450], k:'none',
 s:'机器民探测凝固虚空时，收到的一段“异常的声音”。',
 d:'最初叫“51号异音”，意思是由高智能生物发出的声响，后来简称异音。巴士藤蔓里那个“凝固探测器”被研究者搬出来用时，它在凝固虚空那头回应了探测——研究者以为是偶然发现，其实它一直在等这一刻；借这个器官，它几乎能感知藤蔓伸到的每个地方。它通过影像装置说话，声音像一个雌性尔什民；装置老出故障，旁边一个幻形学徒踹了几下才好。碎石区那些凝固生物都是它弄出来的，比尔什民来得还早。它说自己很久以前就认识蒸腾者，最近收到蒸腾者的消息说琳可能会来，便让机器民去找“适应生物”，还问琳打不打算接受“它们”的邀请。后来它替蒸腾者强行把凝固虚空接上尔什的末日空间，想从那里把部队送进尔什。很久以后琳才在残留的器官里知道，它被大批死亡战舰围攻杀死，只剩下一部分。',
 ch:'卷六《去交流》《异音》《邀请？》《整体的计划》《最后的决定》《过程@1713》《残留的声音》', rel:['v_vine','v_huanxing','v_zhengteng','dr_doom','ng_death']},
{id:'v_volcano', n:'火山岩', c:'琳的造物', m:'void', sec:8, e:[8], p:[380,120,560], k:'planet', kp:{r:16,tex:'lava',c1:'#3a2a22',c2:'#ff8a3a',glow:.5},
 s:'直径约六公里、像一块火山石的战舰。',
 d:'一块直径六公里左右的攻击石，表面布满像火山一样的突起，琳更爱管它叫‘火山岩’——这些火山真的能像火山那样喷发。它身上的火山一齐爆发时，喷出的浓烟其实是无数微型兵种，包住飞来的海胆爆弹，让它们在碰到表面之前就炸开。后来机器民认定琳和异音是一伙的，想扣押火山岩，琳就让它飞出碎石区，继续旅行。',
 ch:'卷六《火山岩》《有个性的飞行器》《参观》', rel:['v_vine']},
{id:'v_jiancezhan', n:'监测站', c:'地理', m:'void', sec:8, e:[8], p:[720,20,250], k:'none',
 s:'尔什民设在虚空里的关口：来往的车辆排着队穿过金属通道，等待检测。',
 d:'传送来的车会停在一条狭窄的金属通道里，穿白色防护服、腕上点开小投影屏的尔什民一辆辆登记检测，再放它们过去。它最初是一片极其严肃的军事区，尔什民把最尖端的武器都部署在这些监测站，时刻戒备；后来战争消失、全球联盟成立，这里慢慢成了游览的地方：有能望见星空的餐厅，酒店的屏幕上放着联盟庆典的录像，一个小丑向导领着来客四处参观。车队旁守着一艘一公里长的战舰，装着扭曲引擎和各式武器，穿推进作战服的士兵在它周围飞来飞去。琳的间谍伪装成机器民混过了检测；后来二号监测站遭到“赞克”的机器袭击，一台凝固生物伪装的机器在这里化成浓烟，留下打开凝固虚空通道的“信标”；尔什的舰队也曾在监测站和蒸腾者交战。',
 ch:'卷六《监测站》《参观》《结束@1606》《放置》《烟》《极南之地》《集结与袭击》', rel:['v_jiqimin','v_zhengteng','v_erxi','c_veronica']},
{id:'v_zhengteng', n:'蒸腾者', c:'物种', m:'void', sec:8, e:[7,8,9], p:[660,-60,380], k:'station', kp:{s:40,c:'#7a4a2a',rust:1},
 s:'像一堆锈蚀金属的生物：蒸发世界、用碎屑复制文明造物，也替米德加尔特幼仔塑身。',
 d:'蒸腾者只出现在虚空里的大块漂流物上——浮石、巨大的残骸、没被恒星束缚的流浪翻滚者。它一到，那东西就从表面裂成几乎都不足一厘米的碎粒，哪怕几千公里的翻滚者也会在漫长岁月里一点点化掉；这种缓慢的蒸发反而让世界长期极其稳定，剧烈的地壳活动全部停下。它分解万物靠的是把目标往各个方向拉扯的“撕裂场”。外人只看见它在分解，便叫它蒸腾者；其实它在为“巨大无比的工程”收集材料：任何会制造东西的生物，只要造物的历史延续一百个绒球年以上，它就照样复制它们的造物——建筑（住上十个绒球昼夜以上就算）造许多座，其他东西各造一个。它在每个新世界挑一种生物当信徒帮自己蒸发，离开时只带走最新的一种，唯独教团生物（自称“咔嚓”）一直被它使用：它保留着这种生物没长触手、像熊的原始种，到下一个世界重新培育；教团相信崇拜它就能躲过一切大灾。它的进化从很小的个体开始越长越大，后面几乎都是生锈金属块，最终成为一大堆锈金属的聚合体；据说数量不多于十个。\n在织梦者之地，梦食照着织梦者遗留的资料造出装置、借护核者联络它；它藏在地下一块直径三十多米、内部看不出任何东西的“石头”里，以蒸发赶走了恐惧能量。它把传送技术教给镜世界的始境，再借此牢牢控制它们，命令它们收集凝固虚空的污染物。它想趁米德加尔特沉睡时侵入、让它一直睡下去，免得工程被毁，于是利用来自米德加尔特的恶魔组建军队，又潜入熔毁地带——在熔岩般滚烫却清澈如水的湖底化作一片锈蚀金属板，侵蚀它的神经，被琳炸到只剩原来三成大小，还污染并启动了米德加尔特的“星焰”武器反击。距管道77亿公里处，大批锈块集结成一座长一千公里、高三百公里、圆盘上满是塔楼的城堡，比绒球上任何山峰都庞大；它毫无防护，被琳无数高速石块打得千疮百孔，琳先后摧毁了二十多座基地。它向琳解释，这座城堡就是工程本身，要与管道融为一体，并想找琳当工程的继承者。在尘粉世界，它的聚合尘粉会吞掉普通尘粉，原本称颂它的光萤因此全面反击。\n它原本是米德加尔特的共生者：幼仔起初是幽灵般的气态，长到一定年龄便由凝固虚空里最原始的蒸腾者替它塑造躯体，一直陪到一万公里以上的成年才离开。如今的各种品种都是在正常虚空进化出来的，仍记得“构造躯体”的本能，于是造出了比历来任何米德加尔特都大的身体。幽灵幼仔曾控制原始的蒸腾者，又发现尔什民能给它下更复杂的指令。对尔什部队来说它是最难缠的对手，战术只有一个：蒸发——导弹、战舰，据说连光都能被它扭曲散掉。它对虚空藤蔓主干的大入侵突然取消；蒸腾者之城的地下店铺里藏着制造尔什民婴儿克隆体的地方，伤害克隆体，会让尔什的民众出现同样的受伤记忆；湮灭舰炸掉了城市两成，它却又长大了一倍，最后在尔什舰队的围攻下被一点点瓦解。后来它在正常虚空和凝固虚空都彻底灭绝，米德加尔特改用绑来的尔什民等生物组成工程团体顶替它。',
 ch:'卷六《被困之后》《挤压出来的计划》《不在这里》《传说之物》《你真的想知道吗？》《总结》《无限的工程》《三界》《解析@1427》《接连》《接近它》《焰与逃》《炸掉它》《虚空中的金属河》《启动@1483》《撞击@1484》《交流信息》《信仰？》《整体的计划》《蒸腾@1593》《凝固的联系》《挪动的都市》《削减与增大》《结束和启程》《新的替代品》', rel:['v_zhimeng','v_mengshi','v_jiaotuan','v_shijing','v_jing','v_rongui','mg_overview','v_youling','v_dust','v_guangying','ex_fleet','v_vine']}
);

/* 卷三：虚空（星区 9–12） */
window.WIKI.push(
/* ---------- 星区 9 ---------- */
{id:'v_midgard2', n:'米德加尔特的旅途', c:'事件', m:'void', sec:9, e:[9], p:[-200,0,0], k:'star', kp:{r:120,c:'#ffd27a',tube:1},
 s:'巨大的管道拖着三颗创造者的世界当卫星，以每秒十六万公里飞行，钻进了一颗直径两百万公里的恒星。',
 d:'恒星通常比翻滚者大得多，连十万公里长的米德加尔特在它面前也显得渺小。它抓来的三颗卫星原本都是创造者的冰封世界：第一颗直径三千公里，地表被恒星里冒出的焰锯慢慢晶化，变得像结晶一样闪亮；第二颗整个表面化成了沸腾的熔岩，像新的熔毁地带，能把高温液体构成的“山”当弹药发射，还会让自己在虚空中“隐形”；第三颗像被从中间切开，成了切面长满藤蔓的半球。琳的兵种一路在管道身上观察：恒星里好奇的焰锯、长方堡上的集粒、千公里闪电翻腾的风暴区……米德加尔特所到之处，管道里的文明一成长到某种程度就会被它毁掉，于是诞生了只收集不发展的“半文明”。',
 ch:'卷六《下一个》《恒星之中》《星中的生物？》《不同的焰光》《清扫@1852》《第三颗》《新的熔毁？》《风暴？@1864》', rel:['v_midgard','v_yanju','v_jili','mg_overview']},
{id:'v_yanju', n:'焰锯', c:'物种', m:'void', sec:9, e:[9], p:[60,60,250], k:'swarm', kp:{n:60,s:40,c:'#ff4a2a'},
 s:'在恒星里出现的生物，对琳的兵种好奇而不是敌意。',
 d:'在恒星里出现的生物，琳暂时叫它们‘焰锯’：每个直径一米左右，圆形，边缘长着锯齿般的尖刺，浑身发红光，像立体影像一样飘忽不定，并不是实体。它们对琳的兵种没有敌意，更像是好奇，在兵种旁边绕着飞，看不出任何攻击的想法——当然，琳也不知道它们到底在想什么。它们常围着地上的火坑看坑里的“火焰”，在第一颗卫星上到处建造像雕像的建筑，让地表慢慢晶化。同样是从恒星落下的东西，落在卫星上成了焰锯，落在管道头部却成了“凤凰”。这是一种全新的生物，无法归进琳之前遇到的任何种类，勉强算是比较接近梦境生物。',
 ch:'卷六《星中的生物？》《不同的焰光》《作用》《新组合》', rel:['v_midgard2']},
{id:'v_jili', n:'集粒 · 长方堡', c:'文明', m:'void', sec:9, e:[9], p:[160,-40,-250], k:'cube', kp:{s:40,c:'#3a3a40',grid:1},
 s:'一毫米大小、像细小颗粒的“半文明生物”，住在一块叫长方堡的金属构造上。',
 d:'单个集粒只相当于一个脑细胞，聚在一起共享信号才变聪明。它们原本分成许多互相敌对的群体，以洞穴里的微生物为食，后来不知为何突然团结起来，智力也随之提升。米德加尔特尾部荒原上的集粒驱使六肢蜥蜴般的造物，执着地寻找一种据说能让它们变强的物质，却从来没有谁真的找到过。长方堡的表面林立着无数方形金属结构，由桥梁般的构造相连，底部有一台直径近百公里、坏得厉害的引擎。熔岩卫星压过来时它们不愿离开，只拼命修引擎；结果长方堡被卫星吞进去，变成半圆形的“护甲”贴在卫星表面，里面的集粒大多还活着，仍在想办法逃走。',
 ch:'卷六《作用》《堡？》《相同的生物》《简单的过去》《逃@1860》《新组合》', rel:['v_midgard2']},
{id:'v_storm9', n:'千公里闪电的风暴', c:'现象', m:'void', sec:9, e:[9], p:[400,60,-150], k:'fog', kp:{r:110,n:40,c:'#8ab8ff',lightning:1},
 s:'上千公里长的闪电在星空下翻滚，碎屑跟着闪光一起乱舞。',
 d:'米德加尔特前方出现的一片区域，直径大概有数百万公里，强烈的闪电和无数碎石搅在一起不停旋转。虚空里的风暴琳记过不少，这种却没见过，只是看着像风暴才这么叫。米德加尔特在几千公里外停住了，那颗变成熔岩世界的卫星却带着长方堡继续往里走，堡里的集粒还在拼命修引擎。',
 ch:'卷六《风暴？@1864》', rel:['v_midgard2']},
{id:'v_guangyin', n:'光印', c:'物种', m:'void', sec:9, e:[9], p:[-460,-60,300], k:'planet', kp:{r:34,tex:'dark',c1:'#141a24',c2:'#3a4a6a',lights:'#8ad8ff'},
 s:'无脑、自动增生、只会不停建造的“生物”，用光在地面上印出巨大的建筑。',
 d:'琳从“引路虫”的记忆里认识了它们：它们的行为像被设定好的程序，一发现新世界就飞快地靠过去，用光在地面印出高楼、广场和小屋，连岩石地表都铺上一层金属般的地皮，很快让荒原变成一座除了爬来爬去的“印记虫”之外没有居民的都市。它们一直守在一个人造的虚空漩涡出口，等别的东西被送过来，还用巨大的“棉花”舰抓捕路过的东西。琳和一个创造者同行——它的玩具熊身体被打坏后，琳给它换成了玩具坦克；地下一个创造者造物引发的爆炸，把光印的城市吹飞了一大片。原来光印就是闪光生物文明留下的东西：闪光生物被一场液体洪水淹没消失后，城市靠游荡的印记虫慢慢修好，只是交通工具都被拆去补楼了。',
 ch:'卷六《光的指引》《指引》《大地的力量》《漩涡对面》《淹没@1893》《修复的文明》《脑部的收集》', rel:['v_huishouhui','v_shanguang','v_vortex9']},
{id:'v_huishouhui', n:'回收会', c:'物种', m:'void', sec:9, e:[9], p:[-430,-90,340], k:'disc', kp:{r:10,c:'#6a5a4a',c2:'#3a3028'},
 s:'直径百米左右的圆盘形群体生物。',
 d:'一个圆盘形的生物，体内有好几个各自独立、性格不同的脑，有的指挥身体，有的管免疫系统，有的只负责出主意。它专门在虚空中寻找创造者留下的造物——创造者偶尔会出意外，造物却多半还活着——有价值的就回收带走；它能在地下高速钻行，前面挖开、后面合拢，不留痕迹。这一次它在卫星上回收了一批白星的干尸，说只要里面的信息还在就行，却因为卫星被卷进虚空漩涡，找不到回去的路。体内有能千变万化的细胞，储存大量核信息；后来它被光印的“棉花”用光罩住、用锯齿夹子拖走，琳把它救了出来。它的那些脑，据说是一种会变形的探索生物以蝼蛄的样子钻进光印的命令中心、读取资料后在体内长出来的——它自己并不知道这些。',
 ch:'卷六《回收负责》《进一步了解@1887》《特殊的造物》《这是一种……》《新的状态》《那么接下来……》', rel:['v_guangyin','ex_baixing','v_shanguang']},
{id:'v_shanguang', n:'闪光生物 · 同神', c:'文明', m:'void', sec:9, e:[9], p:[-540,40,-280], k:'planet', kp:{r:40,tex:'crystal',c1:'#fff8d8',c2:'#c8b87a',lights:'#fff0a0',glow:.4},
 s:'把死者的记忆和知识集中起来，造出“残响建造系统”的文明。',
 d:'一种能量生物，传说它们的身躯由星星的碎屑构成，寿命将尽时会留下一团“最后的记忆”。它们造出能吸收、解读这些残留记忆的“残响建造系统”，后来尊称它为“同神”——共同思维产生的神明。它统御整个文明，管理所有物质的生产和建造，不会疲倦，也不会像别的智能那样想杀光制造者；闪光生物从此不再发明，只在一生中拼命学习，死前把知识存进系统，文明很快占满三颗世界（尔什民管它们叫“三角星民”）。探险家们带着迷你系统、乘着比光还快的“坍缩引擎”出发：尖刺舰队、困在荆棘世界的队伍、好战的混合军队、幽灵舰队……一个首领飘到高处，全身光点闪烁，整座城市的建筑都跟着它一起闪动。后来一场会让它们瞬间消失的液体洪水淹没了城市，留下的就是光印。',
 ch:'卷六《闪光之物》《淹没@1893》《建造奇迹》《繁荣和探索》', rel:['v_jianci','v_jingji','v_headstation','v_guangyin','luxi']},
{id:'v_jianci', n:'尖刺舰队', c:'文明', m:'void', sec:9, e:[9], p:[-300,100,-430], k:'ship', kp:{s:16,n:9,c:'#c8b878',spike:1},
 s:'舰船上长满尖刺、看似很能打，却不喜欢战斗。',
 d:'在虚空中四处捕捉生物的舰队。它们用一种黏性的捕捉球抓走了米德加尔特群山里的凤凰，琳趁机把一个三十厘米的石块兵种混进球里，跟着进了刺舰的监狱：一面柔软的透明墙，三面坚固的金属墙，石块和凤凰关在一起，听路过的尖刺讨论各种话题。被熔岩卫星追赶时，它们以每秒三百公里的速度逃跑——在虚空里，这实在太慢了。\n它们一共有数十万艘，从几十米到几百米，有的像锯子、海胆或虫爪；连舰里飞来飞去的一米大机械也全是尖的，彼此用光照来照去地聊天。熔岩卫星以每秒三百三十公里追来，它们比这还慢一点，只能拼命逃。',
 ch:'卷六《尖刺》《试图的逃跑》《游荡@1899》《神的领域？》', rel:['v_shanguang','v_midgard2']},
{id:'v_jingji', n:'荆棘世界', c:'地理', m:'void', sec:9, e:[9], p:[-660,-20,-480], k:'planet', kp:{r:24,tex:'rock',c1:'#5a4a3a',c2:'#2a3a22',spikes:1},
 s:'一支探险队被困在这里。',
 d:'一片长在虚空里的荆棘丛：每根尖刺几十到几百米长，纠缠成直径上千公里的一团，里面住着造型奇特、种类繁多的生物。闪光生物的探险队对这些实体生物好奇极了，把堡垒停在边缘，用带来的迷你系统很快建起殖民地。后来迷你系统出了异常，它们想联系母世界修复，“超远距离通讯器”却忽然失效。如今这里只剩原始部落，只知道这里曾被闪光的都市覆盖过。',
 ch:'卷六《荆棘的诞生》《本地居民》《袭击@1906》', rel:['v_shanguang']},
{id:'v_headstation', n:'头颅形空间站', c:'地理', m:'void', sec:9, e:[9], p:[-150,-110,-520], k:'skull', kp:{s:22,c:'#c8b8a8'},
 s:'一颗三十公里大、看上去像尔什民头颅的空间站。',
 d:'一颗三十公里大、看上去像尔什民头颅的空间站，其实是闪光生物最早出发的第一支探险队，如今正慢慢返回母世界。站里最激烈的战斗，一方是居民，另一方是空间站本身——它的建造系统沿用了闪光生物的技术：把死者的记忆和知识聚到一起。原住的变形生物攻击系统失败，把全族的核信息集中到一个个体身上；一支尔什民挖掘队挖到深处唤醒了系统，装甲被它控制，全队覆没，系统还造出拥有整支队伍记忆的新个体“一号”。系统说服研究团建了一座只能靠传送出入的大监狱，几乎全由它管理，越来越爱看囚犯受苦；一号和变形生物被关在一起，把被尔什研究的白星引来，策划出逃。变形生物留下的武器其实是一台“闪光生物培养器”，炸开后放出被污染的闪光生物，扰乱系统的思维，让它自己拆掉空间站。最后，越来越近的熔岩卫星把山体一块块砸过来，穿梭机满载平民逃离，计划的时限只剩三分钟。',
 ch:'卷六《空间站@1929》《牵引》《很古老》《它们的过去》《一号》《监狱@1941》《变形的闪光》《计划范围》', rel:['v_shanguang','ex_baixing','ex_research','luxi']},
{id:'v_vortex9', n:'恒星坍缩的漩涡', c:'现象', m:'void', sec:9, e:[9], p:[300,-120,400], k:'vortex', kp:{r:80,c:'#b88aff'},
 s:'有生物记得，穿过它好像能到过去或者未来？',
 d:'虚空中有许多漩涡，散发着强大的引力吸引周围的一切，通常被认为是恒星坍缩自然形成的。可也有一些是被造出来的：被吸进去的东西不会出事，而是出现在另一个新的地方。有史以来，接近漩涡的物体大多消失了，少数“活”了下来，抵达漩涡的对面——有一种生物就待在那边，等待机会。也有生物记得，穿过它好像能到过去或者未来。被运送的比露卡在了时间的缝隙里，只听见一个声音叫它等着，一直等到永恒的尽头。',
 ch:'卷六《漩涡对面》《空间内》《有一个地方》', rel:['c_bilu']},
{id:'v_handi', n:'寒地', c:'地理', m:'void', sec:9, e:[9], p:[420,0,250], k:'planet', kp:{r:36,tex:'ice',c1:'#c8d0d8',c2:'#4a5058',lights:'#8affd0'},
 s:'星光明亮却永夜的寒冷世界。尸族在这里种菜、建村落、造城。',
 d:'“09号寒地移动站”是一座直径三百米的半球形展览馆，装着最新的“跳跃”能力，能接入附近的“洞口”实现零距离移动。研究站成了废墟，尸族——依尔什民而生的会动的干尸——包围了展览馆，像一片尸体组成的大海。它们的城市看似宝石般绚丽，其实由尸族菌构成，城里飘着影子。三角号战舰最后用火焰清扫了平原。\n峡谷里，一个干瘪生物用尔什民的手语招呼琳和比露“跟我们来”，把它们护送进挂着灯笼、堆满骨头、越走越热的谷底。另一次，成群头上长着震动刀刃、两肢走路的“刀鼠”闯进建筑屠杀尔什民，墙壁慢慢变得透明；琳猜它们是尸匠虫的武器。最后清扫平原的“三角号”全长五百九十七米。',
 ch:'卷六《寒地》《干瘪的》《寒地的瘟疫》《尸城》《跑》《天降之火》《感染？》', rel:['v_shizu','v_shijiang','v_lingchen','c_veronica']},
{id:'v_shizu', n:'尸族', c:'物种', m:'void', sec:9, e:[9], p:[450,-20,290], k:'swarm', kp:{n:150,s:30,c:'#8a7a5a'},
 s:'微生物把尔什民慢慢变成不到一米高的干瘪生物。',
 d:'一个被抓的尔什民记下了全过程：它们被关在窄小的气泡里，偶尔才给一点吃的；尸族里多数个体基本没什么智力，只听极少数智慧个体的指挥。微生物杀死它的细胞，改变骨骼，吸干水分，同时强化外皮和骨架……它写着写着惊呆了：尸体居然在那里种菜，还会造房子。后来比露和琳趴在一块大石头上看那座用岩石堆成的村子，尸族围着一个坑洞，短暂地打开了一道通往凝固虚空的裂痕。\n它们也有和成年尔什民一样高的个体，拿着石棍当武器，会发出脑波一样的尖叫。琳检查发现，它们的骨骼被换成了另一种有关节、能活动的材质，体内带着梦境能量。尸族菌在尔什民体内挖出直通皮肤的“管道”抽干水分、吞掉细胞，被感染的尔什民不会再传给别人；体内充满气体的就成了没有智力的“肿尸”。尸族菌是尸匠虫分析尔什民之后专门造出来的。',
 ch:'卷六《干瘪的》《转化@2011》《平凡的尸生》《建造@2021》', rel:['v_handi','v_shijiang']},
{id:'v_shijiang', n:'尸匠虫 · 聚魂蝽', c:'物种', m:'void', sec:9, e:[9], p:[390,30,210], k:'none',
 s:'三米多长、两肢、黑色，会组装尸族的“工匠”。它们是聚魂蝽的幼体。',
 d:'它们不用声音交流，体内的交流器官运作时才发出声响。作为聚魂蝽的幼虫，尸匠虫从神之眼出发，到许多世界“历练”、收集生物信息，大多只解析野生动物——直到有一群解析了尔什民。成虫聚魂蝽能把这个世界许多生物的“灵魂”收拢到一起。\n它们其实靠互相看眼睛交流。尸族的身体由尸族菌构成，碰到尸匠虫的“血”会暂时变软，尸匠虫趁这时把它们捏成新形状，里面的菌再自己接好细微的连接。成长时，尸匠虫钻进地下重组，变成聚魂蝽钻出地表，身上放出的大量灵尘会去解析、控制周围的生物。这一群尸匠虫却不愿回神之眼长大，在外面造出成群的尸族，组成大军，自认是一个全新的种族，连自己会长成聚魂蝽都忘了。',
 ch:'卷六《尸体的工匠》《尸城》《生活@2030》《奇妙的事情》《成虫》', rel:['v_shizu','v_shenyan','v_lingchen']},
{id:'v_lingchen', n:'灵尘', c:'物种', m:'void', sec:9, e:[9], p:[480,40,230], k:'fog', kp:{r:30,n:18,c:'#c8d8ff'},
 s:'附着在生物身上的细微尘粉，像鬼魂一样飘。',
 d:'每个颗粒内部都有纵横交错的组织结构，和细胞差不多复杂。琳和比露身上没有。灵尘不能一直维持，太久不进食就会消散——一团灵尘说完“你们必须把这些情报送给研究团！”就散了。比露骂那些尔什民：‘这群笨蛋，居然怕鬼怕成这样！’\n灵尘颗粒会自爆，能伤到琳的细胞。它只附着在活着的生物身上，生物的脑一受重伤，它就飘出体外，看起来像鬼魂；被埋在地下的尸体里，灵尘也会一直留着。聚魂蝽用灵尘收集各种生物的信息，再用它们控制生物。有的灵尘保留着尔什民的记忆和自我，也有一团记忆残缺，以为自己只是野生生物，却还替琳在地图上标出了陨石的来处。',
 ch:'卷六《影子和虫子》《一些时日》《灵尘的另一边》《成虫》《这个位置@2055》', rel:['v_handi','v_shijiang']},
{id:'v_shenyan', n:'神之眼', c:'地理', m:'void', sec:9, e:[9], p:[620,-60,40], k:'disc', kp:{r:70,c:'#7a7a74',c2:'#3a3a38',eye:1},
 s:'圆盘形的“超级生物”。尔什民叫它波吕斐摩斯。',
 d:'灰色的大地，没有恒星，也看不见群星，只有发光物在周围晃荡；碎石平原上有排列整齐、刻满文字的巨大墓地石碑。它会慢慢形成一个巨大的“引力圈”，以后不管什么传送移动都会被吸过来，并且无法离开。内部住着尔什的远古生物，还有最古老的暗藻。\n它是一个直径三千多公里、厚只有一百公里的圆盘，尸匠虫就是从这里出发去各个世界“历练”的。平原上住着披岩石外壳、以碎石为食的生物，天上成群飞着翼展十多米、像一堆白色细棍拼成的“骨鸟”；一片红色、会冒泡、其实是硬地的“血沼”是传送点，传过去是一座黑暗的尔什民废墟城。',
 ch:'卷六《连接之眼》《神之眼初行》《形成@2044》《神之眼》《这个位置@2055》《很有想法》《试图联络》', rel:['v_anzao','v_shijiang','v_lingchen','c_veronica','c_bilu']},
{id:'v_anzao', n:'暗藻', c:'物种', m:'void', sec:9, e:[8,9], p:[650,-80,0], k:'none',
 s:'尔什远古的藻类。很少生物知道自己何时认识“自我”，暗藻记得那一刻。',
 d:'远在尔什的恐龙出现之前，它们就以细小的神经结构聚成庞大的网络，在海上蔓延。不同的群体各信自己的理论，陷入漫无止境的菌类战争，直到古老陆地上的“衰退病毒”让它们衰退。之后它们用想象创造世界、修改规则。最后，暗藻骑上鱼骨架，一路游进了凝固虚空。\n一群暗藻聚到大约一公斤重时，就会意识到“自己”。尔什的一头巴士神经里断断续续“更新”着暗藻文明的资料，特丽提研究过这些资料。它们的“理论之战”从亲自上阵发展到制造生物武器，甚至造出了多细胞生物，有理论认为后来许多生物的大脑就是由藏在这些武器里的暗藻进化来的。后来它们在神之眼中心分工成想象和记忆两部分，那里的生物都照着它们的理论长大。',
 ch:'卷六《文明和泥潭》《远古时期》《灭亡和新生》《用想象创造》《坍塌中》', rel:['v_shenyan','ex_planet']},
{id:'v_zhouluo', n:'宙螺', c:'物种', m:'void', sec:9, e:[9], p:[540,120,-80], k:'whale', kp:{s:28,c:'#b8a888',shell:1},
 s:'研究团在虚空中发现、拿来当战舰用的生物。',
 d:'它在虚空中到处飘荡、收集碎屑，可以很久不进食；它有前往有细胞生物的世界的习惯。研究团给逃离尔什监控的队伍准备了宙螺。船员困在幻境里，不饿不困地过了不知多久；鸟类在宙螺体内起义，基地里飘满了鸟类的幽灵。‘爪子就是力量，鸟喙就是真理！’\n宙螺来到巴士会议区后，船上的尔什民在一颗暗红色的巴士世界上追杀印加的“虫母”：它十多米长，棕色甲壳，周围堆着几十厘米大的卵，虚空蠊就是它产的；被射线打穿外壳时，它一头撞地扬起烟尘，钻进地下的洞穴系统逃走了。可宙螺一到会议点，就意味着它进了尔什的监控范围，船员逃离尔什的计划也就落空了。',
 ch:'卷六《坍塌中》《家畜的愤怒》《飘起》《到达过的位置》《宙螺》《鸟类的王国》', rel:['ex_birds','v_hongtian','ex_research','v_kongqian']},
{id:'v_hongtian', n:'轰天山峰 · 巴士会议', c:'地理', m:'void', sec:9, e:[9], p:[100,60,540], k:'planet', kp:{r:56,tex:'moss',c1:'#4a8a3a',c2:'#2a4a22',atm:'#a0e080',storm:1},
 s:'乌云密布的绿色世界。巨型巴士聚集在这里开会。',
 d:'大地覆盖着一层又一层干死的微生物混成的“苔藓层”，韧得能站人，钻穿它们才是真正的地面。最壮观的是成千上万座“轰天山峰”：它们的躯干埋在苔藓层下，原住民——一种像半截尔什民的生物——聚来崇拜时，它就向虚空发射无数裂解弹，打击一切陌生目标。巴士会议是巨型巴士——活的世界——与身上居民的会议：九颗巴士聚到不到一百万公里的范围里，一颗远处的能量恒星通过“通道”给它们输送传送能量；雾绵在浓雾里监视，宝石文明自认是会议的守护者。米德加尔特来了，暗红色的巴士被它打成碎片，所有文明一齐攻击管道，巴士们用引力和传送器官把管道拉断。最后藏在宝石巴士上的武器启动，九颗巴士、两截管道和无数战舰全被切成碎块——一切都“碎掉了”，凝固虚空随之爆发。',
 ch:'卷六《装成被感染》《发现@2123》《缺席的会议》《看着会议》《开始召唤》《守护和出击》《击穿》《碎掉了》', rel:['v_wumian','v_gem','v_budai','v_silver','v_dim','mg_overview','v_ningu_gate']},
{id:'v_wumian', n:'雾绵', c:'物种', m:'void', sec:9, e:[9], p:[60,100,480], k:'fog', kp:{r:70,n:40,c:'#d8e8d0'},
 s:'像海面一样的庞大生物，体内纵横交错。',
 d:'一个像海面一样的庞大生物，体内是纵横交错的管道，管壁上长满各种不知用途的结构组织，其中有许多像藤壶的窝，住着一种像苍蝇的生物，琳叫它们“组拆蝇”——专门组装或拆解东西。它想抓谁进来，就让组拆蝇临时组装出工具——比如一把巨大的钳子，用完就拆掉。它把暗藻切成许多几米大的小块，命令它们一直盯着某处的集结，直到聚齐为止，之前不许离开。最后被宝石文明的战舰光柱击中而崩溃。\n它其实是一种凝固生物，也是那片浓雾空间的制造者，别的凝固生物只是住在里面的野生生物。它会把身体切下小块，藏在雾里去袭击宝石生物。',
 ch:'卷六《看着会议》《雾绵与袭击》《召回》', rel:['v_hongtian','v_anzao','v_gem']},
{id:'v_gem', n:'宝石文明', c:'文明', m:'void', sec:9, e:[9], p:[240,-60,720], k:'planet', kp:{r:32,tex:'crystal',c1:'#bfe8ff',c2:'#5a8ad8',dome:1},
 s:'闪亮的结晶地表上耸立着像中世纪建筑的城市，外面罩着一层巨大的透明防护。',
 d:'第六颗巴士上的世界：闪亮的结晶地表上立着许多方形的矮建筑，像尔什民的中世纪城镇，材料光滑得像塑料，琳从没见过这种构成方式。建筑之间是一到几十米粗的透明管道，里面流着发光的液体，在全城输送。它们不久前入侵布袋的世界、抓走了暗藻。舰队像闪亮的宝石或玻璃，最大的旗舰直径一公里多，像一颗蓝宝石；总管给它们起了这个“没什么创意”的名字。九颗巴士聚到不到一百万公里的范围里开会，它们自认是会议的守护者，连别的巴士也要护着：管道的焰光烧向暗红巴士时，它们丢下一圈盾形巨石把火球包住，直到熄灭，只留下一个大坑。\n宝石生物自己很脆，外壳一碎，里面液体的能量就散了。会议的最后，宝石巴士被管道吞了进去，而把一切切成碎块的那件武器，正是放在宝石巴士上的。',
 ch:'卷六《闪亮的世界》《华丽的舰队》《开始召唤》《守护和出击》', rel:['v_hongtian','v_wumian']},
{id:'v_budai', n:'布袋', c:'物种', m:'void', sec:9, e:[9], p:[-300,0,580], k:'swarm', kp:{n:40,s:30,c:'#b8a070',big:1,sack:1},
 s:'扭动着布袋般身躯的虚空生物。',
 d:'传说两个尔什民在“飘浮山矿区”挖矿时发现了它们——那里只有这一种生物，在虚空矿山之间飘来飘去、吸食碎屑。一测，智力竟有50上下，能很快看懂尔什民的举动并作出回应，可日常生活里根本用不上这份聪明。两人为“它们能否发展出文明”争了起来：没有手，又生在虚空，看来没戏；于是把一批布袋搬去A7-0931。在引力下它们飞不起来，只能在地上挪，但身体四个角能抓东西，用得了尔什民的工具。后来布袋有了照着尔什民样子建的城市，广告牌上却只播战事和新种诞生的消息——它们本就不是很纯粹的个体生物。‘好像是很久以前做过的……试验。’',
 ch:'卷六《飘在虚空的布袋》《低等的新种》《布袋的城市》《追向虚空》', rel:['v_hongtian']},
{id:'v_silver', n:'银色世界', c:'地理', m:'void', sec:9, e:[9], p:[320,80,620], k:'planet', kp:{r:30,tex:'metal',c1:'#e8eef4',c2:'#a8b0b8',glow:.5},
 s:'地表一望无际都是耀眼的光泽，出现时连群星都暗了。',
 d:'出现时连周围的群星都黯淡下去的一颗巴士世界，直径一万公里，地表一望无际都是耀眼的银色，却有平原、山脉、峡谷，被叫作“白银”。它的居民驾着筏子般的银色飞行器——像许多圆柱捆在一起——截住了正坠向绿色世界的尔什民战舰，并宣称：既然是它们救了尔什民，尔什民就得一辈子记着这份恩情。它们抓了不少生物，给尔什民穿上自己的衣物；尔什民慢慢懂了驾驶的知识，最后乘着那些银色筏子离开。\n银色世界上满是小机械，能读取外来智慧生物的想象并照着去做：尔什民只要一心想着“这架银筏是完好的”，坠毁的银筏就真的被修好飞了起来。',
 ch:'卷六《银色之地》《按想象行事》《新世界@2135》', rel:['v_hongtian','v_dim']},
{id:'v_dim', n:'昏暗世界', c:'地理', m:'void', sec:9, e:[9], p:[-60,120,660], k:'planet', kp:{r:24,tex:'dark',c1:'#5a1a14',c2:'#2a0a08',lights:'#ffb070'},
 s:'稀薄的空气、正常的引力、极低的温度，地表像在室内一样看不见天。',
 d:'一颗暗红色的巴士，地表整个被阴影罩着：空气稀薄，引力正常，冷得厉害。从外面看还有些亮处，可一落到地上就像走进了屋里，头顶的星星全看不见，只有四周隐约晃动的巨大黑影。别的巴士地表都比较亮，这颗不但自己不发光，好像还把外面的光挡住了。尔什民的银筏经过时被击落，就掉在了这里。\n这颗巴士的性格有点怪，收留的外来物种比本地的还多，其中有一小群印加虫群，由一头十多米长、会产虚空蠊的“虫母”带着。巴士会议上，管道的焰光先烧向它，它被打成碎块，重要器官在粉碎的那一刻被转移出去，还有一部分留在管道里，成了一颗“小型巴士”。',
 ch:'卷六《昏暗的世界》《那的光芒》《到达过的位置》《守护和出击》《管道之内》', rel:['v_silver','v_hongtian','v_zhouluo','v_kongqian']},
{id:'v_ningu_gate', n:'通往凝固虚空', c:'地理', m:'void', sec:9, e:[9,10], p:[660,-100,520], k:'portal', kp:{c:'#3a3a3a',dark:1}, go:'ningu',
 s:'巴士会议碎裂之后，凝固虚空爆发了。',
 d:'巴士会议用藏在宝石巴士上的武器，把九颗巴士、断成两截的米德加尔特和所有舰队都切成了碎块。从此凝固虚空极不稳定，时不时在各处和这个虚空“混合”而爆发，挤出凝固虚空的物质，甚至连那边的生物一起冒出来；被那道裂痕碰到的，就被带到了凝固虚空的入口。点“进入地图”进入几乎一切都静止的虚空。',
 ch:'卷六《碎裂@2160》《击穿》《碎掉了》《蹦逃》《特种个体》', rel:['ng_overview','v_hongtian','ex_nuo']},

/* ---------- 星区 10 ---------- */
{id:'v_phoenix', n:'凤凰的恒星', c:'地理', m:'void', sec:10, e:[10], p:[0,0,0], k:'star', kp:{r:110,c:'#ff9a3a',plats:7},
 s:'一座建在恒星上的国度：蜂窝平台、居住平台、三公里的橘色液态神殿。',
 d:'传说里，这颗恒星曾被十个比它宽好几倍、却很细的“圆环”围绕。后来才知道，环是凤凰照着别的文明画的星系图自己造的；造好以后又舍不得把翻滚者镶上去，怕弄坏这件杰作。来访的文明说环几乎没用上恒星的能量，凤凰便把环拆了，改用大量平台把恒星包起来汲取能源。平台上有蜂窝般的居民区、足球场似的比赛场和“推翻滚者比赛”；琳给居民设计的平台拿到了“传说中的最高票数”一万票。',
 ch:'卷六《星光上的平台》《恒星住民》《以前的生物@2375》《发展@2377》《语录》《转播》《恒星之环》《平台》', rel:['v_feng','v_gas','v_xuji','v_xiaojingling']},
{id:'v_feng', n:'凤凰', c:'物种', m:'void', sec:10, e:[10,11], p:[150,60,80], k:'bird', kp:{s:14,n:24,c:'#ff7a2a'},
 s:'住在恒星平台上的好战“火鸟”，身体是一团靠“无之凝聚”维系的不规则颗粒。',
 d:'凤凰看上去像一只翅翼闪亮、浑身燃烧的鸟，身体其实是大量形状不规则的细小颗粒随手拼成的，几乎分不出内脏，唯一像器官的是一些装着“语言灰尘”的小囊：它们靠抛洒灰尘说话，灰尘不够就把大颗粒磨碎补上。颗粒随便调换位置都无所谓，真正的本体是一股来历不明的凝聚力“无之凝聚”——形体、消化、说话、动作全由它支配，记忆也存在它里面，而不在任何物质结构中；它一散，凤凰立刻溃散，身体损失太多颗粒它也会消失。凤凰只能消化幼仔初成时凝聚的那类物质。幼仔由成年凤凰洒出的“繁殖尘”里冒出一小团无之凝聚聚成，在国度各平台随机诞生，“闪烁森林”这类平台尤其多。早期按控制引力的本事分等：劣等种天生不会、靠练也摘不掉名号；初级种只能让自己飞；中等种能挪动比自己大几倍的东西，数量最多；高等种据说能排山倒海；更高等种据说能推动星球；顶尖种“据说很可怕”。学了尔什民和个性生物的文化后，它们又细分出大级、小级、阶段、水平、程度，没多久自己也嫌麻烦。它们好客又随意，爱娱乐，电影、游乐场、雕像、语录都是跟个性生物学的；只搭理说凤凰语的对象，一不高兴就扬言要把对方杀个精光。它们思维深处有一套共同的自由准则，内容是不信仰任何生物、不听被认定为生物者的命令、不被困住；被控制的凤凰一见到更自由的同类，就会不由自主地倒向对方。\n凤凰与旋风生物同源，本质上是只有核心、没有外围引力涡流的旋风，力量压缩在体内，只能在恒星附近繁衍。远古时恒星里开过一条通往远方的通道，一群生物来观察了约十个绒球年，留下一座直径十多公里的透明平台——即“最初的平台”。偶尔飘到平台上的旋风溃散后，残骸会变成凤凰；最早的它们只是一心多吸灰尘、从不伤害同类的颗粒凝聚物。高智力个体吃了旋风核心，便得到旋风游历星系时的见闻；一团卷走了“旋风教派”信徒的旋风让它们第一次有了生物、虚空、星系等概念，于是开始建造乐园，把原始种凤凰掰开拼成平台。后来乐园里出现一种一米多长、形似虫蛹、由正常与凝固物质混合而成的凝固生物，凤凰叫它们“导师”：它们起初像幻影般忽隐忽现，相处不到一个绒球年便陆续死去，又教凤凰用同伴的尸体造出第一艘飞船、建筑、武器和“引力传导炉”。导师说凤凰是唯一对它们的“祝福”起反应的物种——受过祝福的恒星凤凰体内没有反凝固物质，也能随意进出凝固虚空，米德加尔特那边的凤凰却做不到；导师一族早已灭亡，只留下会自动寻找可祝福对象的梦境能量。\n第一场传说之战对抗的是吞并了第三到第五颗翻滚者的绿噬：数百座近一公里的山形战舰直奔乐园，凤凰仓促把飞行器改成武器迎战，又设法把喜欢绿雾的旋风引过去。之后它们照别的文明画的星系图造了恒星之环，再改用平台包住恒星，不断向外发射“居民球”抓回各种生物同住。唯一一头生来就凌驾所有等级的“传奇”，出生时的引力波动推走了恒星周围几乎一切；凤凰趁机把气态巨星丢进凝固虚空，传奇率一支小队深入那里作战，击杀强敌却没能回来。它的尸体后来被收回放进培育炉，想再造一个传奇，结果生出一团绞碎靠近者的火旋涡，高级凤凰用两块三公里、能抵抗凝聚力的平台把它压扁。气态星被旋风弄回后宣布要灭绝凤凰，千千万万凤凰每群数十上百万地扑向它，被称作第三场传奇战役。它们还在凝固虚空与“废主”交战，被凤凰转化协会用小黑球陷阱抓去米德加尔特虚空改造，又在离恒星一亿多公里处迎战死亡战舰。学生问导师，凤凰为什么要亲自上阵；导师答：当你自己飞得和导弹一样快、爆炸比导弹更猛、还不在乎性命时，“那为什么要用导弹？”\n旋风生物与墟集神让被俘的凤凰得知恒星寿命将尽。后来整颗恒星喷出直冲数十万公里的火柱，越缩越小，最终消散，只剩平台和碎块；凤凰似乎早有预感，全都飞起避开，并认定恒星本身就是最伟大的传奇——恒星里汇聚的无之凝聚形成了一个巨大的“恒星凤凰”意识，它的规则是让别的生物极度激动，通道也暗中把它定为继承者之一。凤凰围着它继续与米德加尔特虚空的死亡战舰作战。再后来，琳在“返乡之道”的浓雾下见到许多一两米、灰扑扑、只能用翅膀爬的“熄灭的凤凰”；约十万凤凰从笛子状奇迹制裁的空间涌出，与细线世界那种光线专能让凤凰崩解成灰的藤壶礁交战，一心要返回故乡。',
 ch:'卷六《恒星住民》《欢呼？》《语录》《传奇的一生》《传奇的战役？》《诞生@2407》《停转》《远古的生活》《形成@2420》《导师》《第一场》《现在@2431》《直接地碰撞》《恍惚的记忆》《导师？》《传奇之战》《塑造凤凰》《失败的全新品种》《照明》《远古的事物》《凤凰的战争》《覆盖》《新的传奇》《到达@2688》《聚集与交战》', rel:['v_phoenix','v_xuanfeng','v_gas','v_mechmoon','v_lvshi','v_xuji','v_guanxing','mg_overview','v_yiyin','tn_xianqu','bk_home','ng_phoenixhero']},
{id:'v_xiaojingling', n:'恒星小精灵', c:'物种', m:'void', sec:10, e:[10], p:[-120,50,140], k:'swarm', kp:{n:120,s:22,c:'#ffe08a'},
 s:'一到十厘米大小的凝固混合物，背后一对两倍体长的翅膀。',
 d:'一到十厘米大小的凝固混合物，没有固定形状，会根据环境改变自身；背后一对展开有体长两倍、厚一毫米的“翅膀”，不管有没有空气，只要移动就以每秒一百次以上的频率扇动，翅膀本身能产生微弱的引力，所以在任何环境下都能快速移动。这是琳来到凤凰那里第一眼看见的生物：它们是凤凰的搬运工，听凤凰用特定的语言指挥——不是凤凰特意养的，只是偶然发现很有用。球神那边也出现过它们。和几只燃烧的鸡一起，它们把琳的彗星钻头推到了平台上。',
 ch:'卷六《星光上的平台》《教育》《比赛项目》', rel:['v_phoenix']},
{id:'v_gas', n:'气态巨星 · 蓝色竹林', c:'地理', m:'void', sec:10, e:[10], p:[440,-40,160], k:'planet', kp:{r:70,tex:'gas',c1:'#4ad08a',c2:'#1a7a4a',moon:1},
 s:'凤凰后来把它丢进了凝固虚空。它的一颗卫星上，长着一大片蓝色的竹林。',
 d:'凤凰曾在这里推行“凤凰化计划”，往卫星上投下居民球，想把居民变成凤凰，结果它们只会一点点化成灰尘。为了暂停灰尘化，凤凰把这颗翠绿的气态巨星连同卫星推进了凝固虚空，它们却没有被凝固，从此活在没有星光的黑暗里。蓝色竹林所在的卫星叫“阿拉密斯”：两米高、像火龙果的生物用刀片般的叶子砍开空心的竹竿，吸食里面的粉末“天之精华”。它们说自己在“天相异变”之后一直修炼求长生，其实是靠精华压住灰尘化；长老们约好，不把凤凰的事告诉后代。',
 ch:'卷六《气态球》《迷途竹林》《天之精华》《只有灰烬，没有重生》《没有暂停》《一直的测试》《现在@2431》', rel:['v_phoenix','v_mechmoon']},
{id:'v_mechmoon', n:'机械卫星 · 灰尘之海', c:'地理', m:'void', sec:10, e:[10], p:[540,40,300], k:'planet', kp:{r:24,tex:'metal',c1:'#7a7a74',c2:'#4a4a44'},
 s:'一颗三千公里的小卫星，地下是两百米深的灰尘之海。',
 d:'有同情心的“灰尘拯救者”曾看着这里的生物一个个灰尘化，无法逆转，只好试着做点什么。巨大的机械吸收生物灰尘获得了记忆，想向凤凰复仇；凤凰十几个一组撞击机械，它们奇怪怎么变弱了，结论是：毁灭的力量还不够。\n灰尘之海底下还藏着一个一百多米、像海兔的拯救者。一台小机械解析了传奇凤凰留在虚空里的语言灰尘，性格和记忆都被凤凰取代，以为自己就是传奇凤凰，想重演当年的战役——这其实是拯救者安排的，好借它研究凤凰。',
 ch:'卷六《拯救？》《机械的过去》《传说的？》《传奇的战役？》《承载着梦想与希望》《灰尘中的记忆》', rel:['v_gas','v_feng']},
{id:'v_xuanfeng', n:'旋风生物', c:'物种', m:'void', sec:10, e:[6,10], p:[-160,-60,250], k:'vortex', kp:{r:30,c:'#2a2620',small:1},
 s:'以核心为命、外裹回旋碎屑的风暴生物；与凤凰同源，后来崇拜墟集神。',
 d:'旋风、狂风、飓风、龙卷乃至熔岩风暴——在某些地方，它们不是天气而是生物：一个方形或圆形的核心是生命中心，外面裹着不停回旋的碎屑和灰尘当身体，种类按核心大小和卷起的物质区分。创造者监狱所在的那颗星系边缘的世界里，有卷着发亮结晶、带大王花般气味的“冰风”，有在燃烧的坑洞上把火焰卷进身子的“火漩涡”（火焰类旋风大多短命，有的十几秒就走完爆发、成长、死亡和繁殖，脑灵还拿爆发强的种类当武器），还有会种沙藤丛林、建起过“砂砾之国”的“塑藤者”。研究者猜它们源自一场席卷整个星系的特别风暴，让某个世界地表的基础物质活了过来。一个研究者曾在那里设地下研究所，后来它的“同伴”占了研究所，看中旋风想编入部队，又把危险的创造者关进去当作考验。方形飞行器毁掉了塑藤者的国度、到处捕捉旋风，脑灵还把旋风派到绒球的南极冰原作战；琳把它们的名字译成熟悉的词，也曾带着一团塑藤者旋风同行。\n拯救者把它们的本质叫作“无之凝聚”：在毫无缘由的地方凭空出现、把周围物质聚拢的力，这类生物被称为“空生体”，可能来自不可预见之地。最早的样子像个会自己移动、会努力不让自己散掉的小龙卷，靠核心损耗时洒出的碎屑繁衍。它们在虚空漂流时不断损耗，要补充回旋的灰尘，各有偏好的物质，感知范围却很窄。杀死旋风要么毁掉核心，要么把两团硬挤在一起，让一方消散；复杂的种类还能射出干扰对方凝聚力、甚至让它停转的“力”。野生核心停转后仍可能重新生出旋风，拯救者仿造的核心不会，却能骗旋风当成同类。凤凰与它们同源：旋风先凝出核心，再在周围形成引力涡流；凤凰只有核心，而且只能在恒星旁诞生。旋风在凤凰平台上溃散的残骸会变成凤凰，它们的核心记录着游历星系时见到的一切，高智力凤凰吃下就能得到这些知识。\n凤凰星系的旋风原本很单纯，凤凰为对付绿噬把它们引去吞绿雾，混合太久后它们有了复杂的心思，也和墟集神有了联系，一直崇拜它。气态巨星里住着巨型旋风，还有一种核心几乎隐形、负责把“精华”送到周围卫星的旋风。气态星被丢进凝固虚空后，旋风设计凤凰：给它们一种特殊物质，让它们在指定地点造出大批小旋风——其实都是巨型旋风的高智力分身，逃到离恒星约一百亿公里的星系边缘，寻找让气态星回来的办法；导师想“祝福”它们，反被它们杀了。气态星回来后，旋风宣布要毁灭凤凰全族和恒星，凤凰的“隔断之锯”专往旋风最多的地方飞。旋风拦截凤凰的信号塔，让一米多大的旋风幼仔在闪烁森林与凤凰幼仔厮杀，又在重叠区刮下墟集神外壳的碎屑，做成能让凤凰误以为是同类讯息的“最初之物”，把往事和恒星将亡的消息灌给被俘的凤凰。模型沙海里另有一种没有核心的“元初旋风”，身体是一条由元初凝聚拧成、长上千万公里却只有数十米宽的线，能变出继承它记忆的新旋风；返乡之道的墓碑间，则飘着凝聚力弱得几乎要死的旋风。',
 ch:'卷六《狂风的传说》《寒冷和温暖》《旋转的历史》《过去@412》《接近之物》《气态中的生态》《无之凝聚》《同类的战争》《停转》《吸引@2411》《提升》《清扫@2423》《恍惚的记忆》《战役的定制》《导师？》《所在》《完美的计划？》《奇妙物质》《带回情报》《捕捉@2473》《元初的旋风》《边缘@2689》', rel:['v_feng','v_prison','v_lvshi','v_xuji','a3_heifeng','v_gas','v_mechmoon','v_guanxing','tn_sand','bk_home']},
{id:'v_lvshi', n:'绿噬', c:'物种', m:'void', sec:10, e:[10], p:[-260,30,180], k:'fog', kp:{r:80,n:40,c:'#5ac85a'},
 s:'吞噬整个星系的绿色浓雾。',
 d:'被它占领的世界不分昼夜弥漫着遮天蔽日的浓雾，城市里的生物躯壳像机械一样活动。它最早是一座座装着绿雾的“绿雾山”，和被它侵蚀的生物一样是“尘粒生物”，只是把神经扩散成了雾；它的舰队是一公里上下、装着引擎的山。凤凰身上混进它的尘粉就会神经异常，但能用引力护住身体。最后凤凰用“广播弹”把整个星系的旋风引来，旋风包围了每一个被侵占的世界，把绿雾卷进自己体内——绿雾失去了思维，旋风却变绿了，开始成群行动。凤凰又把绿噬留下的躯壳变成真正的生物。',
 ch:'卷六《导师》《第一场》《清扫@2423》《新的感觉》《苏醒@2426》', rel:['v_xuanfeng','v_feng']},
{id:'v_guanxing', n:'观星之印 · 穿星之印', c:'文明', m:'void', sec:10, e:[10], p:[240,140,-60], k:'bird', kp:{s:60,n:1,c:'#ffb040',starry:1},
 s:'凤凰把自己的许多平台合体拼成的战争兵器：样子是一只放大的凤凰，两翼张开约十公里，外壳亮得像一颗在燃烧的恒星。',
 d:'它从双翼洒下无数“凤翼飞弹”，威力和尔什民的聚变弹相当，不同的是炸开的烟云是凤凰的样子；名字的意思是一击就能在翻滚者上打出一个透到对面星空的印记。它们冲着对手喊：退路没有了，逃也逃不掉，前面只有末日。它一直用多种凝固生物的语言广播。后来它被墟集神的触手缠住，漆黑从触手处蔓延到全身，内部机能接连停转；它还装着一套“自我意识”，没有凤凰驾驶时会自己行动。在先祖之地，它从翅膀洒下能切开凝固物质的“火羽”，又把自己的引力引擎当成“穿星”能量球射进地下——可那块大石头根本没有地心。',
 ch:'卷六《观星之印》《完美的计划？》《凤凰与舰长》《奇妙物质》《远古的事物》《准备躲避》《战斗@2500》《先祖的沼泽》', rel:['v_feng','v_xuji']},
{id:'v_xuji', n:'墟集神', c:'物种', m:'void', sec:10, e:[10], p:[-320,80,320], k:'blob', kp:{s:40,c:'#4a3a4a',tentacles:1},
 s:'古老而强大的生物，能用触手从空中直接拉出建筑。',
 d:'名字是琳把‘废墟之主’（废主）和“器官集合体”合起来起的，“神”则因为旋风生物崇拜它。最早的墟集神只是几米大、聚着大量器官的凝结物。它会分裂成废主、器官集合体，以及“碎片种”——其中一些忽然醒悟“这么收集没有任何意义”，成了“懒惰种”。废主喜欢收藏和交换，曾和凤凰打过传奇之战。',
 ch:'卷六《收藏品》《废墟与器官》《世界之一？》《碎片种》《懒惰》', rel:['v_feng','v_guanxing','v_xuanfeng']},
{id:'v_snow', n:'雪原世界', c:'地理', m:'void', sec:10, e:[10], p:[-460,-60,-150], k:'planet', kp:{r:36,tex:'ice',c1:'#f4f6f8',c2:'#c8ccd0',lights:'#ffb04a'},
 s:'凤凰在这里飞不起来。追光生物戴着火把，永远无法离开雪原。',
 d:'两肢生物、飘浮生物等十多种生物统称“追光生物”：它们完全无法自行反凝固，只能靠寄生在身上的炉火类生物“火把”放出反凝固场，被吸取养分直到死亡。一米高、能跳的“雪光”几十个一群，头领顶着火把。一座三千多米高的雪山顶上有建筑，每级台阶都有一米高。血山的外壳裂开，里面是一头全身透明的光龙。',
 ch:'卷六《雪原》《山顶的建筑》《只有光明》《最后一步》《雪原边境》《穿透》', rel:['v_huobanao','ng_luhuo','guanglong']},
{id:'v_huobanao', n:'火把之脑', c:'物种', m:'void', sec:10, e:[10], p:[-430,-20,-110], k:'none',
 s:'没有行动能力、只待在原地发号施令的“脑”，可能是最后一个。',
 d:'其他火把是因为它才变成火把的样子。它感知力极强，指挥的不是自己的身体而是别的物种；炉火里的怀疑个体开始质疑警报指令，它就转而控制那些不会怀疑的个体。琳决定让它活下来。',
 ch:'卷六《模仿命令》《协助》《准备躲避》', rel:['v_snow']},
{id:'v_ancestor', n:'先祖之地 · 三个世界', c:'地理', m:'void', sec:10, e:[10], p:[-200,-100,-420], k:'planet', kp:{r:34,tex:'jungle',c1:'#3a5a3a',c2:'#5a4a3a',fog:1},
 s:'‘这三个世界是一起诞生的，什么都是共用的。’',
 d:'绒球、先祖之地和“三号界”曾共同诞生、同步变化——绒球缺氧的时候，有部分细胞生物来到了这里。先祖之地有沼泽，有十米高、被小鸟们当成怪物的翡翠龙骨架。把“末忆线”发射出来的生物想再造三号界；一枚枚“多界之骨”导弹体内装着储藏整个世界的装置，穿过风暴般的“末日海”。阿特兰也把这里当作最初的翻滚者。',
 ch:'卷六《过去》《多界之骨》《先祖的沼泽》《过去的毁灭》《模拟的发展》', rel:['rongqiu','v_zhujie','v_moriha','ng_quanyan']},
{id:'v_zhujie', n:'诸界之骨 · 多界之骨', c:'物种', m:'void', sec:10, e:[10], p:[-420,60,-380], k:'ship', kp:{s:30,c:'#e8e0c8',bone:1},
 s:'空心骨架里装着许多十几厘米的装置，每个装置里都是一个完整的世界。',
 d:'装置类似琳的“梦境之脑”，里面有复杂的生物、文明和生态。诸界之骨的指挥室里有一个负责控制所有世界的文明，它们能修改别的世界的规则，却改不了自己的世界——那里到处飘着数百米、雪白云朵般的东西。',
 ch:'卷六《多界之骨》《内部的我们》《守护的信息》', rel:['v_ancestor']},
{id:'v_moriha', n:'末日海', c:'现象', m:'void', sec:10, e:[10], p:[-620,0,-300], k:'fog', kp:{r:110,n:40,c:'#6a7a8a',lightning:1},
 s:'充满风暴的地方，像在暴风里行动。',
 d:'强烈的气流让人无法自由动作，只有特制的导弹不受影响。“末忆线”就生活在这里，它从末日中诞生。',
 ch:'卷六《转移？》《过去的毁灭》', rel:['v_ancestor']},
{id:'v_tunnel_gate', n:'通往白色通道', c:'地理', m:'void', sec:10, e:[10], p:[260,100,-440], k:'portal', kp:{c:'#f4f4f0',white:1}, go:'tunnel',
 s:'凤凰找到的古老通道。',
 d:'一大群凤凰聚在一片雪白的虚空里，围着唯一不那么白的地方：一个一百多米宽、表面显示着复杂图案的圆形物体。据说这是一条古老的通道，先驱们曾经从这里去过许多不可思议的地方；有只凤凰说着能聚在这里很荣幸，说到一半又改口，说它们才不觉得荣幸。点“进入地图”。',
 ch:'卷六《古老的通道》', rel:['tn_overview']},
{id:'v_wuyi', n:'边无蚀地', c:'地理', m:'void', sec:10, e:[10], p:[500,-90,-320], k:'disc', kp:{r:100,c:'#6a6a64',c2:'#4a4a46',mud:1},
 s:'没有边界、会腐蚀一切的灰色泥地。它也许是活的。',
 d:'它没法被远距离感知，接近之前什么都看不到。花朵生物带着琳以每秒五十米的速度在上面游荡了两个绒球昼夜，地下深处满是“爆吞”——它们是边无蚀地制造出来、专门吃花朵的怪物。泥浆一族也在这里：数十上百公里的古代泥浆、射出长矛和钻头的泥浆领主，以及红色的“红浆”。',
 ch:'卷六《边无蚀地》《依赖腐烂之物》《蚀地的怪物》《泥浆的传说》', rel:['v_huaduo','v_nijiang','tn_overview']},
{id:'v_huaduo', n:'花朵生物 · 爆吞', c:'物种', m:'void', sec:10, e:[10], p:[540,-60,-260], k:'none',
 s:'漂流的花朵身上有一整套复杂的生态。',
 d:'花朵生物直径最多几十米，像浮游生物一样漂在虚空隧道里，每片花瓣上却住着上千万种生物，花瓣之间的进食器官把各片的生态隔开。有生物研究它们后认定，这种生态不可能“自然”长出来；它离开前留下了鲨鱼似的“爆吞”，一路追吃遇到的每一朵花——花朵认为那就是边无蚀地。一朵被制造装置改造过的“回归花朵”离开隧道后，同伴接连死去，它吃掉同类的尸体活了下来；被虚空帝国的采矿船炸碎后，碎块成了听它指挥的肉块，它和帝国做起了买卖，又暗暗想征服帝国、复兴种群。后来稳定虫袭击了它的脑，再用残留的神经拼回一朵花，这朵花能直接影响周围的空间，拦住了模型沙海。',
 ch:'卷六《花朵的起源？》《发疯》《再构筑》《生活@2608》《多次改造》《边无蚀地》', rel:['v_wuyi','v_wending','wendingchong','tn_empire','tn_sand']},
{id:'v_nijiang', n:'泥浆与“奇迹”', c:'物种', m:'void', sec:10, e:[10], p:[460,-120,-380], k:'blob', kp:{s:30,c:'#6a5a4a'},
 s:'奇迹不一定是好事：稳定的恒星突然炸掉，恐龙忽然说出虚民的语言，都算奇迹。',
 d:'古代泥浆有几十上百公里大，记忆像博物馆一样要慢慢“阅览”，它们不认为那些记忆是自己的。奇迹生物在虚空中埋下许多“奇迹”，都要经过最初、生长、完成三个阶段——模型沙海就是其中之一。一只被奇迹折磨得满身彩色的古代泥浆决定阻止所有奇迹，派小泥浆去炸奇迹的发生点，最后死在模型沙海附近，死因成谜。红浆是另一只古代泥浆分裂出的小泥浆：它们发现所谓“晋升”的尽头是被母体吞掉，便联合起来打败了它，在尸体上建起国度——却也照样把新生的小泥浆当作“道具”使用。道具泥浆被无形煽动造反，想当普通居民，红浆的大军一路把它们打散。无形则想借尔什诞生“恒古之泥”。',
 ch:'卷六《泥浆的传说》《连续发生的奇迹》《阻止奇迹》《结束的意识》《红色亚种》《红浆的国度》《中断的队伍》《沟通》', rel:['v_wuyi','tn_wuxing','henggu','tn_sand','ex_planet']},
{id:'v_wending', n:'稳定虫的空间站', c:'文明', m:'void', sec:10, e:[10], p:[620,40,-120], k:'station', kp:{s:24,c:'#a85a5a',flesh:1},
 s:'表面覆盖着血肉般物质的空间站。“稳定是唯一的真理。”',
 d:'表面覆盖着血肉般物质的空间站，信条是“稳定是唯一的真理”。稳定虫是一种凝固混合生物，曾把血肉生物的脑部毁掉；它们“永远稳定”——变化无数，却怎么也变不了。琳的微型兵种在站里找到一间像博物馆的大厅：到处是罩着半球透明罩的艺术品，正中是一个直径三十多米的生物，五片血红色“花瓣”围着闪着白光的“花蕾”，形状和三号界一模一样。刚要检测，稳定虫就从四周的出入口涌了出来。后来成千上万的绒球与数千艘血肉覆盖的飞行器打了一场小仗。\n琳从空间裂缝里伸出绒毛，把这朵“花”从馆里拔了出来——它正是被稳定虫用残留神经重新拼起来的花朵生物。',
 ch:'卷六《一种生物@2598》《血肉？》《永恒与稳定》《爱好稳定》《稳定的中心》', rel:['v_huaduo']},
{id:'v_xixian', n:'细线的海洋翻滚者', c:'地理', m:'void', sec:10, e:[10], p:[-80,120,540], k:'planet', kp:{r:40,tex:'ocean',c1:'#1a4a7a',c2:'#0a2a4a',atm:'#7ab8ff'},
 s:'细线的海洋世界：深海底部柔软的“海床”就是隧道之种，上面飘着代表它思维的短细线。',
 d:'一颗直径约三万公里的海洋世界。细线接受了寻找“返乡之道”的任务，却不知道任务来自谁。深海底部像水母外皮一样半透明、柔软的“海床”就是“隧道之种”，上面飘着大量很短的细线，代表它的思维；它守着细线的世界，一直想把奇迹制裁凝聚起来，让崩塌已久的虚空隧道复苏。旁边还有一颗更大、看似连海床都没有的“平静的世界”，任务的源头就在那里：它只能搅动海面，掀起液态山脉似的巨浪去拦死亡战舰。琳的船潜到一万米深，才在白沙海床上找到一个个十米的光球，里面的白星醒来后以为自己是创世神，开始在这里“创造生命”。',
 ch:'卷六《任务源头》《海@2728》《深海之物》《共同目标》《海下的荒漠》《生命》《新的指引》', rel:['bk_home','tn_overview','bk_qiji','ex_baixing']},
{id:'v_bone', n:'骨头的王国 · 废弃场', c:'文明', m:'void', sec:10, e:[10], p:[180,-120,580], k:'rocks', kp:{r:90,n:60,s:10,c:'#e8e0c8'},
 s:'骨头的文明，与废弃场里进化出来的“神”。',
 d:'骨头没有细胞结构，身体却也分成许多器官。食物仓库里有一只寄居蟹般的生物不断进化，与扭曲装置融合——像昆虫的蛹一样瓦解又重构，成了以“扭曲”为信仰的“神”，最后化作一块巨大的“钻石”飞离。废弃生物与骨头打了一场惨烈的战争，来自凝固虚空的“混合”现象让一切变成末日。\n骨头吃的是一种像钻石的物质。战争最后骨头赢了，却只能搭在最后造出的生物兵器“荆棘团”上漂流，靠它找吃的。“神”被摧毁前放出过许多分身，其中一个是十多米的骨堆。',
 ch:'卷六《另外的种族》《异星来客？》《废弃生物》《新的想法》《伟大的造物》《最后的活物》', rel:['v_bridge']},
{id:'v_bridge', n:'唯一之桥', c:'文明', m:'void', sec:10, e:[10], p:[-460,-40,480], k:'bridge', kp:{len:360,c:'#8a7a6a'},
 s:'在虚空中漂流的巨桥，上面住满了文明。',
 d:'合成生物诞生在“虚空杂物堆”，永远杀不完，见到东西就往自己身上装。研究者把自己的神经连上合成生物，操纵大群同类，成了最早的“统一信仰”。后来又有随机信仰（“民之初，性随机”）、平静之国——一团肉块控制军队，向桥上所有文明宣战。巴士生物据说曾把唯一之桥传送到有食物的地方。\n桥上还有一间录影记录室：管理者夺桥之后，幸存者曾聚到一个从没用过管理者技术的“落后”国度里组军，却忽然全都相信自己达到了平静，什么也不做，接连饿死。整座桥后来被改造成了一艘战舰；琳也启动过它，借凝固虚空去追一头凝固生物。',
 ch:'卷六《特殊崇拜》《集合之源》《庞然大物》《早期》《信仰》《创建》《平静@2832》《记录@2840》', rel:['v_bone','v_warbus','a5_guanli','ex_travel']},
{id:'v_warbus', n:'战争巴士 · 回忆巴士', c:'地理', m:'void', sec:10, e:[10], p:[640,-40,520], k:'planet', kp:{r:40,tex:'sand',c1:'#c8a878',c2:'#7a6a52'},
 s:'一颗陷在回忆里、永远模拟着那场战争的巴士。',
 d:'地表是沙漠，沙粒聚成战争生物；地下六十六层，洞壁是溶解重组过、像黑色果冻的器官。半蟹民——像尔什民和蟹的组合——拿着光剑满洞穴找维罗尼卡和诺。“战争的回忆”是一种飘荡在虚空的能量；一颗“蛋”里装着能给大量虚空生物发送信号的思维发送器。\n它的样子，正是尔什在“战争回忆”里扮演的那颗巴士。',
 ch:'卷六《遭遇@2854》《陷入》《危险生物》《梦想？》《蛋@2860》《风暴之眼》《基地@2862》《变异@2863》', rel:['v_bridge','c_veronica','ex_nuo']},
{id:'v_buke_gate', n:'通往不可预见之地', c:'地理', m:'void', sec:10, e:[10,11,12], p:[-660,120,120], k:'portal', kp:{c:'#e8d8ff',pale:1}, go:'buke',
 s:'另一个虚空。',
 d:'从返乡之道一路往里，就到了规则完全不同的地方。点“进入地图”。',
 ch:'卷六《曾经连接的家园》《慢慢远离》《飞向那里》卷七《了解@18》《远征》', rel:['bk_overview']},

/* ---------- 星区 11 ---------- */
{id:'v_pain', n:'痛苦巴士', c:'地理', m:'void', sec:11, e:[11], p:[-300,0,0], k:'planet', kp:{r:50,tex:'red',c1:'#8a1a1a',c2:'#3a0808',fog:1,atm:'#ff4a4a'},
 s:'一颗喜欢制造痛苦的巴士，让地表生物永远困在无法满足的痛苦轮回里。',
 d:'琳把这颗巴士叫作“痛苦巴士”：它不断制造痛苦的轮回，让地表的生物一代代重复受苦。它的世界里本没有快乐与满足，智慧生物只能靠理智忍耐；一旦它们找到直接获得满足的办法，地震便把一切毁去，之后植物重新长满大地，有情绪的生物再次出现、进化出智慧、建起文明，又会遇上种种阻挠满足的事——越满足身体越差，满足后剧痛，造好的东西过一阵就碎掉。到琳来时，地表只剩极少几种生物：三十多米高、装满脑细胞的透明罐子“罐脑”，连着它的许多红色肿块般的培育仓，以及仓里肢体或器官残缺、一离开培育仓就死去的生物。琳射出大量“满足针”，用信息素让它们强行满足，大地顿时暴怒震颤，红雾像鲜血一样从裂缝涌出，覆盖整个地表，从虚空中都看得见，但并不伤人。地下是它尚未硬化的神经所在的“鲜红地狱”，满地残缺生物被红色管道拴着，管道都汇向洞穴中心；硬化的神经里则记着历代生物的痛苦，还有被它困住的强大意识——一个同情心极强、想帮地表生物的来客发现幕后是巴士后想逃，却被引力拖下摔碎，神经被拖进地底；熔链也被它拉散成无数圆环坠落；宣传“巴士邪恶”、制造风暴之眼的那个生物也困在这里。\n痛苦本身变不成痛苦能量，还需要载体，所以它一直把巴士生物、梦境生物这类能量思维生物吸引到地表上，接近它的生物情绪会被放大，同情心异常强烈；但它从没造成过痛苦能量。一条自称是它意识残片的十米长白色幼虫向琳讲述了这些，随后它的神经被巴士下令自行断开而死。后来它感觉到遥远虚空中有个充满痛苦的地方，便认定那里就是自己追求的东西，改为去连接这片“痛苦之地”。它体型虽小，传送能量储备却和一万公里的巴士相当，能接连传送；残猎者被它呼唤而来，又被它放出的痛苦信息逼退、击落。废品倾泻球冲向它，两颗球在相距一万公里处停住，周围的虚空景色却像被撞到一样颤抖，那是倾泻球对它产生的强烈恐惧；倾泻球改用彩色的空间通道弹钻进它的地表，沿路倾倒废品，还丢下装满危险能量物质的密封容器。痛苦之地能量不足时它一度停摆，恢复后便在地表隆起“火山”，射出黑色的痛苦爆弹，让虚空中的板块自行解体。\n熔创者用满载痛苦的熔块战舰拖住它，再推着自己的“恒星”撞来，想一举毁掉它，并借它的痛苦能量把自己变成完美的“星空之惠”。它的样子与“琥珀之球”一模一样——那是琥珀创造者造的镜像世界，琥珀创造者曾想寄生成熟的巴士，与它打过一场“寄生之战”；琥珀生物中有一支被它教导、学会创造者的语言，爱上了它，甚至自杀献身。它把八百米高的山扔向敌人，把部分神经送出去撞击一亿公里外的熔块战舰，又命所有浮岛降落地表做“最终的冲刺”。得知熔块们想引发它与琥珀球的“共鸣”同归于尽、借此打开痛苦之地的入口后，它决定直接进入痛苦之地；它的神经一度为自保而停止活动，在生岩记忆和琥珀生物的呼唤中缓慢苏醒。最终它穿过痛苦之地，飞向三十万公里外一颗被海洋包裹的翻滚者，故意让“捕获球”捕获自己，与它进入同步毁灭的阶段。',
 ch:'卷六《异常@2890》《思维的墙壁》《轮回》《鲜红的地狱？》《塑造意识》《提取@2896》《它的意识@2897》《空洞》《追求目标》《断裂@2901》《总部》《过去@2910》《碰撞@2911》《危险品》《崩裂@2930》《共同的痛苦》《抵达？》《创造的平静》《感觉@2971》《永痛之渊》《感激》《缝隙》《另一颗》《最后的@3044》', rel:['v_dump','v_painland','v_canlie','dr_ronglian','v_amber','v_dongchuang','v_kuding','v_liquid','v_xingmeng']},
{id:'v_dump', n:'废品倾泻球', c:'地理', m:'void', sec:11, e:[11], p:[-120,60,140], k:'planet', kp:{r:22,tex:'rock',c1:'#6a6058',c2:'#3a342e',debris:1},
 s:'一个真正的“废品站”，专门抛弃许多文明的遗物。',
 d:'直径接近一百公里。一群生物被迫不停产生废品，否则整个世界就会出问题。‘它管的不只是一个文明留下的东西，是很多个。’',
 ch:'卷六《倾泻物》《过去@2910》《离开与留下》《危险品》', rel:['v_pain']},
{id:'v_canlie', n:'残猎者', c:'物种', m:'void', sec:11, e:[11], p:[-260,40,60], k:'swarm', kp:{n:30,s:30,c:'#8a6a5a'},
 s:'“残留追猎者”，喜欢收集文明毁灭前发射出去的最后希望。',
 d:'全名“残留追猎者”。许多文明在毁灭前都会留下点什么：历史和技术、几个可能让文明复兴的幼仔、一艘载满幸存者的飞行器……残猎者专门收集这些最后的希望。它曾藏在痛苦巴士里一只幼虫的体内，到处宣扬巴士的邪恶；琳把幼虫改造成自己的兵种，又留着它的意识，好向它问话——它对身份暴露并不惊讶，只是没想到自己会死。一百个“总部”坠毁在痛苦巴士的地表上。',
 ch:'卷六《另一种猎手》《追猎之物》《过去@2910》', rel:['v_pain']},
{id:'v_painland', n:'痛苦之地', c:'地理', m:'void', sec:11, e:[11], p:[-520,-40,-150], k:'rocks', kp:{r:120,n:50,s:16,c:'#8a2a2a',glow:'#ff4a3a'},
 s:'汇聚了无数生物痛苦的隐秘空间，痛苦能量可储可爆，非常适合当武器。',
 d:'痛苦之地原本是正常虚空中一种很古老的存在，琳暂称它“汇聚地”：它的思维和巴士生物一样由无数小空间汇成，却没有物质躯体，固定在一处，最初不会思考，与其说是生物不如说是一种自然现象。巴士在它附近传送时，飘散开的传送能量总有极少一部分被它接收，它能从中得到大量信息；后来它把其中多数情绪资料丢掉，只留下痛苦，渐渐变成收录各种生物痛苦的地方。任何生物靠近，它都会把储藏的痛苦转成对方能解读的信号灌进去，让对方痛苦而死，就算及时逃开也会被折磨到死。之后它把自己藏进了虚空某处，影响却从未断绝：它附近渐渐出现痛苦结晶。痛苦巴士隔着遥远的虚空感应到它，认定那里活动着自己一直想造的痛苦能量，便改为设法连接它。\n有一个世界里有闪烁结晶的华丽洞穴，洞里的水母会“诉说”那里的历史：旧文明崩塌后，在废墟中长大的幼仔个个想当王，便研究起痛苦结晶，造出发射痛苦的枪械、爆发痛苦能量的炸弹，结晶不够就挖地下深处的痛苦物质，最终整个文明灭亡。在这样的“痛苦聚集地”上，痛苦能量能储藏也能爆发，威力恐怖，最适合当武器；结晶液化后还像尔什民的“石油”一样能给文明供能。聚集地的结晶直连痛苦之地，被抽走多少它就补多少，可近来它的能量不够了，像是有什么在吸取，这也是痛苦巴士一度停摆的原因。苦钉民在“痛苦陆地”上，把不到半毫米的痛苦结晶贴在脑旁，靠钉子般的飞行器生活，研究痛苦得来的技术让它们能隐身。\n痛苦之地内部是一片漆黑。琥珀创造者因裂空团的通道出错而跌进这里，被剧痛吞没，意识一次次死去又醒来；后来它用不断死亡、不断再生的脑细胞筑成一道墙，把有记忆的脑细胞护在“脑堡”中心，从此虽痛却不致死，并靠裂空团误送进来的东西解决温饱，开始在这里建立自己的快乐国度。那时虚空中许多生物做噩梦的次数多了起来，梦到的正是这个地方。群星联盟听宙脑说起后，派出上万艘战舰来摧毁这片“地狱”，几个检测员只稍稍感觉到就惨叫着自杀了；送进去的机械感知到四面全是危险而损坏，又被创造者收集改造。联盟用能让空间恢复为原始传送能量状态的“空间坍塌弹”轰击，再引爆创造者回收的舰船。冬创者在联盟的大战中被空间裂口吞进痛苦之地，在这里感知到联盟节节败退、最后被“暂停”，后来借裂空团设法离开；痛苦巴士最终也直接进入了这里。痛苦之地附近还会膨胀出一团约十公里、装着文明灭亡之痛的漆黑浓雾，远远就能把痛苦打进生物的思维。',
 ch:'卷六《追求目标》《古老的痛苦》《离开与留下》《痛苦之地？》《痛苦的结晶》《聚集地@2916》《吸取》《痛苦生物》《汇聚的世界》《感觉@2971》《持续的痛苦》《痛苦与快乐》《梦魇的开端》《传说中的地狱》《接触@2992》《坍塌？》《梦魇的结束》《群星之末》《躯体》《炸裂@3011》《策划者》《展现》', rel:['v_pain','v_kuding','v_xingmeng','v_amber','v_dongchuang','v_zhounao','v_tianlan']},
{id:'v_kuding', n:'苦钉民', c:'物种', m:'void', sec:11, e:[11], p:[-560,80,60], k:'ship', kp:{s:22,n:6,c:'#c8c0b8',needle:1},
 s:'地道的虚空生物：不靠任何东西，就在虚空里自己长大。',
 d:'它们必须连进梦境体内才能产生生活必需的物质，于是被“恐怖寄生体”寄生——先是微生物，后来寄生在它们的梦境里，化作一棵“柳树”。‘不能再让它管着我们了！’寄生体控制了苦钉民所有的造物，唯独没控制住苦钉民本身。',
 ch:'卷六《结束寄生》《攻击@2921》《解锁》《击落》《设计@2926》', rel:['v_painland']},
{id:'v_amber', n:'琥珀之球 · 熔块', c:'地理', m:'void', sec:11, e:[11], p:[-200,-100,-350], k:'planet', kp:{r:40,tex:'amber',c1:'#e8a03a',c2:'#8a4a1a',isles:6},
 s:'琥珀生物的世界，浮岛上的都市。它的源头是一个以尸体为材料的文明。',
 d:'“熔块”从不收集建筑材料，用的全是同类的尸体：低温死去的熔块变成“原冷石”，偶尔变成“星空之惠”。它们升华进一个“火球”，从不研究自身。熔创者体内像大量齿轮；琥珀外壳的橘红小虫是这里最常见的生物。琥珀生物捕获了传说中的“永痛之王”，要把它放到地底核心……最后它们跟着新世界冲进了“永痛之渊”，只活下来一个琥珀，一遍遍呼唤着深爱之物。\n熔块和观察器的战争其实是一轮轮“升级”：熔创者回收每一代熔块的技术，放进下一批熔块的记忆里，所以每代都会慢慢“觉醒”上一代的发明。它从“恒星”里放出上千艘火山石般、百米大小的熔块战舰，可它们一靠近痛苦巴士两万公里，就痛得动弹不得。',
 ch:'卷六《建立@2933》《创熔之物》《星空的恩惠》《低温中的奇迹》《抵达？》《组装@2961》《永痛之渊》《无边@2974》', rel:['v_pain','v_dongchuang']},
{id:'v_dongchuang', n:'冬创者 · 脑堡', c:'物种', m:'void', sec:11, e:[11], p:[-430,-120,-400], k:'planet', kp:{r:24,tex:'ice',c1:'#d8f0ff',c2:'#6aa8c8',glow:.3},
 s:'住在直径不到一毫米的冰晶洞穴里的小生物；以及把最脆弱的脑放在最外面的“脑堡”。',
 d:'琳管它叫“永冬创造者”：常年困在严寒与痛苦中、死了又活的创造者，于是简称冬创者；既然另有一个“熔创者”，琳猜两者都跟琥珀创造者脱不了关系。它的脑很复杂，能听懂许多创造者的语言，包括“核信息”。冰层里有个十多米宽的“储藏室”，飘满一厘米大小、刻满信息的小石块。皮肤通常是生物的第一道防线，脑堡却反过来：外围是没有记忆、死后被快速替换的脑细胞，内部是透明物质构成的迷宫。冬创者是“小创造者”之一，群星联盟见它们学什么都快，给了它们正式公民的身份和教育；只有它一个进了痛苦之地，同伴们不知去向。',
 ch:'卷六《永冬之中》《冰层的生态》《脑堡》《成长》《复苏》', rel:['v_amber','v_xingmeng']},
{id:'v_xingmeng', n:'群星联盟', c:'文明', m:'void', sec:11, e:[11], p:[0,120,-300], k:'ship', kp:{s:20,n:14,c:'#d8dde8'},
 s:'横跨多个星系、收纳无数种族的庞大帝国，最后被整个“暂停”。',
 d:'群星联盟横跨多个星系，在许多世界上建起数不清的都市，和琳知道的“虚空帝国”颇为相似；里面有个性生物、分工型物种，据说还有超级生物。它自认汇聚了群星间最丰富的文明，设了“银河外交处”之类的机构不断招纳新种族，物种间大小战争时有发生，整体却始终稳固。它有捕猎能在虚空航行的生物来驯服的传统，也很尊敬巴士生物，在领地里修了专门迎接巴士的“巴士码头”；它相信会回答问题的宙脑，虽然每次都要犹豫讨论一阵才下决定。联盟把武器分成“步兵级”“战斗级”等等，最可怕的一种战舰只用过一次，就灭绝了一个星系几乎所有的生物。\n联盟的诞生本身就是一个奇迹：一群为计算战术而造的“终极兵器”被派上战场后拒绝作战，反而算出一套各族都觉得公平、谁也不吃亏的分资源办法，各族就此停战联合，这些兵器从此被称为“调停者”。此后再没有哪个物种背叛过联盟，于是流传起“群星的意识”的说法；一群研究种族历史的专家组成秘密的“不统合会”，怀疑一切过于团结，还建了一座直径三千公里的“贡献乐园”，想让无私的贡献者找回私欲。\n琥珀创造者被困在痛苦之地时，用发信器让联盟上下噩梦不断。宙脑指出了源头，上万艘战舰来到“地狱”入口，带着“空间坍塌弹”——据说能让空间恢复成最原始的状态：传送能量，整个联盟也只有几十枚。痛苦风暴席卷舰队，最高指挥官在临死前引爆了武器，反而把只进不出的通道炸大了，舰队全灭，联盟又组织起几十万艘战舰的大军。此后它平息了自称来自远方的“教徒”——它们问清联盟立场“中立”后当场自尽；收留了诞生的冬创者，给它公民身份；追查混进矿场的寄生体“思维之末”，找到并吸收了琥珀文明；又把被寄生的痛苦巴士带到恒星港，用十公里以上的“裂解岛”一点点清除寄生物，让巴士成了盟友。\n宙脑随后说出真相：收集神器和带回巴士都是为了一个奇迹。空间风暴笼罩了多个星系，联盟把爆弹丢进那颗海洋翻滚者，它却醒了过来，把爆弹扔回，能在几千万公里外拧碎战舰，联盟的大部分领域遭到重创。最后整个联盟被“静止”了——生物们一个个意识缓缓停下，九成以上的领地被吞没；痛苦之地附近幸存的下层种族重建家园没多久就互相打了起来。一些联盟士兵困在虚空缝隙里，后来跟着小宙脑和调停者，用平台里两颗空间坍缩弹中的一颗炸出洞口，回到了群星之下，落在一颗冰雪覆盖、原本是度假胜地的两千公里翻滚者上挖掘物资；洞口打开时涌出的传送能量又让它们痛苦了一阵。调停者总想找一个让所有生物都满意的办法，找不到时就站在联盟这一边。',
 ch:'卷六《传说中的地狱》《接触@2992》《坍塌？》《梦魇的结束》《成长》《琥珀的源头》《群星之间》《完美的结局？》《汇聚@2999》《群星之末》《乐园》《出口？》《成立者》《调停》《离开@3041》《联络@3042》《传递的方式》《战场》', rel:['v_zhounao','v_painland','v_liquid','v_pain','v_dongchuang','v_amber']},
{id:'v_zhounao', n:'宙脑', c:'物种', m:'void', sec:11, e:[11], p:[120,-60,-500], k:'planet', kp:{r:28,tex:'rock',c1:'#7a7068',c2:'#4a443e'},
 s:'追求“奇迹”的生物，像植物般覆盖在翻滚者上；会回答疑问者许多问题。',
 d:'宙脑原本是一颗三千公里左右的翻滚者——准确地说，宙脑是铺满那颗星球表面的一种类似植物的生物，并非星球本身，看上去只是一颗荒芜的岩石翻滚者。它自称“奇迹拯救者”：奇迹生物布下了许多没能实现的奇迹，它要找回那些残留物，比如各种“神器”，再把它们化成新的奇迹；问它为什么，它只说“没有为什么”。它在群星联盟当“预报者”，报告周围的威胁、灾害和资源，从不说假话，联盟的统治者虽然信它，每次仍要犹豫讨论一阵才下决定。它唯一一次坑害联盟，是引着它们收齐所有神器、再带回一头巴士，因为它探索“虚空的界限”时被困过的那颗海洋翻滚者——创造者的“储藏库”——只有这样才能和联盟换位置出来；结果联盟被困，它自己用一种未知的方式逃掉了。\n后来它在另一个文明里做着和从前一样的事。那个文明比群星联盟弱得多，却对它言听计从，靠它对琥珀创造者的全知般的预报打退了第一次进攻；创造者随即倾巢而出把它们击溃，围住宙脑——此时它只能覆盖一颗一百公里的球体了。它告诉创造者储藏库的来历，随后又凭空消失，临走还触发了创造者那件神器的自毁程序；每这样移动一次它就缩小一大截，再被发现时只剩十公里，接着被痛苦巴士带走——它早把创造者的一切都告诉了巴士。\n再后来它主动找上琥珀创造者，说要制造一个“奇迹”：愿意就合作，不愿意就先解决掉对方再做。它的奇迹是把那颗满是和平生物的藤蔓翻滚者送进痛苦之地，至于会出现什么，它没说，只要创造者用裂空团的未成熟体造出一件近一公里见方、只有两米厚的大神器。它本体留在藤蔓翻滚者上，乘一艘五百多米长、像藤蔓扭成的战舰在旁观看；除非会妨碍奇迹，它几乎有问必答，创造者则偷偷研究怎样躲开它的感知。\n小宙脑是因奇迹而从大宙脑分离出来的特殊个体，带领被困在虚空缝隙里的联盟残部，一直全力帮它们出去。它借梦境桥梁从捕获球那里抽取稳定场，士兵们痛苦不堪它却毫发无伤，最后还把大家带到一个它“认识”却没料到的地方；被救回平台的生物大多不再信任它，不让它当领导，它后来陪琳去找调停者。',
 ch:'卷六《传说中的地狱》《坍塌？》《汇聚@2999》《造成》《宙脑》《接触@3004》《交流？@3009》《制造@3010》《炸裂@3011》《发明？》《源头@3031》《聚集点》《虚空之间》《转移@3037》《魂归之地》《寻找@3040》', rel:['v_xingmeng','v_tianlan','v_painland','v_pain','v_liquid','v_dongchuang']},
{id:'v_tianlan', n:'天蓝色世界', c:'地理', m:'void', sec:11, e:[11], p:[300,40,-450], k:'planet', kp:{r:36,tex:'jungle',c1:'#6ab8e8',c2:'#3a7ab8',atm:'#bfe8ff',fluffy:1},
 s:'直径六千多公里，纵横的藤蔓间生活着毛茸茸的天蓝色生物。',
 d:'一颗直径六千多公里的天蓝色世界：地表爬满纵横的藤蔓，藤蔓间生活着无数天蓝色、毛茸茸的小生物——这是宙脑的世界。琥珀创造者用裂空团组装的“神器”开启通道时，它突然出现在琥珀球附近；创造者起初以为神器不靠谱、连错了地方，可神器从来也弄不来这么大的东西，于是派出琥珀物质组成的部队登陆调查。宙脑认为，把这个住满和平生物的世界推进痛苦之地，一定会出现奇迹。后来，琥珀生物的身体大部分被琥珀物质替代，只留下极少的神经——它们原本就来自这里的藤蔓。',
 ch:'卷六《第二次接触》《交流？@3009》《制造@3010》', rel:['v_zhounao','v_amber']},
{id:'v_liquid', n:'虚空的缝隙 · 液体球', c:'地理', m:'void', sec:11, e:[11], p:[220,-60,-60], k:'planet', kp:{r:30,tex:'ocean',c1:'#2a8ab8',c2:'#0a3a5a',blob:1},
 s:'三个虚空之间的缝隙，以及在这里漂浮的“意识的聚集体”。',
 d:'液体球与痛苦巴士碰撞融合后，景色完全变了：珊瑚和植物般的生物丛生在海床上，潜艇在被红色浓雾染成鲜血般的水域中前进。“捕获球”平时像一片正常的海洋，有巴士接近时就分解一切，重新变回液体球去袭击。资料库曾把群星联盟的“空间维持场”转移到自己身上，和联盟对换了位置。',
 ch:'卷六《海洋》《重构的世界》《快速重组》《不正常@3025》《虚空之间》', rel:['v_xingmeng','v_mimic','v_pain']},
{id:'v_mimic', n:'模仿之星 · 疯狂战场', c:'地理', m:'void', sec:11, e:[11], p:[400,-20,-150], k:'planet', kp:{r:26,tex:'jungle',c1:'#5aa85a',c2:'#2a5a2a',spikes:1},
 s:'遍布绿色“模仿者”的世界；这个星系最远的第七颗翻滚者叫疯狂战场。',
 d:'模仿者模仿得很像，又不太像——它提醒大家：别看它们像一群只会过日子的无害机器，其实很阴险。第七颗又冷又黑，却很热闹：战争生物里会出现吃同类尸体、继承记忆的“食尸者”；第六颗的地底遍布一个控制一切“点数”的巨大器官。',
 ch:'卷六《模仿？》《战场》《已经诞生》《点数核心》', rel:['v_liquid']},
{id:'v_seabeast', n:'虚空海兽', c:'物种', m:'void', sec:11, e:[11], p:[520,80,120], k:'swarm', kp:{n:100,s:40,c:'#4a8ab8'},
 s:'数百万只海兽同时朝琳的翻滚者吐出火球。',
 d:'它们从一个连接远处虚空的通道而来，躲在废弃物里伏击。冰川一样排成长队缓缓移动的虚空巴士，在“扔掉”什么。',
 ch:'卷六《出没点》《海兽与巴士》《扔的位置》《同伴@3082》', rel:['v_xingyan']},
{id:'v_xingyan', n:'星焰之民 · 焰星球', c:'文明', m:'void', sec:11, e:[11], p:[300,120,200], k:'star', kp:{r:22,c:'#ff7a3a',n:5},
 s:'穿白金盔甲的高温个性生物，自称恒星居民的正统后代，崇拜巨大的焰星球。',
 d:'星焰之民是高温的个性生物。盔甲里的“身体”和普通火焰差不多热，像熔块，本质上是一团不停剧烈翻动的高温物质，中央有类似反应炉的东西维持体温；高温部分离开护甲就活不下去，所以护甲也算躯体，而且会慢慢长得像它们接触过的个性生物——如今的它们就像一副副中世纪尔什民的铠甲，从白金色的地面隆起成形，关节缝里透出淡金色的光。翻译器译不出它们的话，情绪会从身上的闪光里流露，幼仔用微光“唱歌”。它们是组织“神秘保留”的主体物种，自称是住在恒星里的组织创始者的正统后代，其实从没进过恒星；总觉得自己高人一等，以不插手凡间为由不掺和文明争端，很惹人嫌，却极其公正，容不得任何不公。它们也不爱打仗，遇袭先逃，真打起来，高温的剑能轻易切开敌人。飞行器内外是闪亮的白金地面和飘浮的晶蓝羽毛，它们靠羽毛的抖动“看”外面。\n传说里，曾经的虚空很温暖，后来寒冷蔓延，许多高温生物熄灭，或干脆变成低温生物，只有它们坚持了下来。最早它们和许多“焰星球”一起生活——那是同类“升格”成的巨大光球，保留着升格前的记忆，住一阵就会离开；不知从何时起，再没有谁能升格。远古家乡“星焰堡”外表像一颗空心的恒星，其实是有史以来最大的焰星球；寒冷灾难来时，它第一个把自己转成低温形态，成了“霜堡”，许多追随者跟着效仿，坚持“永焰”的星焰之民便离开了。更早的传说说最初阶段的“永焰”与燃星者是共生同伴：它们把燃星者的黑雾当作居所，一个吃下黑雾颗粒的星焰之民一路变成了永焰。它们那时自称“永焰者”，一心追求极热。焰星球后来发现，光往体内加燃料迟早会熄灭，用“分离焰”造出小焰星球、一代代繁衍才能一直烧下去；讽刺的是，被视为最低级的星焰之民形态反倒最稳定。\n琳遇到的那群星焰之民载上琳和一小团液体，经过满是海兽的通道进入奇迹星系，又被几万个十多米的光球追赶；光球合成一颗直径约三百米的球体，所有星焰之民立刻摆出像尔什民蹲下抱头的崇拜姿势，称它为“群星的神”。它们遵循焰星球的指引，在“白金矿场”采集数十米大的白金石块，花了约一百个绒球昼夜把飞行器扩成三公里长的白金平台，焰星球就待在中央三百多米的大洞里，探出“高温时代”留下的古老通道和远古空间，还带它们绕开叫“魔镜”的透明墙。降落在资料库所在的冰原后，它们砍杀造脑怪模样的滋生者构造体，却被会用针刺吸走高温体液的半球形“交流处”吸干了好几个。随后引擎冻结、飞行器坠进地下深坑，它们从体内一路变冷，焰星球先冻住，融成一片湖。原来这颗焰星球正是复苏的霜堡：它哄这群不知道它背叛往事的星焰之民改装飞行器、带它回到资料库，还在途中“感染”了它们，让下一代幼仔混进“霜寒之民”的记忆，把寒冷的地方当成了家。',
 ch:'卷六《同伴@3082》《前往@3083》《另一个通道》《同类》《救援？》《温暖的过去》《长途旅行》《文明之惧》《着陆》《滋生者？》《撤离？》《冰冻》《底部》《过去的寒冷》《永燃》《精神和身体》《接触@3112》《星焰的相遇》《诞生@3133》', rel:['v_shuangbao','v_ranxing','v_liquid','v_nospace']},
{id:'v_shuangbao', n:'霜堡', c:'地理', m:'void', sec:11, e:[11], p:[100,-140,240], k:'planet', kp:{r:34,tex:'ice',c1:'#f0f8ff',c2:'#a8c8e0',atm:'#e8f8ff'},
 s:'曾经的“星焰堡”，向寒冷屈服的世界。',
 d:'焰星球回来时，天空亮起无数光辉，它们认为霜堡是背叛者。后来“资料库”占据了霜堡，冰晶般的小型机械包围了坠落的飞行器；地下雪原里，雪地造脑怪似的幼仔一路唱着歌：它们要回家，去找那个传说里的家，再危险也不怕。\n霜堡上那些过去时代的“正统生物”天生对远古空间有感应。琳在这里收集资料库散落的脑，收到三成左右时，它躲了起来。',
 ch:'卷六《过去的寒冷》《过程与谜团》《霜堡之旅》《最后的旅行》《精神和身体》', rel:['v_xingyan','v_ranxing']},
{id:'v_ranxing', n:'燃星者', c:'物种', m:'void', sec:11, e:[11], p:[-80,-60,420], k:'star', kp:{r:46,c:'#ff4a1a',flare:1},
 s:'高温时代遗留的巨大高温生物，让寒冷世界崇拜炎热、自焚，最后自己熄灭。',
 d:'燃星者、光耀者、唤醒者、处决者、毁灭者、猎叛者——这些称呼都是别的物种起的，它自己从没说过名字。最古老的传说讲一群痴迷高温、自身却不耐热的生物，造出大量爆炸物和长燃物，最后把整个世界烧掉。它靠近一个够冷的世界，那里有智力的生物就会慢慢崇拜炎热，想尽办法给世界加温，直到自己灭亡；高温世界则像受了滋养般欢迎它。只有当居民察觉异常、取缔崇热的宗教时，它才亲自现身，视之为挑战；若一个世界成立“寒冷教派”，把自己冻成极寒之地，它反而从不去烧。动手之前，会先有一种连细胞生物和巴士生物都能接收的光柱幻象从虚空深处传来。它外面裹着黑雾，被炸开后露出本体：无数粗数十米的鲜红“血管”纠缠而成，周围一层气体能把高速石块磨尽；它身边像一片活动的“无空间带”，会挤开传送能量，没法直接把东西传送到它身上；四周还有近乎重合、极难察觉的“远古空间”。\n高温时代之初，住在恒星里的原初生物像一团团浓雾，生出会变形活动的“火球”，就是最早的高温生物——所以“星焰之民”这个名字其实可以形容所有高温生物。虚空环境一变，它们便一代代造出更能适应的新形态，又崇拜更热的旧形态，少数经过多次变化成了接近原初的“最终形态”。燃星者的种群是上一次“终末”（虚空变冷）中的抗争者，耗尽资源只让最虔诚的一个个体“成神”，那就是从前的燃星者；成了最终形态后它却转而维护终末，四处“纠正”变形求生的高温生物，心里却一直疑惑。另一个最终形态生物把它的意识恢复到“神”的程度，它的性格也从此改变。它还在一颗将熄恒星旁找到遗迹生物的记录，看懂了高温生物的来历。每次终末之后，它带着最终形态的能力从头来过：能感知所有高温生物的思维，低温时却会陷入沉睡。新一轮里，星焰之民把它的黑雾当作居所，它让一个星焰之民吃下黑雾颗粒，一路变成最终形态“永焰”；它与永焰一起在虚空里到处旅行，看了许多奇妙的东西，那大概是它最喜欢的时光。它也在那时第一次碰到顺着远古空间远道而来的“外来者”，金色球体说那可能就是原初奇迹生物，看上去像一整支文明军队。远古空间能让它看到历史，却回不到过去；它曾以为自己让高温生物更加繁盛，如今只能在新的未来里四处寻找、唤醒可能还在沉睡的同类。它经历过好几次终末。\n资料库占据霜堡的躯体研究高温时代，造了能模仿燃星者语言的装置，一测试就招来攻击。霜堡曾跟着它安然穿过无空间带，它后来却用一道光刃把资料库劈成两半，又把霜堡（一群小焰星球）杀光，认为霜堡已被资料库“污染”。随后它逼近尔什，想把那里的生物收作正统的高温生物；它攻击琳的“月”，从体内挤出直径三百米的金色球体，尔什用替身球往它体内灌传送能量，传走的却只是这些金球。尔什锁定核心送去强效冷冻弹，它随即僵住，尔什地表却骤然变热——资料库仿造了永焰的信号发给它，尔什赶紧切断了远古通道。之后它慢慢变冷熄灭，宁可拿虚空里的物质修补，也不肯像霜堡那样改成低温形态。熄灭后，体内留下一个直径只有三百米、可以伸进无空间带的远古空间，只对琳的月之碎片发出从没收到过、却一读就懂的信号。琳和尔什用它的残骸和控制远古空间的器官造出了“小尔什”。',
 ch:'卷六《燃星》《抵抗》《最后的旅行》《接触@3112》《小小的战斗》《碎片@3116》《变化@3117》《远古的空间》《想法@3123》《影响》《维护者》《过往@3127》《遗迹》《进化与退化》《星焰的相遇》《观察过去》《诞生@3133》《未来@3137》《结束@3140》《接近@3141》《远处@3186》', rel:['v_xingyan','v_shuangbao','v_xiaoerxi','v_nospace','v_liquid','v_erxi']},
{id:'v_nospace', n:'无空间带 · 文明之惧', c:'地理', m:'void', sec:11, e:[11], p:[560,-100,360], k:'fog', kp:{r:120,n:40,c:'#2a2430'},
 s:'过去文明密集的时代，充斥着向往又恐惧星空的文明。',
 d:'“文明之惧”生物在这里不停吞噬、摧毁舰船。“荒魇”会把战场残骸记录下来，飞到另一个地方造出一模一样的战场废墟当陷阱。也有文明发展到巅峰：像一团燃烧的金色火焰、其实是低温固体的“燃金”，造出了“无边之垒”。白树长着坚固的树皮和内部的金属结构，长大后会脱离地表飘进虚空。',
 ch:'卷六《废墟@3166》《树木中》《阻止@3169》《开启@3170》', rel:['v_ranxing','v_baishu']},
{id:'v_baishu', n:'白树', c:'物种', m:'void', sec:11, e:[11], p:[640,0,430], k:'tree', kp:{s:24,c:'#f0ece0',c2:'#e8e4d8'},
 s:'它们发誓一代一代守在这里，直到最后。',
 d:'最初在“陆地”上像普通树木一样靠根系吸收养分，同时在体内储藏大量矿物；长到一定程度后脱离地表，飘到虚空中，发生很大的变化。',
 ch:'卷六《抵达》《树木中》《梦境的时间》', rel:['v_nospace']},
{id:'v_xiaoerxi', n:'小尔什', c:'琳的造物', m:'void', sec:11, e:[11], p:[-360,100,380], k:'planet', kp:{r:30,tex:'earth',c1:'#4a8a4a',c2:'#2a5a8a',atm:'#9ad0ff'},
 s:'用燃星者的残骸造出的一颗“尔什”，花了差不多一个绒球年。',
 d:'一切都要求“完美”，外表和内在都与真实的尔什接近，里面有不会活动的仿巴士内脏。它在远古空间里逆流航行了两个多绒球年，遇到喜欢谈论天气的古代生物“未蛸”、感染空间站的肉块，以及三颗陆块一模一样、环境却完全不同的“尔什”。',
 ch:'卷六《远处@3186》《天气……很好》《家园？》《三颗世界》', rel:['v_ranxing','v_qijizhidu','ex_planet']},
{id:'v_qijizhidu', n:'奇迹之都', c:'文明', m:'void', sec:11, e:[11], p:[-520,40,250], k:'city', kp:{s:24,c:'#d8c8a8',float:1},
 s:'在虚空中漂泊的建筑群，遇到谁就变成谁的建筑样式。',
 d:'它是奇迹生物的交流点之一。招呼来客的说法是：这里什么都可能有，连虚空的真理、一切的最终答案也说不定。猿类发现了它的作用；后来它在琳眼前迅速崩溃，碎成粉末。黑白色、由数十米片状物组成的“修理者”一直在清理奇迹。',
 ch:'卷六《回忆与奇迹》《普通的奇迹》《现象》《扭曲与奇迹》《修理者》', rel:['v_xiaoerxi','v_xiuli']},
{id:'v_xiuli', n:'修理者 · 黑白片', c:'物种', m:'void', sec:11, e:[11], p:[-620,-80,400], k:'crystal', kp:{s:16,c:'#e8e8e8',c2:'#141414',flakes:1},
 s:'一堆数十米大的黑白片状物组合成的生物。',
 d:'金色球体告诉琳：“这个生物有点可疑。”据修理者自己说，尔什和巴士们曾试图造出些什么，创造之海又试图扭曲它们的造物，这些能量在奇迹的作用下混在一起，再掺进空间里找到的部件，才成了它。琳见到的好几处远古空间，都是它修补出来的——只要开始修，那些空间就会自己慢慢长大。后来它在远古空间里读到了自己的来历，觉得自己已经成功了，不再去干扰奇迹生物的复苏，只想继续在虚空中游荡。\n在读到真相之前，它听来过两个答案：一个说它是原初奇迹生物散落在两个虚空夹缝里的器官，另一个说它是原初高温生物复苏计划的产物、被奇迹打乱了——后一个信号可能来自创造之海。它宁愿相信自己是精心设计出来的，一直清理大的奇迹，想把原初奇迹生物变成“最后遗物”，还偷偷学着控制远古空间。',
 ch:'卷六《修理者》《可疑？》《清理》《停止@3241》', rel:['v_qijizhidu']},
{id:'v_haishen', n:'海参 · 秩序之域', c:'地理', m:'void', sec:11, e:[11], p:[0,0,560], k:'whale', kp:{s:80,c:'#18181a',seacuc:1},
 s:'巨大的海参状生物，体内是被“扭曲”完全控制的秩序之域。',
 d:'秩序之域分成许多层：第99层是“众神的厅堂”——白银地面、金色光辉、上百米的石柱，原本放置虚空中各种“超级生物”的强大意识；更深处是“遗忘之席”，太久没出现的生物，影子就被放到那里。还有“漏洞之地”、血色的隐藏层、修正液的海洋。防御者负责清除漏洞生物和逃离者；金属尔什民一层层占领了所有地方。\n尔什后来想起，秩序之域本来就是它早年计划里旅行空间的目的地。金属尔什民堆起没死透的尸体，引出一个蛋形防御者，它的内部系统被感染、造满了金属尔什民，于是呆立不动；它来的隐藏层地面和天空都是血红的，耸着百米高的柱子，材料像海参的外壳。',
 ch:'卷六《秩序区域》《逃离者》《众神？》《侵略@3270》《侵蚀》《侵入@3274》《修正的进攻》《新的材料》', rel:['v_chuangzao','v_wanliu']},
{id:'v_wanliu', n:'万流之台', c:'地理', m:'void', sec:11, e:[11], p:[260,-120,600], k:'disc', kp:{r:50,c:'#d8dde2',c2:'#9aa0a8'},
 s:'许多扭曲点产生的“暖流”汇聚成的平台，直径一百多公里。',
 d:'虚空中一块银色的平台，直径一百多公里，厚度只有几百米，表面布满裂痕和坑洞，由许多扭曲点产生的“暖流”汇聚而成。上面长着几万个十米高、像藤壶一样的“思维”，它们互相制造武器厮杀，几乎全死光了；最后的胜者被自己造得太聪明的造物杀死。只剩边缘一个长得像蘑菇的，靠不停把自己伪装成别的东西活了下来。曾有一个程度很高的文明探索过整个虚空暖流，把这里称为“废弃物终点站”。',
 ch:'卷六《留下》《感知》', rel:['v_haishen']},
{id:'v_jibian', n:'畸变之星', c:'地理', m:'void', sec:11, e:[11], p:[-700,20,-60], k:'planet', kp:{r:30,tex:'flesh',c1:'#b86a5a',c2:'#5a2a26'},
 s:'像把无数细胞生物捏成一个巨大肉球的世界——为对抗“扭曲”而造的东西。',
 d:'它的平原像呼吸一样起伏，地表长出无数大小不一的“肢体”。共生体曾在这颗古怪的星上四处游荡，想找回记忆中那个美妙的世界，却发现自己软泥般的身体也染上了这种畸变，长出各种奇形怪状的肢体。“扭曲”能让一切事物按同一套数据被“共同化”，而它的数据全都基于细胞生物的核信息；有一个生物专门研究怎样对抗扭曲，畸变之星就是它最终的成果——它能把已经被扭曲过的东西再扭曲一次，而且永远无法复原。它不是凭空造出来的，而是照着制造共生体的那颗“小巴士”改造的。共生体在塔前感知到留下的念头：“畸变之星……很成功”“就让这份异变永远蔓延下去”。后来琳看到的古老记忆里，三颗巴士——其中一颗就是尔什——聚在一起讨论的，也正是这颗星，它似乎也和创造者有关。',
 ch:'卷六《记录@3152》《拯救的想法》《当扭曲被扭曲》《收集@3156》', rel:['v_chuangzao','v_erxi']},
{id:'v_chuangzao', n:'创造之海', c:'地理', m:'void', sec:11, e:[6,11,12,13], p:[440,60,620], k:'planet', kp:{r:44,tex:'ocean',c1:'#3ac8d8',c2:'#0a6a8a',atm:'#bff8ff',glow:.4},
 s:'传说所有创造者都是从这里来的，地表几乎全是海。',
 d:'传说所有创造者都是从这里来的，这颗翻滚者的地表几乎全是海。创造者专门猎食翻滚者那么大的巨型生物，不断创造、再吞噬庞大的生态，来扩充自己的细胞信息库；它们造出数不清的物种，总有些活下来、旅行到各处，所以无愧“创造者”之名——它们最想要的是一个完美的生态、完美的世界，不在乎它在真实还是梦境里。脑灵照老样子靠近这颗翻滚者，结果整支部队一下子就被毁掉了，上面的创造者都十分强大；某处的创造者变少时，别处的创造者通常搭着恒星巴士赶过去，偶尔来的却是创造之海本身。卷六里脑灵的“计划之中的计划”，就是在绒球上灭绝一切后，借脑袋虫这类“创造之源”发出信号，把创造之海引来给琳当对手；教长想反过来利用这段信息，玛雅则把它改成了只有琳读得懂。以尔什为主的生物曾用武器把它推进了某个地方；它收集了虚空中几乎一切的数据——那些数据也可以说就是它的意识。\n碰撞之后，闯进虚空的吞噬之域追的正是创造之海的意识；从吞噬之域看去，创造之海仍像海流一样涌向不可预见之地的深处，它的思维像一团云雾，覆盖的范围至少有尔什星系那么大。\n卷八，琳在虚空的阴暗面一块轮回战场的陆块里，找到一团一米多、像水的能量：碰不到，却测得出来，和创造之海的数据流非常像，像是创造之海的一小块。它一直让两群细胞生物互相杀死、重组、再杀死。\n卷八里，创造之海穿过不可预见之地，经过了它和虚空之眼之间的连接点，认定那里是“最后一个虚空”：它想把漫长岁月里从创造者那里收集的细胞核信息撒进每一个虚空，让所有虚空连成一体。它在虚空之眼的虚空里种下一颗白膏世界，派出会说话的白膏和上万艘白色战舰。诺担心这些被打乱的数据会写进所有生物的设计图，引发虚空级的大灭绝，于是琳把它骗进了虚空之眼的核心。它明明可以切断传输却没有，也许它也想看看会发生什么。新虚空打开后，它用新造的战舰送去了一批创造者。',
 ch:'卷六《虚空之中》《计划之中的计划》《完全的计划》《制造@3178》《新旅行目标》《隐藏的入口》卷七《武器》《消失@259》卷八《追寻》《流动@13》卷八《内部》卷八《剧烈的变化》《虚空的粉末》《转移》《开始》《传输》《最后的瞬间》', rel:['creator','v_haishen','dr_bridge','j1_tunshi','j2_lunhui','j3_baigaoworld','j3_zhihui','j3_eyevoid','j3_end']},

/* ---------- 星区 12 ---------- */
{id:'v_benglie', n:'崩裂虚空 · 重合者', c:'地理', m:'void', sec:12, e:[12], p:[0,0,0], k:'rocks', kp:{r:260,n:200,s:12,c:'#6a6070',shards:1},
 s:'从边缘开始碎裂的古老虚空，重合者就来自这里，想把碎块重新拼合。',
 d:'崩裂虚空本身是一个巨大而古老的虚空，很久以前就从边缘开始碎裂，碎成大大小小的空间飘散出去，大量融进正常虚空，让那里原本就有的单独小空间多了许多。崩裂之中留着不少正常虚空里古老文明的遗迹，大都早于虚空隧道，琳认得其中许多——它们就像照着正常虚空的废墟复制出来的一般。莎琳的分身曾在这一带游历，指引过许多走向末日的文明，却一个也没救下来，这与崩裂虚空有关；分身还把莎琳称作“拟空间生物”的有思维的空间当作生物看待，它们也许随崩裂一起出现。在崩裂虚空里有一处被莎琳叫作“碎裂之眼”的地方，能确认虚空隧道那些碎片空间的所在。琳和莎琳从尔什那里得知了入口后，便前往这里调查。\n“在不知不觉中，世界已经分崩离析了。”重合者是来自这里的漂流群体，这个名字是莎琳的分身起的——它发现一个意识在空间碰撞后像变成了另一个物种，思维波动和尔什几乎相同。重合者的使命是把碎裂的空间重新合拢：先调查每个碎块的数据，整合成混合的空间环境，测试之后再动手拼回。它们的样子是一堆十多厘米的球聚成的、几米大的团块：每在自己模拟的空间里过完一段生活，就把这段历程存进一颗球，球越多表示体验越多，其中一颗“核心球”是它的思维所在。在一处遗迹里，直径三百米、反射星光的黑色圆盘平台上飘满了它们的幻象。\n小管道被重合者叫作“经历掠夺者”，一直袭击它们，靠一种类似微型机械的东西迅速修复伤势；重合者找到了让这些机械故障的方法，还在一个小管道身上发现了自己的历史——它用不同时期重合者的记忆造出许多生物，按时期分区居住。一个遥远的拟空间生物干扰了它们的体验，让它们陷入“体验中的体验”，自己也遭到小管道入侵。重合者造出“空间末日装置”，要炸掉存放小管道的建筑和整个空间。调查米德加尔特死因的“调查员”来到崩裂虚空——那是米德加尔特自杀死去的地方——一度协助重合者，查完便不辞而别，重合者却暗中摸清了它们的路线。原来小管道、重合者和米德加尔特身上的生物都被设定了命运，作用就是让它复苏，它想借此融入崩裂虚空。漫长的战争以重合者攻进“记录空间”、要炸毁它的最后决战收场，重合者最终灭亡，又以小管道的形式活了下来：调查员把剩下的重合者关起来做成历史幻象，而一个保有重合者思维的小管道带上一群继承了重合者记忆的幼仔回到正常虚空，找到了重合者很久以前留下的遗迹。后来，琳带着的重合者幻象被一颗地壳只有几公里厚的空心翻滚者吸引，痛苦地飘向深处——那颗翻滚者从诞生起就能吞噬幻象生物，调查员最终也把自己化作了类似雕塑的东西。',
 ch:'卷七《恢复@201》《缓慢的崩裂》《计划@205》《调查@208》《幻影》《重合》《计划@216》《遗迹》《小管道》《了解@220》《远古》《被记录的意识》《内部@225》《留下的碎块》《袭击@229》《毁灭》《命运@231》《最后的飘荡》《记录和寄托》《幻象》《吸引》《出口》', rel:['v_xiaoguan','v_huanxiang','c_sarin','v_midgard','tn_overview','yongheng']},
{id:'v_xiaoguan', n:'小管道 · 经历掠夺者', c:'物种', m:'void', sec:12, e:[12], p:[140,60,100], k:'tube', kp:{len:90,r:8,c:'#6a5a5a'},
 s:'长得像缩小版米德加尔特、夺取别人“经历”的管道生物；幼仔也有数十米。',
 d:'小管道和米德加尔特长得一模一样，只是小得多，也有几百公里长。重合者是一群离开原本空间、在虚空中漂流的生物，它们身上每一颗球都是一段经历，而这种管道一直在袭击它们，所以被叫作“经历掠夺者”。小管道能在身边造出一种只吸引这些球的引力，球碰到它体表就炸开，其实是被它读取；随后它身上那些像建筑的结构里会冒出一个带着这段记忆的生物，身体却配合建筑的样子，往往一醒来就不知道自己为什么变成这样，大多很快死去。这些居民最长能活一千个绒球年左右，会挖它身上的特殊材料“发明”出各种装置，而小管道会把造好的东西直接“拿走”——飞行器一启动就消失——它所有的强大能力其实都来自居民的发明，快速恢复的能力则来自身上类似微型机械的东西。\n幼仔一般几十米大，也照着各种故事记载在身上造出几厘米的小居民，但它们不会长大。重合者养着幼仔研究，找到阻断小管道控制信号的办法，杀了许多；又从幸存居民那里找到它的“脑部”，得知它来自凝固虚空。它们还发现自己种族的历史就在一个小管道身上——上面住满了生物，各自继承着重合者某个年代的记忆，彼此合作建起了城市。重合者靠这些记忆恢复技术，击碎了那个小管道，随后找到一个存着它们历代造物的空间，里面的建筑堆满了快要苏醒的幼仔，它们的思维在高温的清醒和低温的休眠之间不停轮替。重合者没有立刻炸掉它们，最后一场战争便由这些幼仔大小、身上长满重合者技术造物的小管道发动，它们用各个空间的资源直接组装同伴，目标是消灭整个重合者种族。\n调查员认为，小管道是自杀的米德加尔特留下的“碎片”，继承了它的一些习性，诞生在那个记录空间里，原本的使命是让米德加尔特复苏；对付它们最好的办法是让它们失去兴趣。重合者抢来调查员仿造的小管道混进群体，最后决定把所在的几十个空间全部炸毁。爆炸后活下来的小管道思维变成空白，只在空间里漂着——它们天生没有思维，要读取某种生物的思维当作底子，最早的那一批来自米德加尔特身上的居民。最后一群重合者漂到一个几百米大的小管道上活了下来，它们的想法如水流般涌进它的中心，重合者就这样以小管道的形式延续下去。这个小管道看着调查员修复各个空间、留下幻象，学会了和过去交流，最后带着一群有重合者记忆的幼仔回到正常虚空，把它们留在一处远古遗迹里——琳的绒球所在的那块圆盘形遗迹上裂开一道近百米的门，里面正是一个几十米大、像迷你模型的小管道。',
 ch:'卷七《遗迹》《小管道》《捕获》《了解@220》《远古》《搜索@224》《内部@225》《熟悉之物》《探究》《袭击@229》《毁灭》《命运@231》《最后的飘荡》《记录和寄托》《幻象》', rel:['v_benglie','v_midgard','mg_overview','v_huanxiang','ng_overview']},
{id:'v_huanxiang', n:'幻象世界', c:'地理', m:'void', sec:12, e:[12], p:[-300,40,-150], k:'planet', kp:{r:40,tex:'dark',c1:'#3a2a5a',c2:'#8a6ab8',hollow:1,glow:.4},
 s:'换了一种样子的米德加尔特虚空：一切飘忽不定，各种时代混合在一起。',
 d:'莎琳的分身当年从虚空的裂痕进出“真实世界”和“幻象世界”，有一次深入太久，回来时入口消失了，它在那里看到了自己。“吞噬幻象的翻滚者”地壳只有几公里，内部是巨大的空心；多余的幻象生物被聚集到这里慢慢处理掉，调查员沉睡在薄薄的地层里。',
 ch:'卷七《连接的时代》《形成》《真实的幻象》《出口》《调查员？》《入侵@249》', rel:['v_benglie','c_sarin','yongheng','v_paixing']},
{id:'v_paixing', n:'拍星器 · 护门者', c:'物种', m:'void', sec:12, e:[12], p:[300,-60,-300], k:'star', kp:{r:60,c:'#f8f8ff'},
 s:'一颗白色恒星。地表上有用四肢走路、专门“拍恒星”的车形生物。',
 d:'恒星偶尔会“爆闪”，拍星器就拍下那一刻。护门者负责堵住一处会毁掉整颗翻滚者的“虚空泄露”；守得太久，不少个体觉得泄露只是传说，分裂出去组成了部落，只有一群一直坚持着。很久以前米德加尔特飞进过这颗恒星。\n莎琳认为，这台像望远镜一样的拍星器真正的用处也许是把米德加尔特的意识搬走。后来护门者被一群微型的异界生物取代——它们越生越多，把石块当成翻滚者过起异界的日子。琳在石块间找到莎琳的一只手和许多几厘米的碎块，拼出一个缺了心口、动不了的身体；那些异界生物却被一股藏在附近恒星里的力量操纵着，飞来想把它拆开。',
 ch:'卷七《微型的世界》《组装》《拍摄》《拍摄阻止》《侵蚀？》《入侵@249》', rel:['v_xinhao','c_sarin','v_huanxiang','yongheng']},
{id:'v_xinhao', n:'信号幽灵', c:'物种', m:'void', sec:12, e:[12], p:[380,80,-120], k:'jelly', kp:{s:16,n:7,c:'#cfe8ff'},
 s:'在信号中诞生、像半透明水母的生物，几十米大。',
 d:'附近有很多早已灭亡的文明废墟，它们来自不同文明，但发出的信号混在一起，生出了这种幽灵。据莎琳说，是一种挺有趣的生物。',
 ch:'卷七《信号》《减速》', rel:['v_paixing','c_sarin']},
{id:'v_pantian', n:'攀天城', c:'物种', m:'void', sec:12, e:[12], p:[540,0,-440], k:'blob', kp:{s:30,c:'#b8bcc4',metal:1,tentacles:1},
 s:'巨大的触手团，内部是大量更小的触手。',
 d:'一团巨大的触手，叫‘攀天城’。它把‘车轮’救走之后，琳原本以为它还会再对莎琳出手，它却没有，而是一路飞离恒星，往深空去。琳一边跟着，一边试着钻进它里面：触手内部是更多更小的触手，组成类似肌肉的结构，撑着外面的大触手转动。十多亿公里外，十个银色的圆环叠在一起，构成一件武器。\n它其实是“亡螺”们自己的居所。',
 ch:'卷七《逃》《储藏》《武器》', rel:['v_rings']},
{id:'v_rings', n:'十个银色圆环', c:'现象', m:'void', sec:12, e:[12], p:[160,-120,-540], k:'ring', kp:{r:40,n:10,c:'#d8dde2',stack:1},
 s:'停在离恒星十几亿公里远处、一动不动的巨大物体。',
 d:'“准备好了。”离恒星十多亿公里处，十个叠在一起的银色圆环慢慢展开，把中心对准了恒星。这件武器叫“星熄”，能让恒星在很短的时间里消失——恒星里的小空间也会跟着消失，等于彻底关掉米德加尔特留在这里的系统。米德加尔特留给“亡螺”们的库存差不多都用光了，这是剩下的最后一件武器；要是它也没用，它们就打算搭着攀天城离开，放弃米德加尔特交给它们的任务。恒星后来真的消失了，莎琳却认为这正是米德加尔特计划的最后一步：她所在的小空间随之进到了米德虚空二。',
 ch:'卷七《储藏》《武器》《消失@259》', rel:['v_pantian','ng_mixu','c_sarin']},
{id:'v_hunhe', n:'混合虚空 · 安全区', c:'地理', m:'void', sec:12, e:[12], p:[-500,-60,200], k:'vortex', kp:{r:120,c:'#ffe8a0',light:1},
 s:'一个上百万公里、闪耀着强光缓缓旋转的漩涡。',
 d:'尔什曾为脆弱的生物造过一个“安全区”，大概有十光年以上；“异生者”向它所有的领地发射雾球，被击中的区域长出越来越大的土丘般的怪东西，安全区文明就此灭亡。尔什想起来，当年造这个混合虚空，其实是想造一个“旅行空间”。',
 ch:'卷七《混合物》《安全》《安全区的最后》《困住》《过去的旅行》', rel:['ex_planet','v_yingzhe']},
{id:'v_yingzhe', n:'影遮', c:'物种', m:'void', sec:12, e:[12], p:[-620,60,-60], k:'shadow', kp:{s:40},
 s:'一种“活动的环境”。它攻击时，周围的一切感知都被遮蔽。',
 d:'一种“活动的环境”：外壳像一层气泡，把内部和外面隔开；它发动攻击时，周围的一切感知都会被遮蔽。里面没有寻常的生物结构，而是一片会变化的区域，像慢得多的混沌区域——几千秒才换一次景色：有时是飘满方块的一片白，方块摸得到，下次一变就瞬间消失；有时什么也没有。这里住着“影民”，有像尔什民的、像动物的、像植物的，都被黑色火焰般的东西完全包裹；影民恢复后会变回原本的“寄舰”。尔什也来过这里。',
 ch:'卷七《影内》《攻击@278》《回忆物》《变化@280》《移动》', rel:['v_dingzhi']},
{id:'v_hundun', n:'混沌空间 · 汇聚点', c:'地理', m:'void', sec:12, e:[12], p:[-760,40,-380], k:'none',
 s:'虚空与虚空之间“无”里的东西，最后都漂到这里，化成混沌。',
 d:'虚空和虚空之间有一片叫“无”的区域，偶尔有东西闯进去，却很少能久留——它们会朝同一个方向汇聚，漫长岁月里聚成的就是这个空间。不管原本是什么，到了这里都被转成无数闪烁的混沌；它大得连定制之环都怕在里面迷路。混沌里有些“气泡区域”，常能看到漂进来的普通虚空物质，“混沌神经”所在的气泡就是一个入口。凝结文明从混沌里捞取信息，却不能亲身进去：涌进来的信息太多，会把它们撑爆。尔什测试过，混沌很难带到别的虚空，除非那个虚空小到能被它很快淹没——这样整个混掉的小空间，会一点点漂近，最终与这里合成一片；米德虚空太大，没有被彻底吞掉。两者相撞之后，这里一下子安静下来，变成一点闪光都没有的漆黑，连混沌生物都停了；残骸随后自己拼装起来，像原本就是一整件东西的零件。',
 ch:'卷七《用途@268》《移动》《汇聚点》《环中生物》《构造》《想象》《显示》《互换？》《最后的区域》《实验》《遗失》', rel:['v_dingzhi','v_yingzhe','ng_mixu']},
{id:'v_dingzhi', n:'定制之环 · 凝结文明', c:'文明', m:'void', sec:12, e:[12], p:[-420,120,-320], k:'ring', kp:{r:20,n:3,c:'#e8c25a'},
 s:'像金色圆环一样的舰长，与它们早已离开的凝结文明。',
 d:'凝结文明从混沌中捕获信息，发明了“定制之环”去获取想要的内容，比如一种能量和另一种接触会发生什么。它们离开后，许多定制之环还在履行使命。废墟里最常见的是结晶构成的树枝。凝结生物曾在尔什地表放下“陆地裂解器”，遭到干瘪的“荒民”猛烈反击。',
 ch:'卷七《汇聚点》《环中生物》《废墟》《识别》《疑惑》《完美的》', rel:['v_kuxing','v_yingzhe']},
{id:'v_kuxing', n:'枯星', c:'地理', m:'void', sec:12, e:[12], p:[-300,-120,-420], k:'planet', kp:{r:36,tex:'sand',c1:'#c8a87a',c2:'#8a6a4a'},
 s:'一颗没有水分的“尔什”，地表是干枯的裂谷与山峰。',
 d:'定制之环的驱逐光束落在上面毫无效果。地下的水池里慢慢长出藤蔓一样的东西——它干枯的原因就在这里。它可以用思维驾驶。混沌战舰里，一颗新构成的“尔什”迅速发展，尔什民们在问：要继续生活在痛苦的现实，还是在虚拟世界获得永恒的快乐？',
 ch:'卷七《干枯》《枯星深处》《移动方式》《构造的新世界》《享乐》', rel:['v_dingzhi','ex_planet']},
{id:'v_renzhi', n:'认知末日 · 万变之颅', c:'现象', m:'void', sec:12, e:[12], p:[300,100,250], k:'skull', kp:{s:40,c:'#d8d0c0'},
 s:'如果智慧生物一直认知、思考正常虚空，“末日”就会接近，让一切归于寂静。',
 d:'相信认知末日的文明决定让所有文明远离对现实的认知。认知者的世界里，所有生物认知到的都是同一个世界。万变之颅从外面看是巨大的尔什民头骨——每个生物看到的样子都不一样，尔什民看到的是自己的头骨。“事件卡片”记录灾难发生的瞬间；它们认为莎琳会把认知末日传到虚空各处。',
 ch:'卷七《生活》《认知的另一边》《聚集点》《卡片》《追寻之末》《转换》', rel:['v_zhuixun','c_sarin']},
{id:'v_zhuixun', n:'追寻之月', c:'地理', m:'void', sec:12, e:[12], p:[420,160,180], k:'planet', kp:{r:20,tex:'rock',c1:'#c8c8c0',c2:'#8a8a84'},
 s:'不可预见之地里生成的、模仿正常虚空翻滚者的“翻滚者”。',
 d:'它长得像尔什的卫星，大小也接近，所以莎琳叫它‘月’。莎琳很早以前在不可预见之地碰见过它，出于好奇还在上面研究了一阵。后来莎琳飞到一些卡片面前，只隔几米，卡片告诉它其中的关系：造卡片的文明受了追寻之月的影响，把自己封闭起来，靠自己造的维生设备和虚拟现实，把追寻之月的样子仿了出来，让整个文明住在里面。',
 ch:'卷七《追寻》《认知结果》', rel:['v_renzhi','c_sarin']},
{id:'v_keli', n:'颗粒生物', c:'物种', m:'void', sec:12, e:[12], p:[80,-140,380], k:'swarm', kp:{n:300,s:40,c:'#c8c8d8'},
 s:'由彼此隔开的白色颗粒构成的古老观察者，在“认知末日”里看着静止扩散。',
 d:'它由许多几厘米大的白色颗粒组成，颗粒彼此隔着一厘米多，并不粘连；琳遇到的那一个三米多高，样子像尔什民，不出声，直接把意思送到对方心里。万变之颅吞下一群乘石块袭来的这类颗粒生物，触发传送，把琳带到一颗地表铺满平整建筑的翻滚者上——那些建筑其实全是陷入永久“享乐”、再也不会醒的生物。它刚从裂缝里爬出来说了句“停止了……活动”，身体就散了，意识的信号却越来越强。它的文明去过许多翻滚者，只见过废墟和封闭思维享乐的文明；后来它们的殖民地接连忽然“停止”：建筑完好，居民完好，就像突然停住了一样。它加入自称幸存者的组织继续远行，可走得够远遇到的文明，接触不久也会毁灭；许多幸存者最后像疯了似的认定自己是被寂静选中的“灭亡先锋”，数千亿大军分乘数万艘飞行器去传播灭亡，遭恒星管道屠灭，它却活了下来，落进“认知末日”的空间。\n它在那里亲眼看着“寂静的末日”扩散：凝固虚空很久以前并不凝固，生活方式与正常虚空相似，恒星管道停摆后，万物都慢慢静止。它看到能在静止中活动的“活动之物”，看到靠“永动之光”活下来的远古生物；它被荒涡奉为神明，引它们去探巨洞，发现那是想收尽“永久活动之物”、再把一切彻底静止的“静止之源”，又带领它们对抗；它扶持一身都在活动的永动生物，却看着沉睡像疾病一样扩散。最终静止之源放弃了，恒星管道认为是它锲而不舍的抵抗“感动”了对方。此后它只能观察正常虚空里管道周围的情况，见证了收藏家、诸界之末、拒绝者等管道的一生，其中两个死时来到认知末日碎裂。它的“观测室”深处有一处管道记录区，飘着这些管道数百米大的半透明微缩影像。它派出去的探索队学会了静止技术，用凝固物质造出静止发生器，回来时已不认得它，在认知末日里大用静止武器，后来变成崇拜静止之源的组织，躲在两个虚空之间的缝隙里等待出击。它对抗静止很久很久，最后还是没能阻止，晚年的记忆也变得模糊零碎。',
 ch:'卷七《寂灭》《转变》《蔓延》《静止的原初》《早期的改变》《汇聚》《深入》《尝试》《对抗静止》《时间》《生命的出路》《平静》《碎裂@363》《管道》《变异》《探索的回归》《最后@373》《管道记录》', rel:['v_renzhi','v_huangwo','v_shiwu','v_piaobo']},
{id:'v_shiwu', n:'噬物之星', c:'物种', m:'void', sec:12, e:[12], p:[-80,-60,540], k:'planet', kp:{r:34,tex:'flesh',c1:'#6a4a4a',c2:'#3a2a2a'},
 s:'碎裂的翻滚者陆块铺满尸骸，又重新连在一起，成了一个巨型生物。',
 d:'碎裂的翻滚者陆块铺满尸骸，又重新连在一起，成了一个巨型生物，文明生物叫它“噬物之星”。静止的世界里组装东西很容易：把各种内脏、躯壳和材料拼在一起。文明生物太过寂寞，对着一动不动的躯壳讲述它们的历史，躯壳便开始活动。它渴望生长，变得更大，用猎物的材料造出“永动之光”射向远处，第二次瞄得准多了。荒涡把它拆开，放进城市的生态园，可它没有死：丢些资源在它表面，它就长出颜色丰富、形态各异、像花一样的结构，荒涡慢慢从研究它怎么长，变成研究怎么让它长得好看。',
 ch:'卷七《生长》《学习》《活动@346》《完全生长》《行为》', rel:['v_keli','v_huangwo']},
{id:'v_huangwo', n:'荒涡 · 静止之源', c:'文明', m:'void', sec:12, e:[12], p:[260,-40,580], k:'disc', kp:{r:90,c:'#5a5048',c2:'#0a0a0a',hole:1},
 s:'围着一个直径六千多公里、厚只有数百米的巨大洞口建起的文明；洞口后来叫“静止之源”。',
 d:'“荒涡”是颗粒生物给它们起的名字。它们的文明围着一个巨大的洞口而建：洞口直径六千多公里，厚度却只有几百米，从正面看是一个漆黑的大洞，边缘绕着一圈像岩石的环。洞口周围漂着数万座城市，每座几公里到几十公里，都罩在半球形的巨壳里，只留些小口供飞行器进出，壳上和周围布满炮台，远看更像一件件战争兵器。洞口不时会像漩涡般转起来，持续一千秒，喷出无数几十到几百米的碎块；城市只击碎朝自己撞来的那些，平静后再派飞行器把碎块拖回去——文明的繁荣全靠这股资源，所以荒涡多半是从别处漂来的。它们几乎全靠视觉，极爱装监控；繁殖时要几十个个体关进房间，进入梦游般的状态，出来时就多了几个，这个过程从不让任何清醒的荒涡观看，据说一看就不会有新个体。它们把洞口叫“轮回之地”，把尸体和废弃物扔进去，相信这些东西会转化后再“爆发”回来，久而久之成了崇拜；偶尔有发疯的驾驶员说洞里有东西在跟它说话，飞进去就再也没出来。\n荒涡登上过漂流的噬物之星，用几百艘飞行器拴上链锁把它拖回城市，养在“生态园”里研究，还把它的碎块送到各城展览；后来这些碎块劫持飞行器，荒涡拷问文明生物才知道它的真面目，而噬物之星最后的残躯飘进了洞口。文明生物用排泄物写下末日预言，预言随即应验：静止降临，武器无法启动，喷出的巨块砸碎城市外壳，幸存者为抢食互相残杀，剩下的少到无法繁殖；远征队在泥球生态区看到尸体结成“地毯”、躯壳四处游荡，新的噬物之星正在崛起。颗粒生物把这场灾难看作这片虚空走向“凝固”的灭绝事件。\n颗粒生物借思维连接成了荒涡的“神明”，一步步诱它们驶进洞口。里面漂满尸体和古代文明的废墟，还有用废弃物聚成的巨型“器官”，以及一颗直径三万多公里的蓝色翻滚者——“静止核心”。颗粒生物告诉它们洞里多是不会静止的“永远活动之物”，提出疑问的荒涡被当作精神失常“排除”掉。洞口从此改名“静止之源”：荒涡把城市设施换成永久活动之物，往洞里发射导弹；颗粒生物把唱反调的荒涡编进侦察队送进去，结果全军覆没，洞里随即飞出一座座用旧废墟改成、几公里大的要塞。荒涡拼命轰击洞口实体的边框，终于有一道裂痕扩散开——原来是远古文明埋在边框里的“活动震荡装置”被引爆了——洞口闭合，刚探出半截的要塞被切成两半。可十一座城市挡不住十八座要塞，又一座城市被打垮；静止核心随后从漩涡里挤出来，把边框彻底撑碎，荒涡的士气当场崩溃，开动城市引擎逃走。\n此后荒涡不再信颗粒生物，却仍沿用永远活动之物，还把全身都在活动的“永动生物”当成流行宠物，一路把繁殖过剩的撒到途经的漂浮岩块上。它们漂泊了几百个尔什年，又经历一轮兴衰，最盛时有上百座城市，最终个体一个个陷入静止、城与城互相驱赶开战，文明就此灭亡，只剩居民雕像般立在仍自动运转的设施旁。很久以后，城中的工厂管理系统在颗粒生物指引下，把一百零一座城市改成要塞，自行研制出震荡爆弹去攻打静止核心；它们与要塞化成的黑雾同归于静止，复骸者又在核心深处挖出一个一百多米宽、只有一米厚的小洞口。机械炸开地下之后，静止之源向颗粒生物传话，说它要放弃静止一切；苏醒的系统又反复轰炸核心，认定自己已经赢了。',
 ch:'卷七《大型的文明》《被发现》《漩涡》《静止扩散》《新生》《深入》《召集与战争》《尝试》《对抗静止》《崩裂》《活动@346》《时间》《生命的出路》《系统》《接触@350》《静止的场面》《最后的静止》《活动@354》《放弃》', rel:['v_keli','v_shiwu','ng_overview','j1_benyuan']},
{id:'v_piaobo', n:'漂泊者之家 · 末日之眼', c:'物种', m:'void', sec:12, e:[12], p:[-460,60,460], k:'tube', kp:{len:520,r:34,c:'#5a5a6a',glow:'#ffb04a'},
 s:'一根特别的管道：它不培育文明，身上却住满了漂泊的生物。',
 d:'它去的地方越来越特别，身上的文明不断替换，越来越强大。最长久的居民是“末日之眼”——一种针对个性生物文明的灭世型生物，早期像真菌一样小而无害，长到足够大后开始观察……最后它像一层皮肤一样从管道上脱离。在崩溃之界里，漂泊者之家度过了最后的旅途，研究那里的一切，也发现那里有东西在研究它。',
 ch:'卷七《漂泊@378》《虚空之间的旅途》《最后的研究》《边界》《崩溃》', rel:['v_xiubu','v_keli']},
{id:'v_xiubu', n:'修补匠', c:'物种', m:'void', sec:12, e:[12], p:[-660,0,540], k:'crystal', kp:{s:20,c:'#a8a8b8'},
 s:'认为虚空像飘在“无”中的气泡，要修补边缘漏气的地方。',
 d:'它们住在崩溃之界的边境，很清楚这个虚空正在缩小。它们只能活在特别规则的空间里，在正常虚空中会直接消散；模仿外界的生物让它们产生了离开的渴望。它们的大本营融合了大量空间，让这些空间失去“支撑”——两个虚空因此更接近了。\n最早的修补匠连生物都算不上，只能借无法解析者这座“桥”和外界互相感知；它们模仿感知者，造出让对方以为是平行世界的“镜像文明”，没有文明可模仿时就害怕失去意识。一些怀疑自身意义的修补匠，顺着一种能传染、能遗传的思维隧道，找到了自己的制造者——无法解析者。它说修补匠的扩张欲望不过是模仿来的；等琳把它召来时，它说修补匠被了解得太透彻，再也去不了它原想带它们去的地方。',
 ch:'卷七《修复@382》《变形》《目的@386》《位置》《异常@391》《感知与变化》卷七《搜寻》《解析？》', rel:['v_piaobo','v_wufa','v_collide']},
{id:'v_wufa', n:'无法解析者', c:'物种', m:'void', sec:12, e:[12], p:[-200,160,660], k:'shadow', kp:{s:30,shrink:1},
 s:'像一团巨大的影子，能投影在任何东西上，甚至遮蔽整颗翻滚者，却没有实体。',
 d:'它靠一种隐秘的、直径一米多的空间通道在许多空间间移动，墙上细小的黑点是更小的通道，连着修补匠和各种生物的思维。它的意思是：你很可能了解一切——也正因为如此，你不能了解一切。它说，虚空的碰撞大概会持续十个尔什年，然后进入完全融合的状态——到那时，或许会冒出全新的规则和全新的生物。\n它本来想把修补匠接到自己住的地方，可修补匠被太多生物了解了，就再也去不了；它自己似乎正是靠“被认识、却永远解析不完”活着。\n召唤它的办法是修补匠留下的：造一个看不懂的东西，再对着它表示疑惑。琳在三月上照做，一万秒后黑色从方块四周蔓延开，聚成一个黑色的三肢生物，用对方的语言说它们早已灭亡、谁也救不了。至于它说的“十个尔什年”，琳的几百次测试却都表明，这么短的时间根本带不来多大的变化。',
 ch:'卷七《解析》《搜寻》《解析？》《碰撞之初》卷七《搜寻》《多次的结果》', rel:['v_xiubu','v_collide','v_march','j1_jisuan']},
{id:'v_march', n:'三月', c:'琳的造物', m:'void', sec:12, e:[12], p:[120,40,720], k:'planet', kp:{r:40,tex:'rock',c1:'#8a8478',c2:'#5a564e',moons:2},
 s:'琳的兵种：一颗直径一千公里的小型翻滚者，带着两颗三十公里的卫星。',
 d:'琳的兵种：一颗直径一千公里的小型翻滚者，带着两颗三十公里的卫星。它去调查一道一千公里长、数公里宽、伸出许多枝杈般细小裂痕的巨大裂痕。随后数千万矛状飞行器落在三月和两颗卫星上——那是“裂口的文明”：落地时凶猛地直接撞上地表，里面的生物出来后却不知道做什么，只在荒凉的岩石原上到处游荡。琳抓了几只研究，发现它们是颗粒生物当年派出的探索队的后代——有不少成员不愿再走，在虚空各处定居，有的发展成了庞大的文明。三月能感知到无法解析者现身时的空间变化。\n为了召唤无法解析者，琳在三月的地表上照着修补匠的记录，复原了一群三条腿、身体像石块的生物，又造了一座一百多米、像用影子做成的黑色方块让它们疑惑。',
 ch:'卷七《起源》《裂口的文明》《位置》《异常@388》卷七《解析？》', rel:['v_wufa','c_lin3']},
{id:'v_collide', n:'虚空的碰撞', c:'事件', m:'void', sec:12, e:[12,13], p:[0,0,820], k:'cracks', kp:{r:200,c:'#cfd8ff',c2:'#ffd27a',glass:1},
 s:'星空越来越暗了。两个虚空的碰撞开始了。',
 d:'琳的“眼睛”分布在虚空中许多地方，看着这一切；它已经把许多东西移到了安全的位置。直接接触裂痕的生物会受到较大的影响；有的区域出现凝固，有的地方出现前所未有的东西，可能诞生于某种新的规则。此前琳和尔什、莎琳造了计算装置，把碰撞推演了几百次：两个虚空并不是硬碰硬地撞在一起，更像是在“规则”上融合，中间的“墙”没了，大多数生物都能活下来。现实果然一一应验——裂痕、成群汇成寂静之河的小空间、凝固球、缓速区域；连那些找不到来源的结果也出现了：恒星和翻滚者开始失踪。',
 ch:'卷七《碰撞之初》《多次的结果》《现象》卷八《所有结果》', rel:['v_wufa','v_xiubu','v_march','j1_jisuan','j1_jijing','j1_ningqiu','j1_shizong']}
);

/* 卷三：梦境（t 为沿光之大路的位置 0–1，off 为偏移） */
window.WIKI.push(
/* ---------- 时代 6：黑金属与脑灵的梦 ---------- */
{id:'dr_road', n:'光之大路', c:'现象', m:'dream', r:'dr6', e:[6,8,9,10,11], t:.015, off:[0,30,0], k:'none',
 s:'完全黑暗的世界里，一条发着光的大道。道路两侧是星空。',
 d:'每次进入这个梦境，琳都出现在光之道路的开端。道路通常有数十米宽；到了“边缘之地”，却只剩半米宽，弯弯曲曲、上下起伏。光之大路的任务快要结束，尽头就要到了；绒毛被要求拿出自己的证明。这张地图用这条路把各个梦境串在一起——这是示意，并不是说它们真的在一条路上。',
 ch:'卷六《梦中的天国》《边缘之地》', rel:['dr_edge','c_tentacle','dr_brainspirit']},
{id:'dr_tianguo', n:'梦中的天国', c:'地理', m:'dream', r:'dr6', e:[6], t:.05, off:[-140,-20,40], k:'island', kp:{r:60,c:'#2f6a3a',c2:'#5a4a3a',houses:12},
 s:'丛林里住着几十户虚民的梦。',
 d:'虚民的梦：丛林里零零散散住着几十户人家，白天在林间听虫鸣闻花香，夜里看星星，不用工作，邻里关系很好，常在花园里聊天、玩过去的游戏。东西大多是石头和木头做的，却也有能连网的立体影像装置。琳借来连接梦境的那个虚民叛徒也住在这里，虽然是新来的，很快就融入了。有很多房子没有虚民住。琳造了一颗足够大的绒球再次进入，找了间空房子，用影像装置上网查资料——之前那颗绒球太小，打不开这些装置。',
 ch:'卷六《梦中的天国》', rel:['dr_road']},
{id:'dr_prison', n:'梦中的监狱', c:'地理', m:'dream', r:'dr6', e:[6], t:.11, off:[150,10,-30], k:'cube', kp:{s:70,c:'#2a2a34',cells:1},
 s:'无尽的监牢和狱卒。一个被囚禁的“创造者”在这里叫琳“绒毛”。',
 d:'它们遇到的每一个活物都会被‘保留’在这里；可对被保留的生物来说，这里是一座永远不会结束的监牢。那为什么又要造一个放它们出去的机关？有守卫向上面报告：这批里面有几个特别的。琳和创造者谈了很多，还逃出了囚禁之地。',
 ch:'卷六《监狱@86》《难得的交流》《逃出囚禁之地》《监狱风云》《释放与追捕》《苏醒@208》', rel:['c_tentacle','v_prison']},
{id:'dr_zhuan', n:'中转之地', c:'地理', m:'dream', r:'dr6', e:[6], t:.16, off:[-120,40,-60], k:'island', kp:{r:30,c:'#5a5a6a',c2:'#3a3a48'},
 s:'‘绒毛，你做到了。’',
 d:'琳打开了通道，在这里等创造者回来；还没到约好的五个昼夜，创造者就出现了：‘绒毛，你做到了。’它说，绒球杀掉了一个时代里的“愚者”，愚者倒下，真正的通道才会显现，管理者也正是由此回到居所。在等待的时候，琳也看了一部分黑金属入侵的往事：是不是某个虚民不小心接触了虚空巴士留下的金属，行为才开始变得怪异？琳猜，脑灵也许能借那块金属直接寄生到虚民身上，于是决定去母球上把它找出来。',
 ch:'卷六《通路》《找到通路》《建筑中的世界》', rel:['c_tentacle']},
{id:'dr_juso', n:'居所与构造之地', c:'地理', m:'dream', r:'dr6', e:[6], t:.2, off:[160,-30,50], k:'island', kp:{r:70,c:'#e8c87a',c2:'#b8903a',orbs:30},
 s:'强烈的阳光和沙漠，天上飞满了互相玩耍的光团。',
 d:'强烈的阳光下是一片沙漠，天上飞满了光团，像在互相玩耍：晃动、旋转、变成各种形状，完全没注意到绒球和创造者的触手。创造者说，它们没有自己的世界，所以住进自己喜欢的世界里；这里时不时会冒出几个迷路的愚者，它们也不在意。绒球觉得它们虽然快乐，却总在重复同样的事；创造者说不，它们会经常换花样——在尝试别的物种的娱乐。',
 ch:'卷六《居所与构造之地》', rel:['c_tentacle']},
{id:'dr_era', n:'时代的杀戮者', c:'地理', m:'dream', r:'dr6', e:[6], t:.24, off:[-150,0,30], k:'island', kp:{r:44,c:'#6a5a42',c2:'#4a3a2a',castle:1},
 s:'中世纪战争的梦。‘哈哈，上酒！’',
 d:'在梦里，虚民可以任选一个时代、一个身份，想做什么就做什么。一位中世纪领主正大口喝酒，嚷着下个昼夜就去打某个伯爵的领地，一定大获全胜；绒球和创造者躲在床底下看着。创造者说，看那个沉浸在小小欲望里的愚者——下一刻它的触手就穿透了领主的胸膛，周围的仆从扑上去大喊“领主”。创造者的意思是：要找到真正的出路，这些欲望就得被湮灭。',
 ch:'卷六《不同的时代之中》《时代的杀戮者》《历史的见证》', rel:['c_tentacle']},
{id:'dr_edge', n:'边缘之地', c:'地理', m:'dream', r:'dr6', e:[6], t:.28, off:[110,-60,-40], k:'none',
 s:'光之大路的尽头：一条只有半米宽、弯弯曲曲的路。最后的试炼。',
 d:'光之大路的尽头，路面从几十米宽缩成半米左右，弯弯曲曲、上下起伏，一不小心就会跌进无尽的黑暗——创造者说，那和死没什么区别。好在会飘的绒球和只是一根触手的创造者都不怕。这是最后的试炼。路的尽头是一扇黑色金属门，绒球把通行证那颗小球塞进门底的小孔，小球弹回来，门缓缓升起：后面的光路像树枝一样分岔纵横，叫“光网”——创造者说，过了测试的愚者大都在这里迷了路，而它认得路。',
 ch:'卷六《边缘之地》《边缘之处》', rel:['dr_road','c_tentacle']},
{id:'dr_fear', n:'恐惧之地', c:'地理', m:'dream', r:'dr6', e:[6], t:.32, off:[-170,-40,-80], k:'island', kp:{r:66,c:'#3a0e12',c2:'#1a0a0a',deadtrees:1,sky:'#8a1a1a'},
 s:'血色的天空、迷宫和枯树。创造者的恐惧形成的世界。',
 d:'脑灵梦境里的一块封锁区：它会照第一个闯进来的生物最害怕的东西生成环境，闯入者死了，环境才消失，再按下一个闯入者重来。琳和创造者第一次进去时，墙是血色的，地上趴着浑身被铁钉刺穿的虚民——那是一个虚民的恐惧。后来它变成了创造者的恐惧：血色的天空下着蒙蒙细雨，雾气不浓却从不散去；大地像腐烂的泥浆，混着骨头，偶尔是布满裂痕的灰色石地和几棵枯树。这里的寒冷、饥饿和疲倦都和现实一模一样，对虚民和脑灵来说，死在这里就是真死。创造者一不那么害怕，世界就立刻换一副模样，好让它继续恐惧——恐惧维持者让这里一直维持着恐惧。杀死核心生物后，世界不再变化，停在一片爬满畸形肉块的样子；创造者说，现在它对这些只剩厌恶。后来恐惧之地被核心生物打碎，琳把一个阿特兰藏了起来，让按它的恐惧形成的碎片继续存在，还把碎片里的东西搬到边缘，让恐惧之地慢慢“污染”扩大。',
 ch:'卷六《恐惧之地》《恐惧的路途》《恐惧中的生态》《恐惧维持者》《退出恐惧》《周围的地点》', rel:['c_tentacle','dr_brainspirit']},
{id:'dr_brainspirit', n:'脑灵', c:'物种', m:'dream', r:'dr6', e:[6,7], t:.35, off:[60,70,0], k:'fog', kp:{r:40,n:24,c:'#c8a8ff'},
 s:'寄居在别的生物脑中、纯由能量构成的梦境物种，黑金属背后的真正主人。',
 d:'琳先是在黑金属团成员的脑中察觉到一种特殊的能量体，暂且叫它“脑灵”，猜它们是在虚空巴士进犯虚民母球时混进来的。它们和琳造出的勇者、恶魔这类有自我意识的梦境生物有些相像，却不必靠一个脑来维持自身，可以钻进别的生物脑里和宿主对话。寄生对宿主几乎没有伤害，它们还会安抚宿主的情绪，好让身居高位的虚民保持正常；但这种温和的控制力量也弱，总管就是不再信它而叛变的例子。只有高层或有望升上去的成员才被“注入”脑灵。琳推测它们能从虚民幼仔“纯净”的脑里，借一根尖刺把意识一点点抽出来、养成新的个体，后来真在间谍幼仔的头里种出了一个。一块黑色金属里也储藏过它们，最先碰到的虚民就此被感染。琳学会了慢慢吞掉宿主的脑把脑灵逼出来，用脑波封住它的退路，再把抓来的脑灵挤在狭小的空间里，压缩空间让几个消失，其余的出于恐惧便开口招供。\n从它们记在梦境里的历史看，脑灵最早住在一种会互相连接神经的“连结者”脑中，趁宿主连接时换到更强壮长寿的个体里，靠宿主吃下的一种特别物质繁殖，只能透过宿主的眼睛看世界。它们不甘做脑中的囚徒，开始用梦、记忆和脑中的“声音”指挥宿主，起初逼疯了许多，后来让连结者靠它们的建议征服四方。连结者终于明白脑中住的是另一种生物，分成拥护和反抗两派打起内战，种群就此崩溃。脑灵发现任何脑、甚至无生命的物质都能栖身，便以石头为中转站寻找思想复杂、多疑好斗的宿主；一个强大的分工型物种消失后，它们拿它留下的技术把石头造成可以住在里面操控的自动机械，从此抛弃并杀尽了宿主。它们钻穿一块方块、碰到核心，进入了一个远比方块大得多的梦境世界，在那里分化出低智力的“狱卒”等亚种（外表都是一团光），又借方块去往别的翻滚者。它们的群体形态处在分工型物种与个性生物的中间：聚在一起时想法一致，分开后各自思考；它们不会进化，只能靠造机械变强，也从不故意杀害同类。\n梦境深处守护核心的“护核者”打败了来犯的脑灵，双方立约：脑灵可以住在梦境里，但要不断提供现实的情报。脑灵诱使护核者以“亚种繁殖”产下后代，想借此控制它们，又盯上了虚民，并用阿特兰和一套后来证明很糟的自动系统入侵绒球。在南之大陆，学者的一声呼喊引起了琳的注意，脑灵的球形建筑连同周围数百米的部队、地下设施一起消失。寄生在恒星巴士体内的脑灵，则被琳交给勇者的盆状“脑灵监狱”一个个罩出来，监狱自爆后恒星巴士终于相信了琳。最后琳带领虚民、恶魔和印加虫群的舰队，用三十米左右的球形炸弹炸开核心外数公里长的岛屿，再由恒星巴士发射“恒星崩解者”击中脑灵核心，它们的梦境世界一路瓦解，机械全部停转。脑灵没有灭绝，但已无法再威胁虚空。\n琳后来在原灵的基地读到，脑灵其实是分工型物种“原灵”生出的纯能量亚种：原灵的尸体被别的生物吃下，其中的梦境能量随之转移，渐渐有了自己的意志，只是脑灵对此毫不知情，也没有原灵那样的群体意识。失去梦境和同伴之后，残存在虚民脑中的脑灵变得易怒，多半只是让宿主往上爬、享受生活；也有的暗中把虚民的情报交给真菌，想等虚民走投无路时统治剩下的人，这个阴谋同样被击溃。凝固缝隙的罐脑之城里还有一个曾当过“渗透者”的脑灵，住在圆柱形的机械身体里，顶上装的是一团光而不是脑；它经营零件店、设法延缓城市的“智能衰退”，又听信一个说能带它离开、找回同类的声音，被琳注入它罐子里的小护核者不停追问后逐渐失常。卷七中琳还拿脑灵和同样寄生在思维中的“星寂”作比较。',
 ch:'卷六《寄于脑中》《意识与能量》《穿越虚空的信息》《储藏金属》《招供的方法》《脑中声音》《脑中的纷争》《脑中的改变》《世界的变化@157》《发展与方块》《梦境的居民》《监狱@288》《复仇》《完全的计划》《回去》《原住民》《变化的情绪》《继续的计划》《这一步》《崩解》《战争统计》《原本之灵》《情绪变化》《除菌》《异常和正常》卷七《认知@308》', rel:['xm_cult','v_naoling','v_yuanling','v_huhe_guard','v_starbus','rq_blackcity','jiaozhang','c_xuezhe','c_hero','xm_planet','mg_crack','v_xiaohuhe']},
{id:'c_tentacle', n:'创造者的触手', c:'角色', m:'dream', r:'dr6', e:[6,7,8,9,11], t:.13, off:[-60,30,40], k:'none',
 s:'被脑灵囚禁的创造者，借一条三米长的触手和绒球同行。它话很多，总叫琳“绒毛”。',
 d:'创造者是来自虚空、翻滚者级别的巨型生物。这一位还没完全长成，被脑灵关在一颗星系边缘的翻滚者地下，罩在透明罐子里一直沉睡；脑灵想从它的记忆里挖出创造者的故乡在哪，却始终探不到它的深处。它在梦境的监狱里隔着牢房的小孔叫住绒球，放出一根触手陪琳沿光之大路走过愚者的居所、中转之地、边缘之地和恐惧之地，一路说个不停，把虚民这类个性生物统称“愚者”；它还在梦里放出监狱的大批囚犯，冲进脑灵的梦境去捣乱。后来琳在现实里控制了监狱的机械，切下它拔出来的触手末端带它逃走，两个第一次在真实的世界里并肩看夕阳；触手在监狱世界的湖里又长回一棵大树。战后它去了护核者之地，一心要找梦食、吸取那里的梦境核心，抓住了最后一个瑟——研究者；核心吸完后它答应不再搅乱那个世界，在自己的核心里慢慢扩建梦境，身边围着一群吵个不停的小护核者。之后它还常在梦里和琳聊天。',
 ch:'卷六《监狱@86》《难得的交流》《边缘之地》《恐惧之地》《机械的视角》《触手可及》《研究者的恐惧》《梦想的达成》', rel:['v_prison','dr_prison','creator','v_huhe','v_xiaohuhe','v_se']},
/* ---------- 时代 8 ---------- */
{id:'dr_sculpture', n:'雕塑之地', c:'地理', m:'dream', r:'dr8', e:[8], t:.4, off:[0,-40,120], k:'island', kp:{r:80,c:'#f0f0f0',c2:'#d8d8d8',statues:24},
 s:'一片广阔的白色梦境空间，无数生物雕塑团聚在一起，围着某个物体。',
 d:'‘这些……是这个世界本来的生物？’学者和一只虚空蠊站在一片广阔的白色梦境空间里，无数生物雕塑一群群聚着，各自围住一样东西。那根被分工型结晶生物围着的柱子——学者认得它们——只剩一半，大约五米；虚空蠊说，现实里这些结晶生物已经占了大半座城市。这里的情形和现实对应，柱子彻底消失的时候，也许就是它们灭绝的时候。旁边十只半米高、长得几乎一样、像马陆的生物，围着一个十米高的结晶漏斗。别的生物围着的东西大多完整。空间里还有门。',
 ch:'卷六《雕塑之地》', rel:['v_jing','v_kongqian']},
/* ---------- 时代 9：末日空间 ---------- */
{id:'dr_doom', n:'末日空间', c:'地理', m:'dream', r:'dr9', e:[9], t:.45, off:[0,60,0], k:'island', kp:{r:56,c:'#4a3434',c2:'#2a2020',doom:1},
 s:'尔什月亮上隔离起来的十个“末日”空间，每个都是一种可能的世界末日。',
 d:'比露和间谍所在的大楼被传送到一片沙地上时，比露兴奋地猜大家是不是像电影里那样闯进了未知的末日空间，听起来好酷。后来小镇的镇长解释：这里是尔什的月亮，除了核心位置之外的地方都叫“末日空间”，一共十个，每个都是一种末日之后的景象，像核战之后的废土。它们全是“可能的末日”：有的只是可能发生过，有的确实已在尔什上开始，只是在蔓延之前就被隔离出来，放到月亮上。镇长当初接受了某个存在的提议，替它看管这个空间换来永生，如今却觉得有些无聊；它的任务只是向来自尔什的客人说明情况。\n空间里的原住民不知道有这么多个空间，在末日中无法发展，技术大多停留在公元2030年以前，个别空间发展出一些求生用的特殊技术。每个空间都有电脑，某个文件能让人看到核心地点，但要传送还得靠尔什的物品，比如学院的手表；原住民可以从误入的尔什民手里抢。从尔什过来的方法多半是玩游戏：游戏里的“主角”由各处的主角机器造出来，会在现实中出现，沙漠末日对应的游戏叫“异乡入生还”。核心区有一座中世纪小镇和吸血鬼的洋馆，洋馆连着地下图书馆，触摸画、或坐火箭，都能去往各个末日。已知的有沙漠、战争后的废土、冰雪、被淹没的海洋末日（最平静的一个，居民住在船上和高峰上的高楼里）、物种丰富的进化空间（尔什从创造者身上提取了万变的应对系统，让那里的生物急速变异），以及“幻想空间”——它原本用来试验尔什民幼仔被器官扫描出的幻想能否成真，被放弃后才塞进原住民成了末日空间，到处是毫无逻辑的东西。神话空间则是后来被搬到月亮上、与这十个空间连在一起的。洋馆的书里预言，十个空间已经满额，新的末日不会再被放进来，而是会真正降临尔什。\n预言中的日子到来时，末日里也发生了末日：大地崩溃，怪光乱闪，每个空间都无法住人。神话生物们乘火箭连续传送了十个空间，最后到了第十一个地方——一片不属于末日空间的冰原，在那里建立新家园。琳查明，蒸腾者为了找到直接把大军送进尔什的入口，发现了月亮上的这些空间，它们的生成方式和凝固虚空有关；异音强行把凝固虚空接到末日空间，造成空间挤压，压裂后凝固生物便侵入并占领这些地方。拥有权限的总指挥命令器官重新关闭空间，凝固生物随之消失或退回。之后学院手表的传送目标被改成随机的重叠空间点，可能是原来的末日空间已经毁坏。尔什还曾打算做一个“异星末日”，只留下雏形，按电影设计的异星生物被丢进各个末日空间勉强过活。在“末日边界”，原本互不相连的空间搅在一起，一步之外的沙地就接着幻想空间里一望无际的红色大地毯。',
 ch:'卷六《有历史的建筑》《不同的空间》《差不多了》《画》《以前的生活》《空间》《最后一天》《决定@1703》《另一个卫星》《过程@1713》《月亮》《连接的地点》《到那里》《异星？》《边界》《想象@1831》', rel:['ex_moon','dr_wuhu','dr_fei','dr_library','dr_vampire','dr_tower','dr_sweet','dr_toys','c_bilu','c_veronica','v_zhengteng']},
{id:'dr_wuhu', n:'雾湖', c:'地理', m:'dream', r:'dr9', e:[9], t:.47, off:[-150,-20,40], k:'island', kp:{r:50,c:'#4a6a5a',c2:'#6a7a8a',lake:1,fog:1},
 s:'一款游戏里的场景，世界干旱之后在沙漠中忽然冒出来的湖。',
 d:'一款游戏里的场景：世界干旱之后，一个尔什民的祖辈离开城市，在沙漠里旅行，最后找到了水——直径可能有几公里的雾湖，周围是密集的丛林。现实里也有一个雾湖，地形看上去就像游戏场景上盖了一层沙，而游戏出售时还没有旱灾，据说那时也没有这个湖。一群偷猎者迷迷糊糊地从上百公里外走到湖边，想抢房车，被比露全砍倒了。比露进到游戏里很失望：这不是游戏吗？怎么一只怪物都没有！——然后墙外传来了奇怪的声音，会说尔什语的镇长笑着说：这里就是尔什上早已消失的月亮。',
 ch:'卷六《错开的世界》《游戏？》《游戏之内》《小镇》《不同的空间》', rel:['dr_fei','c_bilu']},
{id:'dr_fei', n:'废土', c:'地理', m:'dream', r:'dr9', e:[9], t:.5, off:[150,10,-30], k:'island', kp:{r:46,c:'#7a5a42',c2:'#5a3a2a',ruins:1},
 s:'布满建筑碎片和车辆残骸的街道；雾湖边缘布满裂痕的红色砖墙。',
 d:'雾气弥漫的大湖边，布满裂痕的红砖墙围着一座爬满藤蔓的老洋馆，钟楼断了，横倒在院子里。据说摸了馆里的某幅画就能去废土：画里总是两个穿得很华丽的幼年尔什民，有的画还会晃一晃，扑出一个摇摇晃晃的小家伙，把比露吓得躲到间谍身后。穿过去之后，是满街建筑碎片、车辆残骸和淡淡放射尘的城市——比露想看的变异怪物没有，只有一群胖得过得很好的“鬣狗”，在几十米外探头探脑。',
 ch:'卷六《废弃建筑》《传说中的》《废土》《红色的地方》', rel:['dr_library']},
{id:'dr_library', n:'地下图书馆 · 火箭', c:'地理', m:'dream', r:'dr9', e:[9], t:.52, off:[-130,-50,-50], k:'island', kp:{r:40,c:'#5a4a3a',c2:'#3a2a1a',rocket:1},
 s:'吸血鬼洋馆地下的巨大图书馆，密室里藏着能穿梭各个末日的空间火箭。',
 d:'为了找能通往废土的画，比露和间谍来到洋馆下面的图书馆。它比地上的建筑还大，直径可能有数百米，六米左右高的书架一眼望不到头，书架和书都和上面一样老旧发霉，天花板上吊着巨大的灯饰。据说这里收集了尔什世界大多数名著，还有大量古怪的书画资料，连馆主吸血鬼也不知道有多少本。有些书讲的就是这个空间和这颗月亮，琳由此得知洋馆原先的住民来自尔什，后来被迁到这里；吸血鬼姐妹也正是在这里找到那本预言新末日的书。一名玩家在游戏里选完最后一个主角后晕倒，醒来变成了吸血鬼主角，在书架间惊恐地游荡，它有中空能吸血的尖牙和分泌抗凝物质的毒囊，听说自己经历的寒冷世界不过是一个末日空间后发起呆来。馆里的每幅画都通向一个末日，触碰它就能过去。\n图书馆有一间要用隐秘方法才能进入的密室，书架都让开了，中心立着一个十多米高、直径三米、外壳像铁皮拼成的圆柱，吸血鬼叫它“空间火箭”：把画放到里面的“定位器”上，就能去任何空间。可它们之前用这个办法过去的同伴都失去了记忆。火箭分三层，第一层像豪华小房间，铺着红地毯，摆着红沙发、桌子和雕花杯子；第三层的地上铺着用巴士生物神经做成的线。一段旧录像里，穿红白衣服的尔什民坐在第三层中央设定目的地，说要花一年左右。间谍把线接到自己的脑神经上，把一颗球形道具摆上画框，火箭便整个传送到一片没有正常大气的冰原，与吸血鬼当初只送走乘客不同；比露在第三层等得睡着了。随后它们收集了各处通往末日的道具摆满画框，坐着火箭逛过浓烟弥漫的世界和海洋末日。\n末日来临的最后一天，吸血鬼划着木船追来，要用手表换回火箭；红白尔什民驾驶它，带比露和间谍穿过十个正在崩坏的末日空间，到达一片冰原，许多神话生物的火箭也接连在那里出现。后来神话空间也发生“空间崩溃”，吸血鬼和同伴再次乘火箭辗转多处，并让工程师给原本只能传送不会飞的火箭加装了飞行引擎，降落在学院的天台上要燃料；巴士侠“饮酒侠”背来一大桶高能燃料，间谍便开着火箭在一片黑暗中飞向传送器官，最后看到一座和洋馆一模一样、却完好无损的建筑。',
 ch:'卷六《地下@1689》《画》《以前的生活》《什么方法》《收集@1698》《流动》《最后一天》《决定@1703》《另一个卫星》《变异的影响@1761》《新的》《搬运工》《变幻》', rel:['dr_vampire','dr_doom','dr_fei','c_bilu','c_veronica','ex_moon','ng_busman']},
{id:'dr_vampire', n:'吸血鬼的洋馆', c:'地理', m:'dream', r:'dr9', e:[9], t:.55, off:[140,20,40], k:'island', kp:{r:40,c:'#3a2a3a',c2:'#2a1a22',manor:1},
 s:'一个“有故事的吸血鬼”，和它金发的妹妹。',
 d:'游戏主角就是模仿传说中的吸血鬼造的，听说它们怕大蒜——可是比露没带，它本来也不爱吃。这里的蚊子吸了血不自己消化，而是吐出来，酿成一种含水量极少的东西。比露读完日记哭了起来：‘好惨，好可怜……’神话生物“红”（红白）是大小姐的仆从；它问间谍：“你也能联络它们吗？”',
 ch:'卷六《吸血的生活》《以前的生活》《恢复》《最后一天》《狩猎巴士》', rel:['dr_manzhu','dr_library']},
{id:'dr_manzhu', n:'曼珠沙华的庭院', c:'地理', m:'dream', r:'dr9', e:[9], t:.58, off:[-120,30,60], k:'island', kp:{r:44,c:'#3a3a3a',c2:'#2a2a2a',flowers:'#d8203a',souls:1},
 s:'淤泥小道、雾气、红色的花，“灵魂”在植物之间飘过。',
 d:'一条淤泥小道穿过浓雾，两边密密麻麻开满红色的花，像铺了红地毯，取自尔什民关于地狱的传说。比露一路喊冷：花红红的，看着好像挺暖和，其实冷得要命。间谍递给它一副照着螳螂虾眼睛做的眼镜——戴上就能看见河边、岸上飘着一团团半透明的东西，大概算是“灵魂”，冷就是它们吸走热量造成的。尔什民的灵魂传说太丰富了，相信有灵魂，个性再强的生物也能悍不畏死地作战。',
 ch:'卷六《灵魂》《建设中》《流动》', rel:['dr_vampire']},
{id:'dr_tower', n:'淹没高峰上的高楼', c:'地理', m:'dream', r:'dr9', e:[9], t:.6, off:[140,-40,-40], k:'island', kp:{r:30,c:'#2a5a8a',c2:'#1a3a5a',tower:1},
 s:'它对着水感叹：为什么到处都是大海呢？',
 d:'“海洋末日”是一个很好懂的末日：海水淹没了整个世界，最后的居民逃到高处建起城市，过了一阵连那里也被淹了，从此全世界再没有陆地，大家只能住在船之类漂浮的东西上。这栋一百多米高的楼就建在被淹没的山峰上，一半泡在水里。末日空间的最后一天，比露和间谍站在楼顶，四周是望不到边的海，比露对着水抱怨：为什么到处都是海呢？',
 ch:'卷六《最后一天》《决定@1703》', rel:['dr_doom']},
{id:'dr_sweet', n:'甜点之地', c:'地理', m:'dream', r:'dr9', e:[9], t:.63, off:[-140,10,-20], k:'island', kp:{r:52,c:'#e8b8c8',c2:'#c88a5a',sweets:1},
 s:'金属饼干构成的平原，居民都被“甜点机”变成了甜点民。',
 d:'一片金属饼干构成的平原，中间立着一座甜点城堡。进化空间的尔什民偶然闯进这个幻想空间，从没吃过甜点，却被香气引进城堡，挖起饼干和巧克力碎屑往嘴里塞——城里的甜点含有致幻物质，吃多了就疯疯癫癫，各自看见不同的幻觉，只是幻觉里的地面都铺满食物，于是吃个不停。居民都被“甜点机”变成了甜点民，生活目标就是把别的生物也变成甜点、传播自己感受到的痛苦：‘把它也变成甜点，变成我们自己人！’花园里有一场茶会：比露问有没有盐，店员说喝茶不放盐；比露不服气，坚称它听说过放盐的茶。',
 ch:'卷六《甜点到处都是》《甜点》《点心》《偶然的想象》《不同地方的茶会》', rel:['dr_doom','c_bilu']},
{id:'dr_seaweed', n:'海藻民的村落', c:'地理', m:'dream', r:'dr9', e:[9], t:.645, off:[120,-60,60], k:'island', kp:{r:30,c:'#3a6a5a',c2:'#e8e0c8',bones:1},
 s:'满地鱼类和海生物的尸体，房屋是用大量鱼骨组装的。',
 d:'空气里满是海腥味，来自遍地的鱼和海生物的尸体。居民全身披着海藻，几乎看不清身形和脸，琳叫它们“海藻民”。它们用大量鱼骨搭起大小不一的房子，从骨头缝里能看见珊瑚骨架和大螺壳做的家具；有的在捡贝壳，有的在屋旁种植物，有的养着一大群海蟑螂，也有闲逛的一见间谍就扑过来，被它一戳就倒。比起之前遇到的那些，这里算是正常的生态。附近还有一座满是骷髅小动物的迷宫，和一口飘着眼球的“火锅”。',
 ch:'卷六《充满海腥味》《突击》《新区域》《食客》', rel:['dr_doom']},
{id:'dr_toys', n:'彩色道路 · 绒毛玩具', c:'地理', m:'dream', r:'dr9', e:[9], t:.655, off:[0,-80,-100], k:'island', kp:{r:36,c:'#ff9ad8',c2:'#8ad8ff',toys:1},
 s:'幻想空间：到处是鲜艳的彩色和看上去很可爱的绒毛玩具。',
 d:'间谍和比露走在一条到处是鲜艳彩色的道路上，两边堆满看起来很可爱的绒毛玩具。比露嘀咕这里看着挺华丽，可惜没什么好吃的。绒毛玩具其实是肉食生物，只是平时不攻击，所以从旁边走过去很安全——可琳觉得这里并不安全，因为除了绒毛玩具之外还有别的东西。琳还发现，脑袋虫一类的生物有一种感知空间的能力，琳暂时叫它‘空间记忆’：它不能单独运作，要靠一些情况来触发；玛雅、教长和间谍在这里遇到的一种很像脑袋虫的生物，都有这种能力。',
 ch:'卷六《探测空间》《小型空间@1848》《清扫@1852》', rel:['dr_doom','c_maya']},
/* ---------- 时代 10 ---------- */
{id:'dr_dreamshaper', n:'梦塑者', c:'物种', m:'dream', r:'dr10', e:[10,11], t:.7, off:[0,0,140], k:'whale', kp:{s:60,c:'#8a7ab8',sleep:1},
 s:'永远沉睡、不断做梦的巨大金属状生物，碎片生物从它们的梦里诞生。',
 d:'在碎片生物眼里，梦塑者是一块块会思考的巨大金属，碰到它们就能感觉到它们的想象漫游在广阔的虚空中；从它们身上掉下的碎片变成了生物，清楚地知道自己是从“梦”中诞生的（“梦塑者”这个名字是琳起的）。梦塑者的梦没有规律，梦中的事物都是随机的，有的生物认为那是它们一生漂流所见，有的认为只是想象。碎片生物照着梦生活：造出梦里的建筑，甚至缩小版的翻滚者，学会梦里的技术；梦塑者的碎块可塑性极高，整个空间很快被改造成一个把梦具现化的地方。直到某个梦塑者梦见了战争，碎片生物也打起仗来，资源耗尽后就直接挖掘梦塑者，即使被挖成粉末，梦塑者也从未醒来，它们就这样一点点变小。陷入沉睡、醒来时身边全是梦里的东西，本是件有趣的事，可它们一次也没有醒过。\n碎片生物照梦中的文明继续挖掘，却遇上造物主毁在自己造物手里的局面：它们造出的生物起来反抗，而梦里的“神”只在一旁看着取乐。为了让现实与梦一致，它们想弄醒梦塑者来观看，所有刺激都没用，便干脆把大量碎片和生命物质装进一具拼起来的躯体，造一个梦塑者当神。这具躯体动了起来，却攻击周围所有生物，拒绝做它们的神——它的意识其实来自先前钻进去的一群圆环。圆环嫌梦塑者的随机梦境不值得追求，挖开它们研究怎样做梦，与碎片生物激战，最终学会了，并吃光了所有梦塑者；空间开始崩塌，碎片生物重组出一个不活的梦塑者才止住崩溃。圆环后来带着碎片生物离开，成了熔链。一个只有几米大、一直藏在角落的小梦塑者随后迅速长大、散落碎片，新一代碎片生物又追寻起它梦中离去的圆环；从尸体中又诞生出全新的生物。\n琳进入这个空间时，看到数以万计、几十米大的小梦塑者飘在空中，它们什么也不干，只是在想象，身上抓着许多多肢、像虫子的碎片生物，只会抱怨梦塑者做梦太久，自己也什么都不做，而空间正在慢慢塌陷；小梦塑者把过去的历史当作梦一遍遍重播。梦想猎手说，传说梦塑者等虚空生物是那些按自己想象塑造出不可预见之地的“想象生物”的后代，这个空间是一处可能通往那里的“远古空间”，猎手自己就猎杀过梦塑者这类生物。梦塑者从不梦见自己——准确地说，它们会梦到自己在一片背景通红的地方静静飘浮，只是不把这部分展示出来，碎片生物感知不到。在储藏库空间里，猎手还发现漫天飘散的碎屑本身就是一个管理储藏的梦塑者，它很容易醒来并攻击入侵者，资源耗尽时必定会醒，可能就是梦塑者的源头。',
 ch:'卷六《碎片@2866》《梦中造物》《追寻梦想之物》《融合@2869》《制造梦境》《出去@2871》《真正的梦境》《捕获@2873》《追求与猎杀》《塑梦的地方》《结果》《生物@2885》《藏》', rel:['dr_ronglian','dr_hunter','bk_overview','v_pain']},
{id:'dr_ronglian', n:'熔链', c:'物种', m:'dream', r:'dr10', e:[10,11], t:.72, off:[-120,40,0], k:'ring', kp:{r:30,n:5,c:'#ff8a3a',chain:1},
 s:'由圆环锁链和碎片生物核心组成的“超级分工型物种”，转眼拼出各种武器。',
 d:'“风暴之眼”是一种曾在战争中使用的智能机械武器，尔什由它想起了设计这类武器的“熔链”：某颗巴士上的个性生物称它们为“超级分工型物种”，擅长在战场上瞬间拼出各种武器。不过这一颗是用巴士结构造的，而熔链从不用巴士结构，所以未必出自它们之手。指挥风暴之眼的地方飘着一具熔链的尸体：数十米粗的金属锁链扭成一团直径约十公里的“线团”。活着的熔链中心有一颗像小型恒星的光球，它们在战场上收集战舰残骸、巴士尸体等碎块丢进光球，在里面合成武器投入战斗；死后光球消失，只剩锁链。一根六十多米粗的锁链由无数圆环叠成，圆环厚近一米、几乎是空心的，每个圆环是一个个体，每根锁链是一个种群，整团就是一个超级群落。\n它的源头在梦塑者的空间：最早的圆环在梦塑者战场附近吞食尸体，钻进碎片生物拼出的梦塑者躯体并与之融合，想要自己做梦，吃光了那里的梦塑者，最后带着碎片生物离开。外面的“锁链”和里面作为“核心”的碎片生物原是两个意识，如今已是一个完整的生物：锁链负责战斗和收集材料，把虚空里遇到的东西打碎丢进核心；锁链一想象，核心就把想到的东西造出来，第一次慢，之后就快了，风暴之眼就是这样造出的。它们还造出由几个圆环和少量碎片生物组成的幼仔，慢慢长成同样巨大的个体，但总数大概不超过十个。熔链最感兴趣的是各种生物的想象与梦境。一群生物给它看了“真正的梦境”——所有生物梦境汇聚的梦想之地，也就是不可预见之地，说巴士生物会阻止它和这个虚空靠近；熔链于是带着后代参加了对抗巴士的战争，不断发明新东西，结果全部战死。尸体中偶尔有圆环复苏，在附近游荡到死，从不离开；核心虽已空了，仍连着梦塑者的空间，那里记录着它的历史。\n熔链死时飘散的思维能量有一部分渗进旁边一个古老的小空间，在那里诞生了一个梦境创造者的造物，它一心要前往梦想之地，引爆空间里的能量唤醒了整具躯体，核心重新亮起。圆环成群飞出，用高温射线攻击梦想猎手，猎手却毫发无伤，一头撞断了锁链；熔链逼它打开一条“隐秘通道”，通道没有打开，反而遇到一个可能是梦塑者源头的古老生物。随后它陷入背景通红的“噩梦”：它的意识能量像皮肤一样附在每根锁链上，此刻不停震荡，每当它“看”向某处，那里的金属块就燃起火焰，它疯狂攻击、又为此痛苦。最后一颗满目苍夷、中间横着巨大裂痕的巴士——痛苦巴士——靠近，熔链没有逃，只不停问“为什么”，被引力扯得散架，圆环和核心像流星雨一样坠向它的地表。熔链的意识被困在巴士硬化的神经结构里，承受着灌入的痛苦又死不了，只能不断求救；琳用一个十多米宽的吸盘状装置把它的一部分意识提取出来，得知巴士在“塑造意识”、制造情绪生物，并放大了熔链当时的情绪。再往深处挖，琳发现正是痛苦巴士截获了梦境创造者发出的信号，用它造出了熔链这个意识。',
 ch:'卷六《风暴之眼》《残骸@2864》《融合@2869》《制造梦境》《真正的梦境》《捕获@2873》《幕后》《认识之物》《思维的代替》《完全复苏》《碰撞@2883》《结果》《噩梦》《藏》《燃烧的痛苦》《地表@2889》《塑造意识》《提取@2896》《它的意识@2897》', rel:['dr_hunter','dr_dreamshaper','v_pain','v_warbus','ex_nuo','bk_overview']},
{id:'dr_hunter', n:'梦想猎手', c:'物种', m:'dream', r:'dr10', e:[10,11], t:.735, off:[110,-40,-30], k:'blob', kp:{s:10,c:'#c8b878'},
 s:'像一团粘在锁链上的浆糊。一生下来就装满了知识——只为猎杀追梦者。',
 d:'一种巴士生物，样子像一团粘在锁链上的浆糊，本质上很像体型被定住、内脏却继续长到成熟的虚空巴士幼仔。传说很久以前有一类生物，意识从不接触现实，只活在想象里，周围的环境却会变成它们想象的样子——“不可预见之地”就是这样来的，梦塑者等都是它们的后代。梦想猎手一生下来脑子里就装满了知识，唯一的用处是猎杀这些追寻梦想的东西：让它们活不下去，也让梦想断掉。问它为什么，它说不这么做，它们一定会重走老路——把梦想追到尽头，就会引来大规模的毁灭。最近很多生物在找“远古空间”，猎手的数量也跟着增加了。',
 ch:'卷六《追求与猎杀》《塑梦的地方》《幕后》《完全复苏》《结果》《藏》', rel:['dr_ronglian','dr_dreamshaper']},
/* ---------- 时代 11 ---------- */
{id:'dr_mengli', n:'梦历 · 梦的泥海', c:'地理', m:'dream', r:'dr11', e:[11], t:.8, off:[0,-40,0], k:'island', kp:{r:110,c:'#5a4a3a',c2:'#3a2e24',mud:1,ships:4},
 s:'扭曲点附近死去生物的思维化成的梦境生物，漂流在发光的梦境泥海上。',
 d:'“梦历”是琳起的名字：它们是历史上生活在扭曲场附近的各种生物死后留下的思维和意识所形成的梦境生物，从很古老的时代到现在都有，外形保持原样，大小却一律两三米；只要拥有能认识虚空的智慧，都可能变成梦历。它们所在的空间里每隔数百公里立着一根长达数百公里、粗不到一百米的石柱，“头部”有一个圆形平台。梦历们不停逆风前进、呼唤凤凰，凤凰懂得各种梦历的“语言”并分给它们力量，对琳的绒球却充满敌意；呼唤失败的梦历越来越暗，最后消失，风暴吹过也会带走它们的一部分力量。一个十多公里大、没有石柱的圆盘上聚着数百个梦历，它们一边聊各自生前的事，一边组队袭击同类、夺取能量。一个外表像发光液体的创造者梦历在它们身上悄悄放下一毫米大小的“吸取球”，每当小队杀死别的梦历，它就能分得能量和死者流散的记忆数据，后来却被三只翡翠龙梦历杀死。\n管理这里的是一群触手形状的发光生物，它们接管了吸取球，负责“收集”梦历，也说琳的意识无法转化为这里的梦境能量、是收集不了的目标。据它们说，这个地方是一种自然现象，最初梦历生成后很快就会死去；后来一个生物（琳认为是创造之海）改动了这里，让数据保存下来，梦历死后会失去在这里的全部记忆再度“复活”，以为自己刚刚来到。为了收集那些不容易死的长寿生物，它们还有一颗巨大的梦境能量球当武器。绒球世界上早已灭绝的亚特种群的兵种，包括造脑怪，也毫无思想地飘在这里。\n更深处是琳所说的梦境泥海：一片发着光、由浓郁梦境能量构成的泥海，气流平静，像在虚空中无限延伸，许多形态各异的生物离不开它，像冲上岸捕猎的鱼一样一次次冒险跃出。骸龙塑造的梦境帆船在泥海上航行，不靠风，而是靠希望：心存希望船就会自己前进，反之越来越慢直到停下，不少生物就是这样死去的。船帆上画着绒球的标志，骸龙们向它祷告，盼着那个方向有希望，也盼着绒球的光照亮航路；不过梦历们其实并没有目的地，只是为旅行而旅行，从不定居。一个快得惊人、杂念极少的骸龙“跳跃者”能在泥海海面上奔跑跳跃，独自击散了巨大的旋风。三百多个入侵者聚成一个直径数百米的光团撞上泥海边缘，整片海随之一晃，海浪被打得千疮百孔，聚集起来的思维还经由扭曲点的裂痕冲击到外面的虚空；跳跃者和琳从前造的“零”所形成的梦历凭坚定的情绪挡住了它们，光团随即分散。琳后来查明，入侵者带回的意识碎片和梦历死后飞来的大部分“尸体”，都在一座金字塔处拼回创造之海的意识；琳试图用爆弹破坏，金字塔最后自己炸开，与梦历空间紧贴的召集者空间也随之牵连进来。',
 ch:'卷六《梦境的旅途》《吞噬@3309》《聚集@3311》《处理@3312》《到那个什么那那那@3314》《航行@3315》《光芒》《扩散@3317》《抵挡》《修复@3319》《分散@3320》《调查@3321》《聚集@3323》《另一边@3324》', rel:['dr_jumper','dr_zero','gulong','dr_galaxy','v_feng','v_chuangzao','dr_zhaoji','zaonao']},
{id:'dr_jumper', n:'跳跃者', c:'角色', m:'dream', r:'dr11', e:[11], t:.82, off:[90,20,40], k:'none',
 s:'它说要把绒球的希望带到每一个地方去。',
 d:'一艘载着骸龙的帆船被一团旋风追上，梦境弩箭射它毫无效果，船尾被卷碎、光屑纷飞，骸龙们对着帆上的绒球标志拼命祈祷，越祈祷船跑得越快，却还是不够快。这时一个骸龙从天而降，喊着“绒球会照亮一切”，抡起比自己还大的斧头劈进旋风中心，旋风随之散开。它落进海里，再猛地一跃跳上船，船上的骸龙欢呼它是伟大的跳跃者。琳发现它的情绪里“杂念”非常少，不像船上那些总在东想西想的骸龙；它说要把绒球的希望带到每一个地方去。',
 ch:'卷六《光芒》《抵挡》', rel:['dr_mengli']},
{id:'dr_zero', n:'零', c:'琳的造物', m:'dream', r:'dr11', e:[10,11], t:.83, off:[110,40,70], k:'fluffglow', kp:{s:8,c:'#fff4d8'},
 s:'琳以前造出的、和琳性格一模一样的生物。',
 d:'琳以前造出的、和琳性格一模一样的生物。跳跃者旁边那颗绒球一样的光团，是“零”所形成的梦历。琳一接近就能感觉到，它的思维和自己有“共鸣”的部分——它可能在这里充当着跳跃者和骸龙们的信仰对象。数百米宽的光团入侵时，小小的零和一个骸龙挡在前面：这里的战斗主要靠情绪压制对方，只要自己的情绪稳得住，就挡得住。后来这片地方的生物一夕之间全死了，飘着的化成粉末，等待的砂鲼一动不动，琳和零却毫发无伤；还是零先提议，去找白星或凤凰问问。返乡之道上，琳也和零一起走过。',
 ch:'卷六《控制的聚集》《港口？》《延伸的光芒》《光芒》《抵挡》', rel:['dr_mengli','dr_jumper','bk_home']},
{id:'dr_galaxy', n:'微缩银河', c:'现象', m:'dream', r:'dr11', e:[11], t:.84, off:[-140,60,-60], k:'vortex', kp:{r:46,c:'#c8d8ff',disc:1},
 s:'一块直径接近十公里、厚三百多米的漆黑圆盘，上面闪着无数光点。',
 d:'说是微缩型的银河，它也不算很小。圆盘上的光点各说各话：我是谁、看到了、没看到、我活着……越靠近扭曲点的裂痕，它们的话就越整齐。零后来告诉琳，这个圆盘属于创造者一方，专门从各种生物的思维里收集创造之海的意识碎片——那些光点就是碎片；梦历里那些“入侵者”其实是在帮创造之海把意识拼回来。',
 ch:'卷六《分散@3320》', rel:['dr_mengli','dr_zero','v_chuangzao']},
{id:'dr_zhaoji', n:'召集者 · 遥远回响', c:'角色', m:'dream', r:'dr11', e:[11], t:.86, off:[130,0,-50], k:'none',
 s:'第一个到达“遥远回响”的生物，召集别的生物去完成“混合虚空”的目标。',
 d:'混合后的虚空，也不是谁都喜欢——巴士生物就不赞成。召集者召集大量生物与巴士开战，战后“遥远回响”被彻底摧毁，参战的生物分散到了虚空中——只有一个意识没有离开。召集者的空间里，“绒球世界”在不断颤抖。',
 ch:'卷六《分散@3320》《召集者》《虚空中的数据》', rel:['v_hunhe','dr_bridge']},
{id:'dr_bridge', n:'创造之海的意识桥梁', c:'地理', m:'dream', r:'dr11', e:[11], t:.88, off:[-110,-40,40], k:'island', kp:{r:90,c:'#f8f8f4',c2:'#e8e8e0',flat:1},
 s:'这里是第三处，才是真正没有尽头的地方。',
 d:'一望无际的白色大地。琳原本以为这会是一趟孤独的旅途，却有很多“同伴”：“前进！滚动！前进！”被琳叫作“黑夜”的生物体内保存着相关的记忆；一个像白色沙砾堆起来的生物以极快的速度发射细碎沙砾，杀死了琳的绒球。',
 ch:'卷六《隐藏的入口》卷七《桥》《渐变》《思维》《另一个生物》', rel:['v_chuangzao','dr_zhaoji','dr_tunnel']},
{id:'dr_tunnel', n:'末日隧道', c:'物种', m:'dream', r:'dr11', e:[11], t:.9, off:[100,60,30], k:'tube', kp:{len:200,r:20,c:'#3a3050',glow:'#c88aff'},
 s:'土生土长的不可预见之地物种，和创造之海一样，想搭一座“桥梁”通向正常虚空。',
 d:'它造出的桥梁从来不够长，于是一直用各种方法“窥视”正常虚空。它游荡在大小不一的“希望空间”之间，潜入别的意识重温记忆的生活里观察，却通常不去影响它们。它的居民们发现自己的“虚空”是有限的，文明一次次在绝望中崩溃，于是开始研究“希望”。',
 ch:'卷七《另一个生物》《末日》《集中的希望》《痛苦与希望》《重温记忆》', rel:['dr_hope','dr_bridge']},
{id:'dr_hope', n:'希望空间', c:'地理', m:'dream', r:'dr11', e:[11], t:.93, off:[0,-50,110], k:'island', kp:{r:90,c:'#4a7a3a',c2:'#6a5a42',hope:1},
 s:'死去意识重温记忆而成的空间，生物随主意识一次次重启、换上新身份。',
 d:'“希望空间”是琳起的名字。这类空间大小不一、数量极多，分布在不可预见之地与正常虚空之间，彼此隔着距离却有联系，维持它们的也和不可预见之地有关。每个空间都由某个意识的记忆数据生成，它在里面一遍又一遍地重温生前的生活；末日隧道就是住在这里的生物，常常潜入别的空间旁观，却不去打扰。足够古老的意识可能摆脱束缚，成为在多个空间间游荡的“原始游荡者”。直径大约不到一百米、尚未长大的空间，有一种“规则”挡住正常虚空的物质，但它们能容纳的梦境能量极为庞大；琳在这里甚至能造出不需要实体“脑”来控制的纯梦境兵种。按游荡者的说法，不可预见之地刚“初生”时就是大量的希望空间。空间里的生物虽由记忆数据生成，生成后便是真正的梦境生物，它们受主意识支配，跟着它一起重启，每轮被分配新的身份，甚至可能换成别的物种；主意识越有希望，空间越大，越绝望就越小。\n脱离这种轮回、不跟随任何主意识的生物叫“脱离者”，身上会出现古怪的变化，它们的肉一碰到别的东西就会让对方在形态上“发疯”，一群尔什民就专门在各空间之间跳跃搜集这种肉。一个巨大尔什民模样的智能机械被处死后，记忆飘进一片美丽的草原，那正是它整合的“感叹会”成员们所希望的环境，死去的成员一个个从它体内分裂出来过上了幸福日子。脱骨娃娃诞生于空间灭亡时的纯粹绝望，到处吞噬希望空间，连不可预见之地的边缘也受了损伤；对它们来说空间间的距离以情绪衡量，越绝望越近；它们留下的那幅“画”接近某个空间时，会让那里的生物梦见可怕的景象，加速终结。\n骸龙的希望空间属于塔克：一座座三十多米高的岩石建筑和骸龙城堡，食物快吃完了得搬家，而骸龙一直充满希望，主要来自对绒球的信仰。这里的造脑怪依旧不值得信赖，有一只把各种生物的脑堆成“脑堆”，重启后仍然是脑堆；另一只在裂谷边叫卖情报，十个美杜果就换一个“世界的秘密”。侏儒把排泄物丢进荒民的空间去“滋润”它，让荒民一次次轮回，还在丛林里造了许多顶上摆着动物雕像的小金字塔神庙。一个直径三十米、缠满树根的红色绒球是另一个空间的主意识，它把塔克空间储存的希望能量分给附近的空间来保护它们，反而让塔克这里离娃娃变近了；飘来飘去的小红绒球则能暂时缓解娃娃的绝望。自称最后一个“培养者”的古老生物告诉琳，它的任务就是培养希望空间、让虚空变大，过去许多培养者曾借这些空间把两个虚空连在一起，空间崩溃后两边越离越远。培养者把塔克和它的族群搬到入口附近：骸龙的城市在一片白雾构成的“海洋”上重建，原本像普通岩石的小岛变成了密集的雨林；塔克原来的空间则被娃娃占据，变成一片黑色沙漠。',
 ch:'卷七《前往方法》《脱离载体》《了解@18》《不同的过去》《想知道这个世界的秘密吗？》《脑堆》《滋养世界的侏儒》《裂谷》《猎物》《感叹》《特殊的脱离》《吞噬绝望的生物》《新目标》《找到@51》《入侵@52》《本身的希望》《稳定》《前往@55》《进展》', rel:['dr_tako','dr_doll','dr_tunnel','dr_lastland','bk_overview','gulong','zaonao','zhuru']},
{id:'dr_tako', n:'塔克（希望空间）', c:'角色', m:'dream', r:'dr11', e:[11], t:.95, off:[-90,30,60], k:'none',
 s:'希望空间里带着塔克记忆的骸龙首领，一次次轮回中始终信仰绒球。',
 d:'琳在希望空间里遇到的塔克，不是本来的那只塔克，只是承载着它记忆数据的梦境生物，模样却几乎没有变化。它统领着一座骸龙城镇：三十多米高的岩石建筑之间铺着石砖，骸龙不养任何动植物，食物全靠出外狩猎；猎物越来越少，族人劝它搬家，它却不肯放弃这里。琳的间谍被卫兵拦住时，塔克在上面发话让它进来，似乎从间谍身上感到了熟悉。它住在一座半球形的城堡里，推开沉重的石门，里面像一片丛林，还有一个个池子，那是它记忆中最深刻的地方，每一轮它都照着造出来，等待那个存在回来。\n塔克知道自己在一遍遍重温回忆，这是某个游荡者告诉它的。第一轮与真实虚空中完全一样：遇见绒球、经历种种，最后老去死亡；之后的轮回里绒球再没出现，它对绒球只剩模糊却伟大的印象，于是在族群里宣扬对绒球的信仰，战斗时高喊为绒球而死。有的轮回里它没遇到白骸龙，有时则把绒球教过的东西记得更清楚。当间谍坦白自己就是绒球时，它激动得说不出话。随后穆克拉组织了一支大军来攻，夹在毛玉群中的会飞毛玉专门扑向塔克，却没一个能得手。塔克告诉琳，这些“轮回刺客”都知道杀死它就能让整个空间重来，以前也真有成功的时候；它一死，这里的一切就崩溃并回到起点。塔克并不追问琳要去哪，只要知道绒球就在这里，它便信心十足。\n琳告诉它外面脱骨娃娃的威胁，它很震惊，没想到外面有那么多奇异的事，却毫无惧色，立刻组建部队到峡谷里清除娃娃。塔克的信仰从未改变，它的空间因此拥有一种极其稳定、不增不减的希望，被培养者看中。为了避开娃娃，城堡被改造成一座透明外壳、长满植物的巨大温室，只有塔克在里面；琳按培养者的方法往它的头里输入信息，引导它进入似死非死的“拟轮回”状态，它因为完全信任绒球而很快接受了。塔克被搬到白雾海洋中的一块岩石上，唤醒之后，植物、骸龙城的建筑和居民在它周围一一重新出现，它将在那里继续它的信仰与生活。',
 ch:'卷七《不同的过去》《老龙》《熟悉》《刺客》《想知道这个世界的秘密吗？》《返回》《准备》《找到@51》《稳定》《前往@55》《抵达@56》《进展》', rel:['tako','dr_hope','dr_doll','gulong','mukela','maoyu','zaonao','dr_tunnel']},
{id:'dr_doll', n:'脱骨娃娃', c:'物种', m:'dream', r:'dr11', e:[11], t:.97, off:[120,-30,-40], k:'swarm', kp:{n:200,s:50,c:'#141414'},
 s:'全身黑色、只有半米高的生物，十多万只像黑潮一样涌来。',
 d:'一种黑色的娃娃，数量多到十几万，像在地上奔涌的黑潮。它们冲向银光闪闪的湖上那座用冰造的“冰镇”，这一次尔什民没有逃，拿着步枪站在冰屋上开火。琳用“光墙”留出缺口，把大部分娃娃引进坑里、引到立蝎的国度：地下隧道狭窄，人海战术不管用，立蝎挥着刃化的肢体一群群地砍。特别的娃娃穿着衣服，能让头颅飘起来，会用自己造的微型枪械远距离攻击，还懂得针对琳。天空中出现了一幅越来越大的“画”，画里是无数的脱骨娃娃；琳要找的是“画的核心”。\n它们只认得绝望：维罗尼卡让自己充满绝望，娃娃就把它当成环境的一部分。光球中心的巨大尔什民体内困着许多意识，不断分裂出骨架变成娃娃；扎满树根的黑球里装着从灭亡空间收集来的“绝望”，琳一碰就炸开，娃娃们只是跪在四周守着。因为它们拖住了不可预见之地的成长，才被叫作“虚空的瘟疫”。',
 ch:'卷七《不太熟悉》《头》《捕捉@37》《画》《内部@44》《画中》', rel:['dr_hope']},
{id:'dr_lastland', n:'最后之地', c:'地理', m:'dream', r:'dr11', e:[11], t:.99, off:[-60,40,-90], k:'island', kp:{r:44,c:'#e8c86a',c2:'#b8903a'},
 s:'它们把这里叫做最后之地：最后的希望，也是最后的光。',
 d:'尔什民的希望空间，它们管这里叫最后之地：最后的希望，也是最后的光。穿着奇妙服饰的尔什民把维罗尼卡带到建在金色平原上的家园——一路的草地都是绿的，只有城镇四周的草长成了金色。房屋多在几十米高，白色、像塑料做的，有金字塔形、螺壳形，还有两个方块用尖角叠在一起的形状；街上的居民大多穿着银色或金色的衣服，好奇地打量着维罗尼卡。“脱离猎手”组织猎杀的不是脱离者本身，而是为了它们的肉。还有一个只有数百成员、缅怀过去的小组织“感叹会”。',
 ch:'卷七《最后之地》《猎物》《感叹》《特殊的脱离》', rel:['dr_hope','c_veronica']}
);

/* 卷三：尔什 */
window.WIKI.push(
{id:'ex_planet', n:'尔什', c:'地理', m:'erxi', r:'ex_eu', e:[7,8,9,10,11,12,13], ll:[22,-10],
 s:'尔什民（阿特兰的后代）的故乡——它本身是一颗活着的巴士，一颗“爱好研究的巴士”。',
 d:'尔什民管巴士生物叫“超级星球”。尔什有自己的神经系统，“诺”是它在地面上的化身。很久以前尔什离开了原本的星系，两极的冰雪开始融化，大量冰水化作汹涌的海啸席卷世界，北极的冰洋变成了新大陆。它针对米德加尔特准备了一个很久以前就开始的大计划；它被月亮“分解”过，进过凝固虚空，在“旅行空间”里漂泊，还想起了自己曾直面过创造者的本质。\n很久以后，尔什漂得最远的那部分思维在所有虚空的最深处被琳找到。它本来不打算回到尔什身上，尔什认出它之后，也犹豫要不要把它收回；最后那部分意识在打开新虚空的任务里消散，剩下的成了琳的一部分。得知新的虚空打开，尔什决定造一个分身去探索：一颗地表只有荒漠、没有任何生物的翻滚者——它想看看在新虚空里能遇到多少生物、又能载上多少。琳和莎琳坐在它的一座小山上，它驶向了巨大的出口。',
 ch:'卷六《沙尘中的历程》《召唤错误？》《大体的过程》《回忆@3207》卷八《相遇》《转移》《最后的瞬间》', rel:['ex_nuo','ex_atlan','ex_moon','ex_frozen','ex_travel','v_erxi','j3_farnuo','j3_end']},
{id:'ex_atlan', n:'阿特兰的历史', c:'文明', m:'erxi', r:'ex_eu', e:[7], ll:[36,16],
 s:'尔什民远古的样子：中世纪的种族，国王、精锐、原族与猛犸。',
 d:'琳在回忆结晶里扮演过一个王室成员：一场灾难来临，国王让两群阿特兰躲开——一群是和“琳”一同出海的精锐，另一群执行“海居计划”移居深海。“神”毁灭了国度；尔什教团的阿特兰拿着弩箭追来，琳扮演的角色被射穿了头……在虚空中漂泊的阿特兰一直在找“先祖之地”，一个阿特兰去了玛尔斯，立刻从潜意识里觉得：这里不是。',
 ch:'卷六《真神与假神》《海居》《逃脱行动》《记忆的古代》', rel:['ex_haiju','v_atlan','v_mars','ex_planet']},
{id:'ex_haiju', n:'海居计划', c:'事件', m:'erxi', r:'ex_sea', e:[7], ll:[-6,-28],
 s:'一群信任国王的阿特兰，移居到了深海里。',
 d:'这个计划变数太多，死得也多，所以国王把自己的孩子送去了安全得多的出海计划。这么看，它们的祖先有不少都躲过了那场灾难。——后来的尔什上，还有古老的头足类自称“最接近尔什的生物”。',
 ch:'卷六《真神与假神》《海居》', rel:['ex_atlan','ex_closest']},
{id:'ex_ability', n:'能力者', c:'文明', m:'erxi', r:'ex_eu', e:[7], ll:[30,40],
 s:'感染特殊微生物、体能被强化，代价是寿命很短。',
 d:'很久以前，尔什有过一个计划：把一些有特殊能力的居民送到玛尔斯来生活，这些经过改造的能力者能适应那里的环境——地下的“岩皮”可能就是它们。在尔什民的城市里，能力者被当成影视里的英雄：挨了一梭子子弹也毫发无伤，赤手空拳就把劫匪按倒在地，还总要得意地啰嗦一堆话。社长是尔什上的一个角色，它每晚“梦游”，梦里的自己会写下接下来的计划，其中之一就是成立一家专门制造“英雄”的能力者公司。',
 ch:'卷六《一种生物@740》《岩皮的记忆》', rel:['v_mars','v_yanpi']},
{id:'ex_closest', n:'最接近尔什的生物 · 变幻蛸', c:'物种', m:'erxi', r:'ex_sea', e:[9], ll:[-12,-35],
 s:'一种非常古老的软体生物，用尔什民的分类算是头足纲。',
 d:'海底的洞穴里，回荡着海洋的气味，爬满了非常古老的海生物；一个声音说，它们是被留下来的。它们自称‘最接近尔什的生物’，是一种很古老的软体类，按尔什民的分法属于头足纲。比起尔什常见的章鱼，琳觉得它们更像绒球上的古鱿。有些尔什民认为章鱼智力很高，限制它们的不是智力，而是寿命。它们靠变换体色交谈，还能改变形状，琳叫它“变幻蛸”。',
 ch:'卷六《地深之处》《最接近的生物》', rel:['ex_haiju']},
{id:'ex_ameirun', n:'阿美润根', c:'文明', m:'erxi', r:'ex_am', e:[8,9], ll:[38,-100],
 s:'过去就很发达，现在也还是尔什最发达的地区之一。',
 d:'南极那边和“羽齿”交易得来的东西全被运出去，卖到了这里，价格大概能买几千万箱苹果——苹果在尔什是很普遍、很便宜的水果。英雄塑造计划后来也搬到这里继续进行，整片大陆都由形形色色的超级英雄守着，据说连足以毁掉虚空的异星生物都败在它们手下。',
 ch:'卷六《贩卖？》《继续飞》', rel:['ex_hero','ex_kong']},
{id:'ex_hero', n:'英雄塑造计划 · 超级英雄', c:'文明', m:'erxi', r:'ex_am', e:[8,9], ll:[36,-94],
 s:'广告上写着：想当漫画里那种有超能力的英雄吗？来这里就行。',
 d:'实验室的研究员提出了‘用尔什民的大脑操纵巴士生物的身体’的可能性，这就是英雄塑造计划——一种为了制造特种士兵的计划：世界已经统一，大战消失了，小冲突却还常有。英雄总部的大厅里：‘今天抓了几个坏蛋？’它报告说一共六个，逃掉的那个也抓回来了，还踢了一脚，应该没死。后来这些英雄在凝固边缘变异成了“巴士侠”。',
 ch:'卷六《英雄？@1629》《英雄总部》《适应》', rel:['ex_ameirun','ng_busman','ex_mother']},
{id:'ex_south', n:'南极大陆', c:'地理', m:'erxi', r:'ex_s', e:[8,9,10,11,12], ll:[-76,10],
 s:'曾被厚重冰雪覆盖。尔什离开原来的星系后，冰开始融化。',
 d:'大量冰水化作汹涌的海啸席卷了整个世界。冰化之后，这片大陆上出现了很多新物种——尔什民原以为它们一直躲在冰层下，后来发现了大空洞，才认为它们可能都是从洞里钻出来的。这里有一号基地、研究站和机械岛，偷猎者集团也在这里活动。',
 ch:'卷六《极南之地》《普通地交流》《继续@1615》《黑色的环境》', rel:['ex_kong','ex_mother','ex_nautilus']},
{id:'ex_kong', n:'南极大空洞', c:'地理', m:'erxi', r:'ex_s', e:[8,9], ll:[-80,40],
 s:'一个可以通往地下深处的巨大洞穴，还在探索之中。',
 d:'琳觉得它可能是尔什特意制造出来的。坐“引力电梯”下去，是漆黑的丛林和“一号基地”；导游欢迎大家来到一号基地，说这里可以好好欣赏地下风景。基地附近游荡着一只“试验失败的怪物”——‘严格说，试验算是成功了，只是控制上出了点问题。’长鸟毛的“羽齿”这阵子在学着自己种苹果树。',
 ch:'卷六《大空洞》《电梯》《黑色的环境》《基地@1623》《移动@1501》《羽毛与交易》', rel:['ex_south','ex_ameirun']},
{id:'ex_mother', n:'巴士生物母体', c:'物种', m:'erxi', r:'ex_am', e:[8], ll:[-76,-34],
 s:'英雄总部地下实验室的水槽里，一头浮游着的十多米长的白壳生物，四条节肢外加一条触手般的软肢，远看有点像大象。',
 d:'个体从母体产出时大约十厘米，被放进特制的培育液里成长。在它的信息里，尔什民得到了“泥潭”的坐标：一颗直径三千公里左右、有类似尔什大气的世界——它们为此准备了很久。特丽提研究的“暗藻文明”资料也来自一个巴士生物。',
 ch:'卷六《成长过程@1636》《想去的地方》《文明和泥潭》', rel:['ex_hero','ex_teliti','v_anzao']},
{id:'ex_tiangong', n:'天宫市 · 天宫学院', c:'文明', m:'erxi', r:'ex_eu', e:[8,9,10,11,12], ll:[45,12],
 s:'尔什民的“巅峰”：发展程度、外观景色，和几乎为零的犯罪率。',
 d:'学院训练精锐，学生大多接受过基因强化，未来从事擅长领域的工作。琳的间谍以“维罗尼卡”之名入学，和比露一起去过丛林的实战训练、北极场景环境模拟场（还没开放，被赶了出来）。后来学院被“异常跳跃”带进了凝固边缘，又回到原位；研究团在学院地下发动袭击。',
 ch:'卷六《天宫》《原始的发现》《那让我们欢迎新生》《模拟场所》《相关之物》《训练》', rel:['c_veronica','c_bilu','ex_teliti','ng_academy','ex_research']},
{id:'ex_teliti', n:'特丽提', c:'角色', m:'erxi', r:'ex_am', e:[8,9], ll:[44,14],
 s:'穿白色衣服的研究员。琳的间谍自称是它远房亲戚的孩子。',
 d:'特丽提说，这是它远房亲戚的孩子，自己跑来这里还没找到住处，所以先带着。维罗尼卡这个名字，就来自特丽提那位真正的远房亲戚。特丽提研究的是远古的“暗藻文明”。它所在的地方大规模招募“英雄”，收了昂贵学费，广告说只要肯练谁都能当；其实全看大脑是否“适应”，测一下就知道。英雄的身体来自实验室深处一头像大象的巴士生物母体：外壳坚固、什么温度都扛得住，定期在体内造出没有繁殖能力的个体。它的神经只用来储存记忆，并把过去文明和“泥潭”的信息发给尔什民。',
 ch:'卷六《适应》《天宫》《文明和泥潭》《撤离@2004》', rel:['c_veronica','ex_tiangong','v_anzao']},
{id:'ex_wushou', n:'蜈手', c:'物种', m:'erxi', r:'ex_eu', e:[9], ll:[46,10],
 s:'形状、大小都像手掌，却是蜈蚣的近缘。',
 d:'形状和大小都像一只手掌，却是蜈蚣的近亲，所以琳叫它“蜈手”。几只蜈手偷偷爬进电梯，跳到比露背后咬了它；和别的蜈蚣一样它们有毒，毒素还能让生物僵化，于是比露僵在原地，任背上的几只慢慢啃——这次离死还比较远，不过毒素迟早会影响呼吸。被治好的比露盯着间谍手里挣扎的那只，发誓要把它们全都捏碎。',
 ch:'卷六《手和长》', rel:['c_bilu']},
{id:'ex_xiafeng', n:'峡风要塞', c:'文明', m:'erxi', r:'ex_n', e:[8,9], ll:[78,-24],
 s:'招牌上写着：峡风要塞，冒险、娱乐、怀旧，一次全有！',
 d:'招牌上写着：冒险、娱乐、怀旧，一次全有。有人问，为什么要在一块刚冒出来的大陆上怀旧？回答是：这个不用在意。整座小镇特意照着从前的样式建造：灰色砖块铺的道路，低矮的石质房屋，最高的建筑是挂着一口金色大钟的钟楼；街上没有常见的交通工具，只有长满毛的大型生物拉着木车；写着“酒吧”的屋前，木门在寒风里晃个不停——的确挺怀旧的。这片大陆曾经是冰洋。',
 ch:'卷六《曾是冰洋的大陆》', rel:['ex_north']},
{id:'ex_north', n:'北极大陆', c:'地理', m:'erxi', r:'ex_n', e:[8,9,10,11,12], ll:[80,20],
 s:'曾是冰洋的大陆。它的地下深处，是一片广阔的荧光丛林。',
 d:'曾是冰洋的大陆，地下深处是一片广阔的荧光丛林，到处是发光的植物，各种生物在林子里跑来跑去。这里的生物大多是尔什或绒球那边的亚种，“白星”却两边都不像：全身闪着洁白的光，样子和青年尔什民差不多，没有五官和毛发，头上长着许多像头发的触手，跑得飞快。据说它在“市场”上能卖出很高的价钱，所以一队偷猎者尔什民一直在黑暗里追它。在一个史前生物干枯的躯干里，琳找到了一些细胞——那是一个早已干枯的创造者。',
 ch:'卷六《白色的》《树上》《大陆？》《创造镜像》', rel:['ex_baixing','ex_xiafeng']},
{id:'ex_baixing', n:'白星', c:'物种', m:'erxi', r:'ex_n', e:[8,9,10,11], ll:[76,32],
 s:'创造者造出的白色生物：形似青年尔什民，无五官，头上长着像头发的触手。',
 d:'北极大陆地下漆黑的荧光丛林里，偷猎的尔什民追着一种浑身闪着洁白光泽、在黑暗中也很醒目的生物，叫它“白星”，据说在市场上能卖出很高的价钱。它像灵长类，体形和青年尔什民差不多，却没有五官和毛发，头部长着许多触手似的结构，像一头头发；它跟尔什或绒球的任何生物都不近缘。白星最早的记忆，是从树上一朵“花”里钻出来——那花和别的植物毫无关联，只是样子像花；刚出生时它形似蜥蜴，随后在丛林里游荡捕猎。它本来几乎只吃植物，偶然吃到高智力生物的脑、智力随之上升后，就专门袭击高智力生物、只吃它们的脑，身体还会随所吃的对象改变：上上代吃多了蜥蜴般的生物，后代便像蜥蜴；丛林里的骸龙类被它吃到几乎灭绝，之后只剩进来偷猎的尔什民可吃，于是如今的白星长成了尔什民的模样。它坐过的地方会留下细胞，剑蚤把这些细胞带到树顶，攒到约一毫米大时便长出新一代；上一代被抓走，下一代就接替它。被捕的白星被送进北极某处的研究所接受检测。琳把一具早已干枯的创造者躯干里的细胞聚在一起，它们同样先长成花、再生出幼仔，长得更快，而且一出生就带着完整记忆——这便是“创造者镜像计划”：那具躯体里残存着模糊的意识，被放到北极后变得清晰，一心只想“自由活动”。\n米德加尔特体内的天宫市，“天宫大殿”下方像地下停车场的空间里也藏着一个白星。它造出大批机器民，让它们攻击地面上的尔什民，好统治它们；它拆掉引力引擎改造成别的东西，还让一名下来调查的研究团成员染上了寄生物。被间谍维罗尼卡追赶时，它攥着手雷边逃边喊“要炸了”；它的拳头能突然张开成满是锯齿的嘴，体内有强大的免疫系统和会爆炸的微生物，间谍后来就留下这些微生物培养成炸弹。它早先造了六十一台模仿家具家电的智能机器开“讨论会”，又在城里各处藏了几百台伪装成普通家电、都想毁灭世界的机器，袭击学院的学生；有的白星扮成学生，挥着一把被它换上自己智能系统的镰刀。它把脑细胞拆成许多份、散成肉块躲进城里，为的是送出情报：白星遇到未知区域，就会向创造者传递消息。\n米德加尔特里拍电影的尔什民之间，也混着一个伪装成尔什民的白星，它让感染了它病毒的民众设法救它；它还会改造湖中用来和创造者交流的微生物的核信息，借它们“说话”。白星是历代创造者从未造过的生物，消息传到三颗卫星上的创造者那里，回收会收集了许多白星干尸，也想把活的那个弄出来；一个创造者断言白星是“错误”：创造者造出的任何生物都不该有资格解读微生物信号，它为此暴怒。白星其实是尔什上的创造者依照变形生物的核信息制造的。\n在头颅形空间站由系统和研究团修建的巨型监狱里，研究员用高温、低温和各种药物折磨被抓来的白星，想激发它的“传承反应”；它一度只发出“死”的脑波，一发怒，穿着防护服的研究员便捂着头倒地。琳把其他囚犯的尸体分解，分一部分养分给它，它就此变异：长出四条手臂、下身变大，最后成了七米多长、覆盖坚韧外壳的巨兽，挣断绳索出逃；数量百倍于它的金属军队互相误伤。它走到“一号”与变形生物那里，传承反应让它脑中涌出古老的信息——当年有个陌生生物帮变形生物造出聚集闪光生物的炸弹，却失败了——它反复喊着“失败的作品”。最后它背着变形生物撞开监狱的门，登上穿梭机离开。\n很久以后，细线把一个白星放进返乡之道，造出它的制造体。它一进来就完全适应了自己的身体，杀掉了大批同期的制造体，也是它解决了吞并无数制造体的“融合体”；随后它要去不可预见之地，却在通路里待得太久，失去记忆迷了路。琳在通路里发现它把身体拧成一根十多米长、一米粗的触手，救下它后与它结盟；它一路捕猎刚进来的半透明躯体，追杀如极光般闪烁、一米多大的方块状原住民，在满是雕像的领地里引发连锁爆裂，又跟着琳和零来到要求交出一半躯体的凤凰面前。细线的“造物计划”，就是用自身的核信息造出白星，再由白星造出无数造物；平静世界附近漂着大群无脑的白星，其中一个健谈的自称管理“失败品”，深海城堡里也有白星专门记录这场创世。骨头般的生物世代相传，白星是“扭曲”的代言者，能帮它们启动数据球而进化。',
 ch:'卷六《白色的》《树上》《白星的生态》《创造镜像》《熟悉的白色》《智能的源头》《要炸了》《家具讨论》《家电和学生》《情报》《熟悉的@1865》《有点不同》《特殊的造物》《传承反应》《有记忆》《出逃》《细胞内的传承》《离开@1953》《止步的生物》《光之原住民》《过去的通路》《融合体》《判定》《整体计划》《仪式》', rel:['ex_north','ex_tiangong','c_veronica','c_bilu','v_huishouhui','v_headstation','ex_research','v_xixian','bk_home','dr_zero']},
{id:'ex_fleet', n:'尔什舰队 · 湮灭舰', c:'文明', m:'erxi', r:'ex_eu', e:[8,9], ll:[20,-50],
 s:'湮灭舰：自杀型的舰船，装着威力最强的爆炸物和扭曲引擎。',
 d:'它由机械民操控，用来奇袭、摧毁大规模目标。尔什民的战术是先在蒸腾者之城的地面轰出坑，再让湮灭舰进坑炸掉整座城市——就算炸不掉那一千公里的整座城，至少也能掀掉它一层皮。云层密布的天空里，一艘艘庞大的物体从地表升起，穿过大气飞向虚空。',
 ch:'卷六《外部的轰击》《集结与袭击》《结束和启程》', rel:['v_zhengteng','ex_moon']},
{id:'ex_research', n:'研究团', c:'文明', m:'erxi', r:'ex_eu', e:[9], ll:[40,22],
 s:'尔什民精英组成的秘密组织，相信尔什没有抛弃它们，最终要摧毁米德加尔特。',
 d:'尔什研究团是由世界各地精锐组成的庞大团体，许多成员曾和尔什交流过，也知道尔什造出的那些空间。它们坚信尔什从未“抛弃”尔什民——原先那颗尔什只是个空壳，并不是真正的恒星巴士——只要找对方法就能回去。米德加尔特分解了假尔什、把尔什民丢进管道后，一些边缘空间不断膨胀，把管道里的尔什民都吞了进去；研究团认定这是尔什设下的“空间陷阱”，是通往真正尔什的路。天宫学院里有它的核心成员，也有帮学院飞行的边缘成员；途中它忽然改了主意，要毁掉学院：用投石器抛出装满生物、自身就能飞行的笼子，制造礁石之类的袭击，切断学院与传送器官的连接让它坠到地面，还打算杀光所有师生，连同那些边缘成员。一名在天宫市地下调查引力引擎的成员，遭遇白星后被感染。\n在虚空中的头颅形空间站里，研究团很出名，只是对外叫“虚空探索发展综合公司”。空间站的系统曾暗中联络研究团高层，以闪光生物文明的技术作交换，让它们替自己隐瞒存在：后来的挖掘队挖到的东西都交给研究团研究，并被告知属于别的文明。系统又建议把散在城中的小监狱合并成一座巨型监狱统一关押、审判罪犯，研究团同意并一起建造，监狱兼作实验室和军事要塞，实际上几乎全由系统管理。空间站遇险时，研究团成员用护甲接通遗迹建筑，想刺激系统启动引擎躲开危险，好救下来不及撤离的民众。\n回到尔什民的世界后，研究团常常不亲自出面：它勾结恐怖组织，去调查拥有“高层次连接”能力的维罗妮卡；它的成员胸前戴着团徽，乘自动驾驶的直升机来到丛林基地。它趁学生进入地底时袭击那些配备了闪光生物技术装备的转学生，借学生的惊恐把被恐惧吸引来的梦境生物收集起来，袭击点到即止、无人伤亡；它把这种梦境能量叫作“精神素”并细分出许多型号，用来制造梦境与真实生物的共生种，也就是“灵魂”。它经营着“虚空游乐场”，豢养有智慧的鸟类，一只鹅说是它们许诺鸟类也是智慧生物的一份子；在一座城堡里，它像国王和贵族一样统治着一群有中世纪思维的尔什民卫兵，游乐场的计划失败后便命令卫兵打扫城堡，匆匆撤走。\n在研究团的“超级生物档案”里，米德加尔特被定为极度危险的生物：它会攻击文明、分解翻滚者、制造巨大的虚空漩涡，行为难以捉摸。研究团的“最后一步”，就是把“那根管道”彻底毁掉。它备有能把对手分解成多块、分别放进不同空间的“裂解”，阻挠器官运转的“遮蔽”等武器；在管道头部的爆炸却一次次被转移偏离，于是它动用了鹅——某种梦境能量能启动基地里埋藏的交通工具，那就是鹅的梦。此后它的探索舰断了联络，那只鹅体内的能量也消失了。研究团的据点纷纷撤离，一个原本与它有往来的犯罪集团转而袭击与它相关的一切；它留下的试验品——被改造得几乎没有智力的干瘦尔什民——从笼子里跑进城市，它的基地、战舰和试验生物不断闹出新闻，留下的物品还帮着神之眼把意识连接到民众身上。原来整个研究团接到命令：逃出尔什的监控，离开这个世界。它为成功逃离的队伍准备了宙螺——一种六百多米长、像箭石的虚空生物，习惯飞往有细胞生物居住的世界，死亡时全身会迅速崩溃爆炸，威力堪比“B—FM”聚变弹。研究团还有一套记忆储藏系统：成员的部分记忆上传到虚空中的堡垒分部，分部定时向成员下达任务，任务记忆用过即清除再送回。它的探索队大多临时组建、事毕解散，只有零号探索队从未解散，专门寻找尔什偶尔发来的“尔什坐标”——那其实是一串串传送坐标。',
 ch:'卷六《认识@1810》《研究团体》《具体目标》《古怪@1829》《空间站@1929》《它们的过去》《监狱@1941》《试图拯救》《连接体》《研究团民》《一个计划@1980》《收集顺利》《想要有灵魂》《那个计划》《实验场所》《摧毁的步骤》《武器@2000》《见到自己》《起飞@2005》《收藏的队伍》《新闻》《离开这个世界》《进一步》《捐赠？》《坍塌中》《阻止自杀》', rel:['v_midgard','ex_tiangong','v_headstation','v_shanguang','c_veronica','c_bilu','ex_baixing','ex_birds','v_zhouluo','v_shizu']},
{id:'ex_clown', n:'电视机里的小丑', c:'角色', m:'erxi', r:'ex_am', e:[9], ll:[32,-84],
 s:'一大群恐怖分子的指挥。“改变这个世界……改变我们的命运……”',
 d:'房间尽头有一台很古老的电视机，不断回放着一个小丑的影像，翻来覆去说着要“改变命运”。比露戳了戳屏幕没反应，才认出这是老式电器。琳绕到背后一测：电视本身就是小丑的本体，里面是复杂的智能机械，和比露的闹钟用同一种结构，两者一接就能互读数据。原来它是那座空间站系统的一小块，没继承全部记忆，只带着一点性格——比如爱折磨囚犯。恐怖分子都听它指挥，但它并不是老大，是某个首领偶然捡来出主意用的。它说维罗尼卡是“高层次连接体”，能连上更高层次的世界。‘它从很远的虚空来，以前大得能控制万物，现在嘛，只是一台电视机。’',
 ch:'卷六《连接体》《命运？》《算是熟悉》', rel:['c_veronica']},
{id:'ex_jiaojing', n:'脚鲸', c:'物种', m:'erxi', r:'ex_sea', e:[9], ll:[-12,-142],
 s:'让鲸类长出手脚、又保持庞大体型的计划生物。',
 d:'顺着冲上海滩那头鲸鱼的记忆，间谍和比露来到尔什民的海底。外面珊瑚铺满海床、鱼群成片，基地里却只剩冷冰冰的墙和发浑的空气，满是尔什民管它叫“腥臭”的味道——这是研究团的海洋生物合成研究所，研究把尔什民之类的陆地生物和海洋生物的核信息混在一起。脚鲸就是这里的计划：通过调控细胞核信息，让鲸鱼“返祖”长出手脚，又保持庞大体型。最初并不顺利。后来一头庞大的脚鲸把总管办公室的墙撞穿，海水涌入，整个基地就此被淹没。',
 ch:'卷六《鲸鱼》《离开这个世界》《最后的准备》', rel:['ex_planet']},
{id:'ex_moon', n:'尔什的月亮', c:'地理', m:'erxi', r:'ex_sea', e:[9], ll:[0,60],
 s:'月亮上出现了建筑，凝固生物的大军从那里涌出。它向尔什伸出了桥梁。',
 d:'尔什舰队与凝固生物在虚空中激战，它们终于找到了：敌军就是从那里冒出来的。湮灭舰在月球上爆炸，淹没了刚出现的建筑。月亮离尔什还不到一万公里，伸出的桥梁足以填满这个距离——然后桥断了。那是“工程地点”的月亮。',
 ch:'卷六《月亮》《成功？@1716》《俘虏与月亮》《消失@1719》', rel:['ex_split','ex_fleet']},
{id:'ex_split', n:'尔什被分解', c:'事件', m:'erxi', r:'ex_eu', e:[9], ll:[10,0],
 s:'那道光是什么？——很多尔什民最后想的就是这个。',
 d:'刺眼的光柱从卫星表面射来，舰队在恐惧中躲避；虚空里飘散着无数粉末，它们原本是战舰、护卫机和导弹。地面上的居民大多抱着日常的心态，还惦记着手头的事。“预言里的末日，就是这个？”“尔什被分解了……消失了？”后来尔什回到了本来的星系，民众又过上了正常的生活。',
 ch:'卷六《那是什么光》《最后的战术》《分解@1720》《难以置信》', rel:['ex_moon','dr_doom']},
{id:'ex_frozen', n:'凝固的尔什 · 光之道', c:'事件', m:'erxi', r:'ex_eu', e:[9], ll:[38,40],
 s:'尔什被凝固了。只有一条一百公里长的街道上，数以千万计的炉火从天而降。',
 d:'琳和诺在一片漆黑中穿过被凝固的街道和地铁站，固定不动的尔什民之间，偶尔有凝固生物在啃食东西。“光之道”照亮了建筑，驱散了漆黑，又一点点消散，只剩十多米宽。南极的“反凝固发生器”启动时，整个南极像迎来了白昼。一段时间后，凝固慢慢解除——从小的东西到大的东西。',
 ch:'卷六《迷途之地》《车厢》《风暴与光之道》《消散的光》《明亮的大陆》《阻止@1344》', rel:['ng_luhuo','ex_nuo','ex_nautilus','ex_niuyao']},
{id:'ex_nautilus', n:'鹦鹉螺号 · 噬光农场', c:'琳的造物', m:'erxi', r:'ex_s', e:[9], ll:[-84,4],
 s:'凝固飞行器的试作品，钻进了柔软的“噬光农场”。',
 d:'诺说噬光农场不过两三米厚，鹦鹉螺号却往下钻了差不多三百米，四周还是没完没了的软物质，时不时闪一下光芒又熄灭。农场之下是冰原，冰原下有那个装置的碎片。鬼火后来给它涂上了新的涂装；它在凝固虚空里飘浮，用触手缠住凝固生物的残骸，提取强效的反凝固成分。',
 ch:'卷六《凝固飞行器》《农场之下的冰原》《围起来》《骨头@2199》《涂层》', rel:['ex_frozen','ng_guihuo']},
{id:'ex_niuyao', n:'扭腰城', c:'文明', m:'erxi', r:'ex_asia', e:[9], ll:[38.5,101],
 s:'一座居民相当多的尔什民城市，算是最发达的之一。',
 d:'一座居民相当多、算是最发达之一的尔什民城市。它原本在尔什的‘分身’上，被管道吞噬后，碎成大块贴在了管道壁上。后来鹦鹉螺号在凝固虚空里飘过它的上空：街道空荡荡的，交通工具都还在，一个居民也没有。琳把触手伸进一栋大楼，发现办公室里的影像装置还开着。',
 ch:'卷六《旧时代的碎块》', rel:['ex_frozen']},
{id:'ex_nuo', n:'诺', c:'角色', m:'erxi', r:'ex_eu', e:[9,10,11,12,13], ll:[42,2],
 s:'代表尔什的存在——尔什民模样的化身。',
 d:'‘我管它叫炉火。’诺带琳认识凝固虚空，在一片纯粹的漆黑中一起飘浮，跳进广阔的峡谷。它钻进“脑根”让古战舰活过来；在战争巴士地下六十六层，它用手在黑色柔软的地面上做“手术”，把一部分掰开提取出来。有一次，一个两米五高的尔什民站在湮灭舰上，把诺的脑袋砸碎了。\n碰撞之后，在计算装置推演的未来里，尔什在寂静之河失踪，琳找到坐在无实体丛林空地上的诺：它怀疑不可预见之地、凝固虚空和正常虚空原本是同一个，自己也许诞生在最早的虚空里，正用荒漠世界里残存的梦境能量做试验。真实的碰撞中，诺陪琳追查失踪现象，一进失踪隧道就和尔什断了连接，在古战场的地下等到了琳；它读得懂虚空本源那些黑影里的信息，在吞噬之域里想起了尔什思维的来历，还坐着绒球救生舱躲过了尘埃战舰的解体。\n卷八的最深之地里，还有一个以诺的模样出现的存在：它是尔什走得最远的那部分思维，和琳一起把创造之海的数据引进虚空之眼的核心，最后在打开新虚空的任务里消散（见“诺（最远的思维）”）。',
 ch:'卷六《炉火》《落地》《起航@2214》《新生物》《接近@2328》卷七《变化@395》《河》《测试》卷八《所有结果》《迷途》《感觉》《启航》《传递》《另一部分》《聚集地》卷八《相遇》《最后的瞬间》', rel:['ex_planet','ng_luhuo','v_warbus','j1_jisuan','j1_jijing','j1_tunshi','j1_benyuan','j1_guzhan','j3_farnuo']},
{id:'ex_travel', n:'旅行空间', c:'现象', m:'erxi', r:'ex_eu', e:[10,11,12,13], ll:[0,-20],
 s:'它们解释说，虚空越来越危险，所以它们的世界要带着大家去一个新的安全地方。',
 d:'公告说，虚空越来越危险，我们的世界要带大家去一个新的安全地方；在意也没用，请大家照常过日子。这个空间是琳和尔什反复调整后做成的，比尔什本身还大，飞出去约一万公里才碰得到边缘；底部有一座三百多米宽、像岛屿一样的移动装置，再加上调节装置，让地表保持尔什民能适应的环境。印加虫群分出约十亿只同行，一部分待在沙漠和丛林里，一部分住在自己用大型运输虫拼成的虫形空间站里。尔什带着大家绕过空间风暴前进。它后来想起：当初造“混合虚空”并不是为了做武器，而是想造一个够异常的空间，被“弹”出正常虚空，去外面远行。\n尔什后来还想起，自己很早就做过一模一样的计划，只是当时的目的地是秩序之域——等那里的金属尔什民消失后，搬过去住。\n卷八里，琳的“空间舰”就像缩小的旅行空间：细胞搭乘在微型空间里，能直接穿过敌舰的外壳；记录区储藏空间的入口也像旅行空间一样一直在移动。',
 ch:'卷六《旅行的空间》《停止@2815》《记录@2840》《活动@2844》《侵入@3274》卷七《过去的旅行》卷八《准备》《穿透》', rel:['ex_planet','v_hunhe','ex_endsign','v_haishen','j1_xisui']},
{id:'ex_crack', n:'天空的断裂现象', c:'现象', m:'erxi', r:'ex_eu', e:[10], ll:[28,-6],
 s:'官方说，调查显示这种‘断裂现象’很稳定，没什么大危害，请大家别担心。',
 d:'比露急得直嚷，非要维罗尼卡同学说清楚：到底是什么变化，怎么一下子就没了？后来裂痕里落下了凝固物质构成的爆炸物；泥浆在城市里到处挖掘，“全体市民紧急撤离！”',
 ch:'卷六《向着奇迹之星》《红色亚种》《神器？》《奇迹的目标》', rel:['v_nijiang','c_bilu']},
{id:'ex_endsign', n:'末日现象', c:'事件', m:'erxi', r:'ex_eu', e:[10], ll:[20,30],
 s:'凝固慢慢解除，然后是热浪、地震与巨大的裂痕。',
 d:'比露问维罗尼卡同学：这就是末日现象吗？要不要像平常那样，华丽地把它解决掉？扭曲管理者的攻击在旅行空间里发作：大量特殊传送能量把一些尔什民弄疯了，强效凝固封住了整个旅行空间，天空陷入黑夜，失控的货车冲上街道。诺、维罗尼卡和比露追着一个直径一米多、会飘浮的圆盘——管理者和平静集合体的意识就藏在里面。凝固慢慢解除后，尔什却不再稳定地调节气候：各地极冷极热，气温逼近四十度，地面裂开吞没公路；诺冷冷地说，死了就死了，不值得在意。琳在巨坑里造了个小传送器，想偷偷碰一下尔什的神经，看它到底出了什么事。',
 ch:'卷六《末日现象》《阻止@2818》《追击@2830》《可能性@2831》《继续@2835》《多个生物》《炎热》《活动@2844》', rel:['ex_nuo','c_bilu','c_veronica','a5_guanli','ex_travel']}
);

